def garantir_lista_de_caminhos_de_politica(raiz: Path) -> None:
    destino = raiz / ARQUIVO_CAMINHOS_DE_POLITICA
    if destino.exists():
        print(LOG_LISTA_DE_POLITICA_EM_DIA)
