        'ERRO_TIPO = "{}: deveria ser {}"\n'
        'ERRO_ENUM = "{}: {!r} não está em {}"\n'
        'ERRO_CONST = "{}: deveria ser {!r}"\n'
        'ERRO_PATTERN = "{}: {!r} não casa com {}"\n'
        'ERRO_MIN_LENGTH = "{}: precisa de ao menos {} caractere"\n'
        'ERRO_MAX_LENGTH = "{}: passa de {} caracteres"\n'
        'ERRO_MINIMO = "{}: {} é menor que o mínimo {}"\n'
        'ERRO_CAMPO_OBRIGATORIO = "{}: falta o campo obrigatório {!r}"\n'
        'ERRO_CAMPO_FORA_DO_CONTRATO = "{}: campo fora do contrato: {}"\n'
        'ERRO_CAMPO_PROIBIDO = "{}: campo proibido neste contexto: {}"\n'
