        '\n'
        'ERRO_MOTIVO_DESCONHECIDO = "motivo desconhecido: {!r} (vale: {})"\n'
        'ERRO_DEFEITO_NO_SINTETICO = ("defeito na evidência sintética — corrija "\n'
        '                             "evidencia.py: {}")\n'
        'ERRO_ENTRADA_VAZIA = "entrada vazia — a etapa não devolveu evidência nenhuma"\n'
        'ERRO_NAO_E_OBJETO = "a entrada não é um objeto JSON de evidência"\n'
        'ERRO_JSON_QUEBRADO = "JSON quebrado: {}"\n'
        '\n'
        'ERRO_CONTRATO_ILEGIVEL = "não consegui ler o contrato em {}: {}"\n'
        'ERRO_LEITURA = "não consegui ler {}: {}"\n'
        'ERRO_STDOUT = "o stdout falhou: {}"\n'
        'ERRO_STDOUT_APOS_VALIDA = "evidência válida, mas o stdout falhou: {}"\n'
        'ERRO_STDOUT_APOS_ESCRITA = "evidência escrita em {}, mas o stdout falhou: {}"\n'
        'ERRO_DE_USO = "erro de uso: {}"\n'
        'PROBLEMA_ORDEM = ("argumento --ordem: {} fora de 1..99 (vira o prefixo de "\n'
        '                  "dois dígitos do arquivo)")\n'
        'PROBLEMA_CUSTO = "argumento --custo: não é JSON ({})"\n'
        'PROBLEMA_DIR = ("argumento --dir: vazio ou com quebra de linha — o caminho "\n'
        '                "impresso no stdout é lido linha a linha")\n'
        'ERRO_AMBIENTE_NA_ENTRADA = ("erro de ambiente ao ler --entrada {}: {} — nada "\n'
