        'ERRO_AMBIENTE_NADA_ESCRITO = "erro de ambiente — nada escrito: {}"\n'
        'ERRO_DE_AMBIENTE = "erro de ambiente: {}"\n'
        'OK_EVIDENCIA_VALIDA = "evidência válida"\n'
        '\n'
        'AJUDA_VALIDAR = "valida uma evidência contra o contrato"\n'
        'AJUDA_ARQUIVO = "caminho do JSON, ou - para stdin"\n'
        'AJUDA_DIR = "diretório-base das evidências"\n'
        'AJUDA_MATERIALIZAR = "escreve a evidência a partir do stdout da sessão"\n'
        'AJUDA_ENTRADA = "arquivo com o stdout da sessão; - = stdin"\n'
        'AJUDA_TURNOS = ("turnos que a sessão gastou (num_turns); opcional, "\n'
        '                "carimbado pelo código na evidência")\n'
        'AJUDA_CUSTO = ("custo que a sessão devolveu (total_cost_usd e usage), como "\n'
