        '               "código na evidência")\n'
        'AJUDA_SINTETICO = "escreve a evidência de etapa desligada/morta/teto"\n'
        'AJUDA_ESQUEMA_SESSAO = "o contrato enxuto da sessão, para --json-schema"\n'
        '\n'
        'DETALHE_EXIT = "exit {}"\n'
        'TESTE_ACEITA_RECUSOU = "ACEITA [{}]: recusou — {}"\n'
        'TESTE_RECUSA_ACEITOU = "RECUSA [{}]: aceitou o que devia recusar"\n'
        'TESTE_RECUSA_MOTIVO_ERRADO = "RECUSA [{}]: recusou pelo motivo errado — {}"\n'
        'TESTE_COMPORTAMENTO = "COMPORTAMENTO [{}]"\n'
        'TESTE_FALHA = "FALHOU: {}"\n'
        'TESTE_RESUMO_FALHA = "FALHOU: {} de {} casos"\n'
        'TESTE_RESUMO_OK = ("OK: {} casos — {} aceitos, {} recusados, {} de "\n'
        '                   "comportamento")\n'
        '\n'
        '\n'
        'def _casa_padrao(padrao: str, dado: str) -> bool:\n'
        '    if padrao.endswith("$") and not padrao.endswith(r"\\$"):\n'
        '        padrao = padrao[:-1] + r"\\Z"\n'
        '    return re.search(padrao, dado) is not None\n'
        '\n'
        '\n'
        'def _tipo_certo(tipo: str, dado) -> bool:\n'
        '    if isinstance(dado, bool):\n'
        '        return tipo == "boolean"\n'
        '    if tipo == "integer" and isinstance(dado, float):\n'
        '        return dado.is_integer()\n'
        '    return isinstance(dado, TIPOS[tipo])\n'
        '\n'
        '\n'
        'def _erros_de_valor(esquema: dict, dado, caminho: str) -> list:\n'
        '    erros = []\n'
        '    if "enum" in esquema and dado not in esquema["enum"]:\n'
        '        erros.append(ERRO_ENUM.format(caminho, dado, esquema["enum"]))\n'
        '    if "const" in esquema and dado != esquema["const"]:\n'
        '        erros.append(ERRO_CONST.format(caminho, esquema["const"]))\n'
        '    if "pattern" in esquema and isinstance(dado, str) \\\n'
        '            and not _casa_padrao(esquema["pattern"], dado):\n'
        '        erros.append(ERRO_PATTERN.format(caminho, dado, esquema["pattern"]))\n'
        '    if "minLength" in esquema and isinstance(dado, str) \\\n'
        '            and len(dado) < esquema["minLength"]:\n'
        '        erros.append(ERRO_MIN_LENGTH.format(caminho, esquema["minLength"]))\n'
        '    if "maxLength" in esquema and isinstance(dado, str) \\\n'
        '            and len(dado) > esquema["maxLength"]:\n'
        '        erros.append(ERRO_MAX_LENGTH.format(caminho, esquema["maxLength"]))\n'
        '    if "minimum" in esquema and isinstance(dado, (int, float)) \\\n'
        '            and not isinstance(dado, bool) and dado < esquema["minimum"]:\n'
        '        erros.append(ERRO_MINIMO.format(caminho, dado, esquema["minimum"]))\n'
        '    return erros\n'
        '\n'
        '\n'
        'def _erros_de_objeto(esquema: dict, dado, caminho: str) -> list:\n'
        '    if not isinstance(dado, dict):\n'
        '        return []\n'
        '    erros = []\n'
        '    for exigido in esquema.get("required", []):\n'
        '        if exigido not in dado:\n'
        '            erros.append(ERRO_CAMPO_OBRIGATORIO.format(caminho, exigido))\n'
        '    propriedades = esquema.get("properties", {})\n'
        '    if esquema.get("additionalProperties") is False:\n'
        '        sobras = sorted(set(dado) - set(propriedades))\n'
        '        if sobras:\n'
        '            erros.append(ERRO_CAMPO_FORA_DO_CONTRATO.format(caminho, sobras))\n'
        '    for nome, sub in propriedades.items():\n'
        '        if nome in dado:\n'
        '            erros += _erros(sub, dado[nome], f"{caminho}.{nome}")\n'
        '    return erros\n'
        '\n'
        '\n'
        'def _erros_de_lista(esquema: dict, dado, caminho: str) -> list:\n'
        '    if not isinstance(dado, list) or "items" not in esquema:\n'
        '        return []\n'
        '    erros = []\n'
        '    for n, item in enumerate(dado):\n'
        '        erros += _erros(esquema["items"], item, f"{caminho}[{n}]")\n'
        '    return erros\n'
        '\n'
        '\n'
        'def _erros_do_proibido(proibido: dict, dado, caminho: str) -> list:\n'
        '    if _erros(proibido, dado, caminho):\n'
        '        return []\n'
        '    if set(proibido) == {"required"}:\n'
        '        return [ERRO_CAMPO_PROIBIDO.format(caminho, proibido["required"])]\n'
        '    return [ERRO_ESQUEMA_PROIBIDO.format(caminho)]\n'
        '\n'
        '\n'
        'def _erros_de_combinacao(esquema: dict, dado, caminho: str) -> list:\n'
        '    erros = []\n'
        '    for sub in esquema.get("allOf", []):\n'
        '        erros += _erros(sub, dado, caminho)\n'
        '    if "if" in esquema:\n'
        '        casa = not _erros(esquema["if"], dado, caminho)\n'
        '        ramo = esquema.get("then") if casa else esquema.get("else")\n'
        '        if ramo:\n'
        '            erros += _erros(ramo, dado, caminho)\n'
        '    if "not" in esquema:\n'
        '        erros += _erros_do_proibido(esquema["not"], dado, caminho)\n'
        '    return erros\n'
        '\n'
        '\n'
        'def _erros(esquema: dict, dado, caminho: str) -> list:\n'
        '    desconhecidas = set(esquema) - SUPORTADAS - ANOTACOES\n'
        '    if desconhecidas:\n'
        '        return [ERRO_PALAVRA_DESCONHECIDA.format(caminho,\n'
        '                                                 sorted(desconhecidas))]\n'
        '    tipo = esquema.get("type")\n'
        '    if tipo and not _tipo_certo(tipo, dado):\n'
        '        return [ERRO_TIPO.format(caminho, tipo)]\n'
        '    return (_erros_de_valor(esquema, dado, caminho)\n'
        '            + _erros_de_objeto(esquema, dado, caminho)\n'
        '            + _erros_de_lista(esquema, dado, caminho)\n'
        '            + _erros_de_combinacao(esquema, dado, caminho))\n'
        '\n'
        '\n'
        'def carregar_esquema(caminho: Path = ESQUEMA_PADRAO) -> dict:\n'
        '    try:\n'
        '        return json.loads(caminho.read_text(encoding="utf-8"))\n'
        '    except (OSError, json.JSONDecodeError) as erro:\n'
        '        print(ERRO_CONTRATO_ILEGIVEL.format(caminho, erro), file=sys.stderr)\n'
        '        sys.exit(2)\n'
        '\n'
        '\n'
        'def _sem_comentario(no):\n'
        '    if isinstance(no, dict):\n'
        '        return {chave: _sem_comentario(valor) for chave, valor in no.items()\n'
        '                if chave != "$comment"}\n'
        '    if isinstance(no, list):\n'
        '        return [_sem_comentario(item) for item in no]\n'
        '    return no\n'
        '\n'
        '\n'
        'def projetar_para_sessao(esquema: dict) -> dict:\n'
        '    guia = _sem_comentario({chave: valor for chave, valor in esquema.items()\n'
        '                            if chave != "allOf"})\n'
        '    guia["required"] = [campo for campo in guia["required"]\n'
        '                        if campo not in CAMPOS_DO_CODIGO]\n'
        '    for campo in CAMPOS_CONDICIONAIS:\n'
        '        regra = esquema["properties"].get(campo, {}).get("$comment")\n'
        '        if regra:\n'
        '            guia["properties"][campo]["description"] = regra\n'
        '    return guia\n'
        '\n'
        '\n'
        'def _data_existe_no_calendario(quando: str) -> bool:\n'
        '    try:\n'
        '        datetime.fromisoformat(quando)\n'
        '    except ValueError:\n'
        '        return False\n'
        '    return True\n'
        '\n'
        '\n'
        'def validar_evidencia(dado, esquema: dict) -> list:\n'
        '    erros = _erros(esquema, dado, ROTULO_DA_EVIDENCIA)\n'
        '    if not erros and not _data_existe_no_calendario(dado["quando"]):\n'
        '        erros.append(ERRO_CALENDARIO.format(dado["quando"]))\n'
        '    return erros\n'
        '\n'
        '\n'
        'def agora() -> str:\n'
        '    return datetime.now().astimezone().isoformat(timespec="seconds")\n'
        '\n'
        '\n'
        'def caminho_da_evidencia(dir_base: str, trabalho: str, ordem: int, etapa: str):\n'
        '    pasta = Path(dir_base) / trabalho\n'
        '    padrao = re.compile(rf"{ordem:02d}-{re.escape(etapa)}-c([0-9]+)\\.json\\Z")\n'
        '    existentes = [int(casado.group(1)) for arquivo in pasta.glob("*.json")\n'
        '                  if (casado := padrao.fullmatch(arquivo.name))]\n'
        '    i = 1 + max(existentes, default=0)\n'
        '    return pasta / f"{ordem:02d}-{etapa}-c{i}.json", i\n'
        '\n'
        '\n'
        'def escrever_atomico(caminho: Path, evidencia: dict) -> Path:\n'
        '    caminho.parent.mkdir(parents=True, exist_ok=True)\n'
        '    texto = json.dumps(evidencia, ensure_ascii=False, indent=2) + "\\n"\n'
        '    descritor, tmp = tempfile.mkstemp(dir=caminho.parent,\n'
        '                                      prefix=PREFIXO_TEMPORARIO,\n'
        '                                      suffix=SUFIXO_TEMPORARIO)\n'
        '    try:\n'
        '        with os.fdopen(descritor, "w", encoding="utf-8") as arquivo:\n'
        '            arquivo.write(texto)\n'
        '            arquivo.flush()\n'
        '            os.fsync(arquivo.fileno())\n'
        '        os.link(tmp, caminho)\n'
        '        os.unlink(tmp)\n'
        '    finally:\n'
        '        if os.path.exists(tmp):\n'
        '            os.unlink(tmp)\n'
        '    return caminho\n'
        '\n'
        '\n'
        'def _corpo_do_motivo(motivo, etapa, trabalho, teto, detalhe) -> dict:\n'
        '    dito = detalhe or DETALHE_AUSENTE\n'
        '    if motivo == MOTIVO_DESLIGADA:\n'
        '        return {"faltas": [FALTA_DESLIGADA]}\n'
        '    if motivo == MOTIVO_MORTA:\n'
        '        return {"faltas": [FALTA_MORTA.format(dito)],\n'
        '                "proximo": PROXIMO_MORTA.format(etapa, dito, trabalho)}\n'
        '    if motivo == MOTIVO_RECIBO_INVALIDO:\n'
        '        return {"faltas": [FALTA_RECIBO_INVALIDO.format(dito)],\n'
        '                "proximo": PROXIMO_RECIBO_INVALIDO.format(etapa, dito,\n'
        '                                                          trabalho)}\n'
        '    return {"faltas": [FALTA_TETO_ESGOTADO.format(teto)],\n'
        '            "proximo": PROXIMO_TETO_ESGOTADO.format(teto, trabalho)}\n'
        '\n'
        '\n'
        'def sintetizar(dir_base, trabalho, etapa, ordem, teto, motivo, detalhe,\n'
        '               esquema):\n'
        '    if motivo not in MOTIVOS:\n'
        '        sys.exit(ERRO_MOTIVO_DESCONHECIDO.format(motivo, ", ".join(MOTIVOS)))\n'
        '    caminho, i = caminho_da_evidencia(dir_base, trabalho, ordem, etapa)\n'
        '    evidencia = {\n'
        '        "etapa": etapa,\n'
        '        "trabalho": trabalho,\n'
        '        "quando": agora(),\n'
        '        "veredito": (VEREDITO_SEGUE if motivo == MOTIVO_DESLIGADA\n'
        '                     else VEREDITO_PARA),\n'
        '        "provado": [],\n'
        '        "suposto": [],\n'
        '        "faltas": [],\n'
        '        "origem": ORIGEM_ENCADEADOR,\n'
        '        "motivo": motivo,\n'
        '        "ciclo": {"i": i, "teto": teto},\n'
        '    }\n'
        '    evidencia.update(_corpo_do_motivo(motivo, etapa, trabalho, teto, detalhe))\n'
        '\n'
        '    erros = validar_evidencia(evidencia, esquema)\n'
        '    if erros:\n'
        '        print(ERRO_DEFEITO_NO_SINTETICO.format("; ".join(erros)),\n'
        '              file=sys.stderr)\n'
        '        sys.exit(2)\n'
        '    return escrever_atomico(caminho, evidencia)\n'
        '\n'
        '\n'
        'def _candidato_da_entrada(texto: str):\n'
        '    texto = (texto or "").strip()\n'
        '    if not texto:\n'
        '        return None, ERRO_ENTRADA_VAZIA\n'
        '    try:\n'
        '        bruto = json.loads(texto)\n'
        '    except (ValueError, RecursionError) as decodificacao:\n'
        '        return None, ERRO_JSON_QUEBRADO.format(decodificacao)\n'
        '    if isinstance(bruto, dict) and "structured_output" in bruto:\n'
        '        bruto = bruto["structured_output"]\n'
        '    if isinstance(bruto, dict):\n'
        '        return bruto, ""\n'
        '    return None, ERRO_NAO_E_OBJETO\n'
        '\n'
        '\n'
        'def materializar(dir_base, trabalho, etapa, ordem, teto, texto, esquema,\n'
        '                 turnos=None, custo=None):\n'
        '    candidato, erro = _candidato_da_entrada(texto)\n'
        '    if candidato is not None:\n'
        '        for reservado in CAMPOS_RESERVADOS_AO_SINTETICO:\n'
        '            candidato.pop(reservado, None)\n'
        '        caminho, i = caminho_da_evidencia(dir_base, trabalho, ordem, etapa)\n'
        '        candidato["etapa"] = etapa\n'
        '        candidato["trabalho"] = trabalho\n'
        '        candidato["quando"] = agora()\n'
        '        candidato["ciclo"] = {"i": i, "teto": teto}\n'
        '        candidato.pop(CAMPO_DOS_TURNOS, None)\n'
        '        if turnos:\n'
        '            candidato[CAMPO_DOS_TURNOS] = turnos\n'
        '        candidato.pop(CAMPO_DO_CUSTO, None)\n'
        '        if custo:\n'
        '            candidato[CAMPO_DO_CUSTO] = custo\n'
        '        erros = validar_evidencia(candidato, esquema)\n'
        '        if not erros:\n'
        '            return escrever_atomico(caminho, candidato), 0\n'
        '        erro = "; ".join(erros[:QUANTOS_ERROS_NO_DETALHE])\n'
        '\n'
        '    caminho = sintetizar(dir_base, trabalho, etapa, ordem, teto,\n'
        '                         MOTIVO_RECIBO_INVALIDO, erro, esquema)\n'
        '    return caminho, 3\n'
        '\n'
        '\n'
        'def montar_parser() -> argparse.ArgumentParser:\n'
        '    parser = argparse.ArgumentParser(prog="evidencia.py", add_help=True)\n'
        '    sub = parser.add_subparsers(dest="comando", required=True)\n'
        '\n'
        '    valida = sub.add_parser("validar", help=AJUDA_VALIDAR)\n'
        '    valida.add_argument("arquivo", help=AJUDA_ARQUIVO)\n'
        '\n'
        '    def comuns(p):\n'
        '        p.add_argument("--dir", required=True, help=AJUDA_DIR)\n'
        '        p.add_argument("--trabalho", required=True)\n'
        '        p.add_argument("--etapa", required=True)\n'
        '        p.add_argument("--ordem", required=True, type=int)\n'
        '        p.add_argument("--teto", required=True, type=int)\n'
        '\n'
        '    materializa = sub.add_parser("materializar", help=AJUDA_MATERIALIZAR)\n'
        '    comuns(materializa)\n'
        '    materializa.add_argument("--entrada", default="-", help=AJUDA_ENTRADA)\n'
        '    materializa.add_argument("--turnos", type=int, help=AJUDA_TURNOS)\n'
        '    materializa.add_argument("--custo", help=AJUDA_CUSTO)\n'
        '\n'
        '    sintetiza = sub.add_parser("sintetico", help=AJUDA_SINTETICO)\n'
        '    comuns(sintetiza)\n'
        '    sintetiza.add_argument("--motivo", required=True, choices=MOTIVOS)\n'
        '    sintetiza.add_argument("--detalhe", default="")\n'
        '\n'
        '    sub.add_parser("esquema-sessao", help=AJUDA_ESQUEMA_SESSAO)\n'
        '    return parser\n'
        '\n'
        '\n'
        'def _descartar_stdout():\n'
        '    try:\n'
        '        os.dup2(os.open(os.devnull, os.O_WRONLY), 1)\n'
        '    except OSError:\n'
        '        pass\n'
        '\n'
        '\n'
        'def _dizer_caminho(caminho: Path, codigo: int) -> int:\n'
        '    try:\n'
        '        print(caminho)\n'
        '        sys.stdout.flush()\n'
        '    except OSError as saida:\n'
        '        print(ERRO_STDOUT_APOS_ESCRITA.format(caminho, saida), file=sys.stderr)\n'
        '        _descartar_stdout()\n'
        '        return 2\n'
        '    return codigo\n'
        '\n'
        '\n'
        'def _imprimir_esquema_da_sessao(esquema: dict) -> int:\n'
        '    guia = projetar_para_sessao(esquema)\n'
        '    try:\n'
        '        print(json.dumps(guia, ensure_ascii=False))\n'
        '        sys.stdout.flush()\n'
        '    except OSError as saida:\n'
        '        print(ERRO_STDOUT.format(saida), file=sys.stderr)\n'
        '        _descartar_stdout()\n'
        '        return 2\n'
        '    return 0\n'
        '\n'
        '\n'
        'def _validar_arquivo(pedido: str, esquema: dict) -> int:\n'
        '    if pedido == "-":\n'
        '        texto = sys.stdin.read()\n'
        '    else:\n'
        '        try:\n'
        '            texto = Path(pedido).read_text(encoding="utf-8")\n'
        '        except OSError as erro:\n'
        '            print(ERRO_LEITURA.format(pedido, erro), file=sys.stderr)\n'
        '            return 2\n'
        '    try:\n'
        '        dado = json.loads(texto)\n'
        '    except (ValueError, RecursionError) as erro:\n'
        '        print(ERRO_JSON_QUEBRADO.format(erro), file=sys.stderr)\n'
        '        return 2\n'
        '    erros = validar_evidencia(dado, esquema)\n'
        '    if erros:\n'
        '        for linha in erros:\n'
        '            print(linha, file=sys.stderr)\n'
        '        return 2\n'
        '    try:\n'
        '        print(OK_EVIDENCIA_VALIDA)\n'
        '        sys.stdout.flush()\n'
        '    except OSError as saida:\n'
        '        print(ERRO_STDOUT_APOS_VALIDA.format(saida), file=sys.stderr)\n'
        '        _descartar_stdout()\n'
        '        return 2\n'
        '    return 0\n'
        '\n'
        '\n'
        'def _custo_do_argumento(texto):\n'
        '    if not texto:\n'
        '        return None, ""\n'
        '    try:\n'
        '        return json.loads(texto), ""\n'
        '    except (ValueError, RecursionError) as quebra:\n'
        '        return None, PROBLEMA_CUSTO.format(quebra)\n'
        '\n'
        '\n'
        'def _problemas_dos_argumentos(args, esquema: dict) -> list:\n'
        '    problemas = _erros(esquema["properties"]["etapa"], args.etapa,\n'
        '                       ROTULO_ARG_ETAPA)\n'
        '    problemas += _erros(esquema["properties"]["trabalho"], args.trabalho,\n'
        '                        ROTULO_ARG_TRABALHO)\n'
        '    problemas += _erros(esquema["properties"]["ciclo"]["properties"]["teto"],\n'
        '                        args.teto, ROTULO_ARG_TETO)\n'
        '    if not ORDEM_MINIMA <= args.ordem <= ORDEM_MAXIMA:\n'
        '        problemas.append(PROBLEMA_ORDEM.format(args.ordem))\n'
        '    if not args.dir or "\\n" in args.dir or "\\r" in args.dir:\n'
        '        problemas.append(PROBLEMA_DIR)\n'
        '    custo, problema = _custo_do_argumento(getattr(args, "custo", None))\n'
        '    if problema:\n'
        '        problemas.append(problema)\n'
        '    elif custo is not None:\n'
        '        problemas += _erros(esquema["properties"][CAMPO_DO_CUSTO], custo,\n'
        '                            ROTULO_ARG_CUSTO)\n'
        '    return problemas\n'
        '\n'
        '\n'
        'def _texto_da_entrada(entrada: str):\n'
        '    if entrada == "-":\n'
        '        return sys.stdin.read()\n'
        '    try:\n'
        '        return Path(entrada).read_text(encoding="utf-8")\n'
        '    except FileNotFoundError:\n'
        '        return ""\n'
        '    except OSError as ambiente:\n'
        '        print(ERRO_AMBIENTE_NA_ENTRADA.format(entrada, ambiente),\n'
        '              file=sys.stderr)\n'
        '        return None\n'
        '\n'
        '\n'
        'def _materializar_pela_linha_de_comando(args, esquema: dict) -> int:\n'
        '    texto = _texto_da_entrada(args.entrada)\n'
        '    if texto is None:\n'
        '        return 2\n'
        '    custo, _ = _custo_do_argumento(args.custo)\n'
        '    try:\n'
        '        caminho, codigo = materializar(args.dir, args.trabalho, args.etapa,\n'
        '                                       args.ordem, args.teto, texto, esquema,\n'
        '                                       turnos=args.turnos, custo=custo)\n'
        '    except FileExistsError as colisao:\n'
        '        print(ERRO_COLISAO.format(colisao), file=sys.stderr)\n'
        '        return 2\n'
        '    except OSError as ambiente:\n'
        '        print(ERRO_AMBIENTE_NADA_ESCRITO.format(ambiente), file=sys.stderr)\n'
        '        return 2\n'
        '    return _dizer_caminho(caminho, codigo)\n'
        '\n'
        '\n'
        'def _sintetizar_pela_linha_de_comando(args, esquema: dict) -> int:\n'
        '    try:\n'
        '        caminho = sintetizar(args.dir, args.trabalho, args.etapa, args.ordem,\n'
        '                             args.teto, args.motivo, args.detalhe, esquema)\n'
        '    except FileExistsError as colisao:\n'
        '        print(ERRO_COLISAO.format(colisao), file=sys.stderr)\n'
        '        return 2\n'
        '    except OSError as ambiente:\n'
        '        print(ERRO_AMBIENTE_NADA_ESCRITO.format(ambiente), file=sys.stderr)\n'
        '        return 2\n'
        '    return _dizer_caminho(caminho, 0)\n'
        '\n'
        '\n'
        'def main(argv) -> int:\n'
        '    args = montar_parser().parse_args(argv)\n'
        '    esquema = carregar_esquema()\n'
        '\n'
        '    if args.comando == "esquema-sessao":\n'
        '        return _imprimir_esquema_da_sessao(esquema)\n'
        '    if args.comando == "validar":\n'
        '        return _validar_arquivo(args.arquivo, esquema)\n'
        '\n'
        '    problemas = _problemas_dos_argumentos(args, esquema)\n'
        '    if problemas:\n'
        '        for problema in problemas:\n'
        '            print(ERRO_DE_USO.format(problema), file=sys.stderr)\n'
        '        return 2\n'
        '\n'
        '    if args.comando == "materializar":\n'
        '        return _materializar_pela_linha_de_comando(args, esquema)\n'
        '    return _sintetizar_pela_linha_de_comando(args, esquema)\n'
        '\n'
        '\n'
        "EXEMPLO_DA_ISSUE = r'''\n"
        '{\n'
        '  "etapa": "cetico",\n'
        '  "trabalho": "issue-42",\n'
        '  "quando": "2026-08-16T16:02:47-03:00",\n'
        '  "veredito": "para",\n'
        '  "provado": [\n'
        '    { "afirmacao": "o endpoint responde 200 no ambiente de teste",\n'
        '      "comando": "curl -s -o /dev/null -w \'%{http_code}\' \\"$URL_HOMOLOG/relatorio\\"",\n'
        '      "saida": "200" }\n'
        '  ],\n'
        '  "suposto": [],\n'
        '  "faltas": [\n'
        '    "a issue pedia paginacao e a resposta veio inteira: 3.412 itens num corpo so"\n'
        '  ],\n'
        '  "proximo": "Implemente a paginacao pedida na issue-42: parametros pagina e tamanho, teto de 100. Prove com dois comandos: a pagina 2 vindo diferente da 1, e uma pagina alem do fim vindo vazia com 200.",\n'
        '  "ciclo": { "i": 1, "teto": 3 }\n'
        '}\n'
        "'''\n"
        '\n'
        '\n'
        'def _base(**troca):\n'
        '    evidencia = {\n'
        '        "etapa": "fantoche", "trabalho": "issue-0",\n'
        '        "quando": "2026-08-16T12:00:00-03:00", "veredito": "segue",\n'
        '        "provado": [], "suposto": [], "faltas": [],\n'
        '        "ciclo": {"i": 1, "teto": 3},\n'
        '    }\n'
        '    evidencia.update(troca)\n'
        '    return {chave: valor for chave, valor in evidencia.items()\n'
        '            if valor is not ...}\n'
        '\n'
        '\n'
        'ACEITA = [\n'
        '    ("o exemplo do corpo da issue", json.loads(EXEMPLO_DA_ISSUE)),\n'
        '    ("segue mínimo, listas vazias", _base()),\n'
        '    ("pergunta com o campo pergunta", _base(\n'
        '        veredito="pergunta",\n'
        '        pergunta="Recomendo A porque custa um comando; a alternativa B refaz "\n'
        '                 "a etapa. Sigo com A?")),\n'
        '    ("skip sintético da etapa desligada", _base(\n'
        '        origem="encadeador", motivo="desligada",\n'
        '        faltas=["etapa desligada no roteiro — nada executou"])),\n'
        '    ("para sintético de etapa morta", _base(\n'
        '        veredito="para", origem="encadeador", motivo="morta",\n'
        '        faltas=["a etapa morreu sem deixar evidência: timeout"],\n'
        '        proximo="A etapa fantoche terminou sem evidência (timeout). Leia o log, "\n'
        '                "corrija a causa e reexecute a partir dela.")),\n'
        '    ("provado com comando e saída", _base(provado=[\n'
        '        {"afirmacao": "o teste passa", "comando": "pytest -q", "saida": "3 passed"}])),\n'
        '    ("ciclo 1.0 — draft-07 aceita inteiro de fração zero",\n'
        '     _base(ciclo={"i": 1.0, "teto": 3})),\n'
        '    ("custo carimbado pelo encadeador", _base(custo={\n'
        '        "usd": 0.1234, "tokens": {"entrada": 10, "saida": 2,\n'
        '                                  "cache-lido": 100, "cache-criado": 50}})),\n'
        ']\n'
        '\n'
        'RECUSA = [\n'
