        'SEM_MEDIDA = "-"\n'
        'TETO_DE_ARGUMENTOS = 100000\n'
        'GREP_ERROU_A_PARTIR_DE = 2\n'
        'VOCABULARIO_NAO_MEDIDO = ("Vocabulário NÃO MEDIDO em {} termo(s): o grep falhou, "\n'
        '                          "e falha não é zero.")\n'
        'VOCABULARIO_FECHADO = "Vocabulário fechado: nenhum termo com saldo."\n'
        'VOCABULARIO_COM_FOLGA = (\n'
        '    "Vocabulário com {} exceção(ões) a mais do que existe no disco — a "\n'
        '    "declaração envelheceu, e enquanto ela sobra o termo pode reabrir sem "\n'
        '    "ninguém ver: a ocorrência nova entra no lugar da que sumiu. Meça e "\n'
