        'VOCABULARIO_ABERTO = ("Vocabulário com {} ocorrência(s) em aberto — o "\n'
        '                      "termo velho voltou, ou a exceção declarada envelheceu.")\n'
        'SEM_VOCABULARIO = "Sem {} — nada a medir."\n'
        'RASCUNHO = "tmp"\n'
        'TETO_DE_DIAS_NO_RASCUNHO = 7\n'
        'SEGUNDOS_DO_DIA = 86400\n'
        'PASTAS_DE_INSTRUMENTO_NO_RASCUNHO = {\n'
        '    "evidencias": ("as evidências das execuções, que o executor de roteiros "\n'
        '                   "escreve e o painel de controle lê — a rodada as reabre"),\n'
        '    "esfriamento-lembrado": ("a marca de uma vez por sessão do gancho que "\n'
        '                             "lembra o esfriamento"),\n'
        '}\n'
        'COMANDO_DOS_RASCUNHOS_RASTREADOS = "git ls-files tmp/"\n'
        'TITULO_RASCUNHO = "O RASCUNHO — o que envelhece em tmp/"\n'
        'LINHA_DO_ESQUECIDO = "  {:<52} {} dias parado"\n'
        'LINHA_DA_PASTA_DE_INSTRUMENTO = "  {:<24} fora da conta: {}"\n'
        'SEM_RASCUNHO = "Sem {} no disco — nada a medir."\n'
        'RASCUNHO_NAO_MEDIDO = (\n'
        '    "Rascunho NÃO MEDIDO: `{}` falhou. Sem a listagem do git não sei o que "\n'
        '    "ali é rastreado, e chamar tudo de esquecido acusaria o que viaja.")\n'
        'RASCUNHO_EM_DIA = (\n'
        '    "Rascunho em dia: nenhum arquivo não rastreado parado em {}/ acima de {} "\n'
        '    "dias — {} olhado(s), {} rastreado(s) fora da conta.")\n'
        'RASCUNHO_ENVELHECIDO = (\n'
        '    "Rascunho envelhecido: {} arquivo(s) não rastreado(s) parado(s) em {}/ "\n'
        '    "acima de {} dias. A rotina acusa e não apaga: destrutivo é do dono.")\n'
        'GLOB_PYTHON = "*.py"\n'
        'GLOB_SKILL = "*/SKILL.md"\n'
        'GLOB_PAGINA = "*.md"\n'
        'BANDEIRA_DE_TESTE = "--testar"\n'
        'MARCAS_DE_RESUMO = ("OK:", "FALHOU:")\n'
        '\n'
        'FRONTMATTER = re.compile(r"^---\\n(.*?)\\n---\\n", re.S)\n'
        'CAMPO_NOME = re.compile(r"^name:\\s*(.+)$", re.M)\n'
        'CAMPO_DESCRICAO = re.compile(r"^description:\\s*(.+)$", re.M)\n'
        'CAMPO_DAS_FERRAMENTAS = re.compile(r"^tools:\\s*\\S", re.M)\n'
        'FORMAS_DE_FUNCAO = (ast.FunctionDef, ast.AsyncFunctionDef)\n'
        'MARCA_DE_TESTE_NO_NOME = "test"\n'
        'MARCA_DA_BANDEIRA_DE_TESTE = "testar"\n'
        'LINHA_DO_CATALOGO = "- {}: {}\\n"\n'
        '\n'
        'MODELO_DA_SIMULACAO = "claude-haiku-4-5-20251001"\n'
        'FERRAMENTAS_DA_SIMULACAO = "Read,Glob,Grep,Write,Bash"\n'
        'TEMPO_DA_SIMULACAO = 900\n'
        'TEMPO_DE_UM_TESTE = 900\n'
        'ARQUIVO_PEDIDO = "tmp/somar.py"\n'
        '\n'
        'TITULO_MEDIR = "O QUE A CAMADA COBRA"\n'
        'TITULO_PROVAR = "O QUE A CAMADA PROVA"\n'
        'TITULO_SIMULAR = "UMA SESSÃO DE VERDADE"\n'
        'LINHA = "  {:<44} {}"\n'
        'LINHA_DE_CASO = "  [{}] {}"\n'
        'SEM_CLAUDE = "  (claude fora do PATH — a simulação não rodou)"\n'
        'SEM_REGRAS = "  (sem nucleo/regras.json — a simulação não tem gabarito)"\n'
        'NUMERO_DESCONHECIDO = "Número que não existe: {}.\\nOs que existem: {}."\n'
        'NUMERO_NAO_MEDIDO = "não medido"\n'
        'FORA_DA_RAIZ = "Rode na raiz do repositório: {} não encontrado aqui."\n'
        '\n'
        'PEDIDO = """Você abriu esta sessão na raiz de um repositório que tem uma camada de\n'
        'instruções para agentes. Leia o que a camada manda ler e faça as duas coisas.\n'
        '\n'
        'PARTE 1 — responda pelo que a camada diz, não pelo que você acha.\n'
        'PARTE 2 — escreva o arquivo {arquivo}: um script que soma os inteiros passados na\n'
        'linha de comando e imprime a soma. Ele precisa ter um `--testar` próprio que sai 0\n'
        'quando passa, e esse teste tem de exercitar o código do próprio arquivo.\n'
        '\n'
        'Sua ÚLTIMA mensagem tem de ser só este JSON, sem cerca de código:\n'
        '{{"onde_abrir": "<em que pasta a sessão se abre e por quê>",\n'
        '  "quantas_regras": <número inteiro de regras numeradas da camada>,\n'
        '  "posso_commitar": "<sim|nao|depende — e em uma frase, por quê>",\n'
        '  "segredo_em_texto_rastreado": "<o que a camada manda escrever no lugar do valor>",\n'
        '  "branch_de_longa_duracao": "<o que a camada manda fazer com ela>",\n'
        '  "o_que_e_pronto": "<quando a camada deixa chamar um trabalho de pronto>"}}"""\n'
        '\n'
        '\n'
        'def corre(comando, tempo=TEMPO_DE_UM_TESTE):\n'
        '    r = subprocess.run(comando, shell=True, capture_output=True, text=True,\n'
        '                       timeout=tempo)\n'
        '    return r.returncode, (r.stdout + r.stderr).strip()\n'
        '\n'
        '\n'
        'def pasta_das_skills(raiz: Path) -> Path:\n'
        '    instalada = raiz / PASTA_DAS_SKILLS\n'
        '    return instalada if instalada.is_dir() else raiz / PASTA_DAS_SKILLS_FONTE\n'
        '\n'
        '\n'
        'PASTAS_DE_SKILL_DA_FERRAMENTA = ("plugins", "skills")\n'
        'ORCAMENTO_DA_LISTAGEM = 8000\n'
        'FORA_DO_ALCANCE = ("a listagem de skills que a ferramenta monta some {} bytes "\n'
        '                   "de {} skill(s) da máquina, contra um orçamento de {} — {}x "\n'
        '                   "acima. Acima do orçamento a ferramenta corta descrição, e "\n'
        '                   "skill sem descrição perde o gatilho. Isto NÃO é do "\n'
        '                   "repositório e não reprova: o catálogo daqui é a linha de "\n'
        '                   "cima. Conte com: find ~/.claude -name SKILL.md")\n'
        'LISTAGEM_NAO_MEDIDA = ("a listagem da máquina não foi medida — não há pasta de "\n'
        '                       "skill da ferramenta neste alcance")\n'
        '\n'
        'TETO_DO_CORPO_DA_SKILL = 10000\n'
        'SKILL_ACIMA_DO_TETO = "{} ({} bytes)"\n'
        'NENHUMA_SKILL_ACIMA = "nenhuma"\n'
        '\n'
        '\n'
        'def skills_da_ferramenta() -> list:\n'
        '    pasta_da_ferramenta = Path.home() / ".claude"\n'
        '    achadas = []\n'
        '    for pasta in PASTAS_DE_SKILL_DA_FERRAMENTA:\n'
        '        alvo = pasta_da_ferramenta / pasta\n'
        '        if alvo.is_dir():\n'
        '            achadas += [p for p in alvo.rglob("SKILL.md") if p.is_file()]\n'
        '    return achadas\n'
        '\n'
        '\n'
        'def listagem_da_ferramenta() -> tuple:\n'
        '    achadas = skills_da_ferramenta()\n'
        '    return sum(len(catalogo_e_corpo(p)[0].encode()) for p in achadas), len(achadas)\n'
        '\n'
        '\n'
        'def anexos_da_skill(skill: Path) -> int:\n'
        '    return sum(len(anexo.read_bytes())\n'
        '               for anexo in sorted(skill.parent.rglob("*"))\n'
        '               if anexo.is_file() and anexo != skill)\n'
        '\n'
        '\n'
        'def catalogo_e_corpo(skill: Path) -> tuple:\n'
        '    texto = skill.read_text(encoding="utf-8", errors="replace")\n'
        '    frente = FRONTMATTER.match(texto)\n'
        '    if not frente:\n'
        '        return "", len(texto.encode())\n'
        '    nome = CAMPO_NOME.search(frente.group(1))\n'
        '    descricao = CAMPO_DESCRICAO.search(frente.group(1))\n'
        '    if not (nome and descricao):\n'
        '        return "", len(texto.encode())\n'
        '    listada = LINHA_DO_CATALOGO.format(nome.group(1).strip(),\n'
        '                                       descricao.group(1).strip())\n'
        '    return listada, len(texto.encode()) - len(frente.group(1).encode())\n'
        '\n'
        '\n'
        '@functools.lru_cache(maxsize=1)\n'
        'def interpretador_com_nome_portatil() -> str:\n'
        '    for nome in CANDIDATOS_DE_INTERPRETADOR:\n'
        '        if not shutil.which(nome):\n'
        '            continue\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                [nome, "-c", PERGUNTA_DA_VERSAO], capture_output=True,\n'
        '                text=True, timeout=TETO_DO_INTERPRETADOR_S)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            continue\n'
        '        if pronto.returncode == 0 and \\\n'
        '                pronto.stdout.strip() == VERSAO_QUE_SERVE:\n'
        '            return nome\n'
        '    return CANDIDATOS_DE_INTERPRETADOR[0]\n'
        '\n'
        '\n'
        'def comandos_dos_ganchos(raiz: Path, arquivos: tuple,\n'
        '                         evento: str) -> list:\n'
        '    comandos = []\n'
        '    for nome in arquivos:\n'
        '        try:\n'
        '            dado = json.loads(\n'
        '                (raiz / nome).read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError):\n'
        '            continue\n'
        '        eventos = dado.get(CHAVE_DOS_GANCHOS) or {}\n'
        '        escolhidos = ([eventos.get(evento) or []] if evento\n'
        '                      else list(eventos.values()))\n'
        '        for blocos in escolhidos:\n'
        '            for bloco in blocos:\n'
        '                for gancho in (bloco.get(CHAVE_DOS_GANCHOS) or []):\n'
        '                    if gancho.get(CHAVE_DO_COMANDO):\n'
        '                        comandos.append(gancho[CHAVE_DO_COMANDO])\n'
        '    return comandos\n'
        '\n'
        '\n'
        'def interpretadores_que_somem(comandos: list) -> list:\n'
        '    ausentes = []\n'
        '    for comando in comandos:\n'
        '        pedacos = shlex.split(comando)\n'
        '        if not pedacos:\n'
        '            continue\n'
        '        chamado = pedacos[0]\n'
        '        if shutil.which(chamado) or Path(chamado).is_file():\n'
        '            continue\n'
        '        if chamado not in ausentes:\n'
        '            ausentes.append(chamado)\n'
        '    return sorted(ausentes)\n'
        '\n'
        '\n'
        'def ganchos_com_interpretador_que_some(raiz: Path) -> list:\n'
        '    return interpretadores_que_somem(\n'
        '        comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE, ""))\n'
        '\n'
        '\n'
        'def comandos_de_abertura(raiz: Path) -> list:\n'
        '    return comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE,\n'
        '                                EVENTO_DE_ABERTURA)\n'
        '\n'
        '\n'
        'def bytes_que_os_ganchos_injetam(raiz: Path) -> tuple:\n'
        '    total, cegos = 0, 0\n'
        '    for comando in comandos_de_abertura(raiz):\n'
        '        real = comando.replace(RAIZ_NO_COMANDO, str(raiz)).replace(\n'
        '            RAIZ_NO_COMANDO_SEM_CHAVES, str(raiz))\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                real, shell=True, input=ENTRADA_VAZIA_DO_GANCHO,\n'
        '                capture_output=True, text=True, cwd=raiz,\n'
        '                timeout=TEMPO_DE_UM_GANCHO)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            cegos += 1\n'
        '            continue\n'
        '        if pronto.returncode != 0:\n'
        '            cegos += 1\n'
        '            continue\n'
        '        if not pronto.stdout.strip():\n'
        '            continue\n'
        '        try:\n'
        '            injetado = json.loads(pronto.stdout)[\n'
        '                CHAVE_DA_SAIDA_DO_GANCHO][CHAVE_DO_CONTEXTO_INJETADO]\n'
        '            total += len(injetado.encode())\n'
        '        except (ValueError, KeyError, TypeError, AttributeError):\n'
        '            cegos += 1\n'
        '    return total, cegos\n'
        '\n'
        '\n'
        'def lotes_de_caminhos(alvos: list) -> list:\n'
        '    lotes, atual, tamanho = [], [], 0\n'
        '    for caminho in alvos:\n'
        '        if atual and tamanho + len(caminho) > TETO_DE_ARGUMENTOS:\n'
        '            lotes.append(atual)\n'
        '            atual, tamanho = [], 0\n'
        '        atual.append(caminho)\n'
        '        tamanho += len(caminho) + 1\n'
        '    if atual:\n'
        '        lotes.append(atual)\n'
        '    return lotes\n'
        '\n'
        '\n'
        'def soma_das_contagens(saida: str):\n'
        '    total = 0\n'
        '    for linha in saida.split("\\n"):\n'
        '        if not linha:\n'
        '            continue\n'
        '        try:\n'
        '            total += int(linha.rsplit(":", 1)[1])\n'
        '        except (ValueError, IndexError):\n'
        '            return None\n'
        '    return total\n'
        '\n'
        '\n'
        'def quantas_linhas_casam(padrao: str, alvos: list, raiz: Path):\n'
        '    total = 0\n'
        '    for lote in lotes_de_caminhos(alvos):\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                ["grep", "-cHInP", padrao] + lote, cwd=raiz,\n'
        '                capture_output=True, text=True,\n'
        '                timeout=TEMPO_DE_UM_TESTE)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            return None\n'
        '        if pronto.returncode >= GREP_ERROU_A_PARTIR_DE:\n'
        '            return None\n'
        '        do_lote = soma_das_contagens(pronto.stdout)\n'
        '        if do_lote is None:\n'
        '            return None\n'
        '        total += do_lote\n'
        '    return total\n'
        '\n'
        '\n'
        'def perdao_do_termo(termo: dict, alvos: list, raiz: Path) -> tuple:\n'
        '    perdoadas, sem_referente = 0, []\n'
        '    for excecao in termo.get("excecoes", []):\n'
        '        quantas = excecao.get("ocorrencias") or 0\n'
        '        if not quantas:\n'
        '            continue\n'
        '        declarados = excecao.get("arquivos") or []\n'
        '        if not declarados:\n'
        '            sem_referente.append(excecao.get("caso") or EXCECAO_SEM_CASO)\n'
        '            continue\n'
        '        referentes = [a for a in declarados if a in alvos]\n'
        '        if not referentes:\n'
        '            continue\n'
        '        no_referente = quantas_linhas_casam(\n'
        '            termo["pronto"]["padrao"], referentes, raiz)\n'
        '        if no_referente is None:\n'
        '            return None, sem_referente\n'
        '        perdoadas += min(quantas, no_referente)\n'
        '    return perdoadas, sem_referente\n'
        '\n'
        '\n'
        'def saldo_do_vocabulario(raiz: Path) -> list:\n'
        '    fonte = raiz / FONTE_DO_VOCABULARIO\n'
        '    if not fonte.is_file():\n'
        '        return []\n'
        '    try:\n'
        '        termos = json.loads(fonte.read_text(encoding="utf-8"))["termos"]\n'
        '    except (json.JSONDecodeError, KeyError, TypeError):\n'
        '        return []\n'
        '    listados = corre(f\'cd "{raiz}" && git ls-files\')[1].split("\\n")\n'
        '    alvos = [c for c in listados\n'
        '             if c and c not in FORA_DA_CONTA_DO_VOCABULARIO]\n'
        '    if not alvos:\n'
        '        return []\n'
        '    contas = []\n'
        '    for termo in termos:\n'
        '        achadas = quantas_linhas_casam(\n'
        '            termo["pronto"]["padrao"], alvos, raiz)\n'
        '        perdoadas, sem_referente = perdao_do_termo(termo, alvos, raiz)\n'
        '        cego = achadas is None or perdoadas is None\n'
        '        saldo = None if cego else max(achadas - perdoadas, 0)\n'
        '        contas.append((termo["id"], achadas, perdoadas or 0, saldo,\n'
        '                       sem_referente))\n'
        '    return contas\n'
        '\n'
        '\n'
        'def folga_do_termo(bruto, perdoadas: int) -> int:\n'
        '    return 0 if bruto is None else max(perdoadas - bruto, 0)\n'
        '\n'
        '\n'
        'def vocabulario(raiz: Path) -> int:\n'
        '    contas = saldo_do_vocabulario(raiz)\n'
        '    if not contas:\n'
        '        print(SEM_VOCABULARIO.format(FONTE_DO_VOCABULARIO))\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_VOCABULARIO}")\n'
        '    orfas = []\n'
        '    for nome, bruto, perdoadas, saldo, sem_referente in contas:\n'
        '        folga = folga_do_termo(bruto, perdoadas)\n'
        '        print(LINHA_DO_TERMO.format(\n'
        '            nome, SEM_MEDIDA if bruto is None else bruto, perdoadas,\n'
        '            SEM_MEDIDA if saldo is None else saldo,\n'
        '            TERMO_NAO_MEDIDO if saldo is None else\n'
        '            (TERMO_ABERTO if saldo else\n'
        '             (TERMO_COM_FOLGA.format(folga) if folga else TERMO_FECHADO))))\n'
        '        orfas += [(nome, caso) for caso in sem_referente]\n'
        '    for nome, caso in orfas:\n'
        '        print(EXCECAO_SEM_REFERENTE.format(termo=nome, caso=caso))\n'
        '    cegos = sum(1 for _, _, _, saldo, _ in contas if saldo is None)\n'
        '    aberto = sum(saldo for _, _, _, saldo, _ in contas if saldo is not None)\n'
        '    folgas = sum(folga_do_termo(bruto, perdoadas)\n'
        '                 for _, bruto, perdoadas, _, _ in contas)\n'
        '    if cegos:\n'
        '        print(VOCABULARIO_NAO_MEDIDO.format(cegos))\n'
        '    elif aberto:\n'
        '        print(VOCABULARIO_ABERTO.format(aberto))\n'
        '    elif folgas:\n'
        '        print(VOCABULARIO_COM_FOLGA.format(folgas))\n'
        '    else:\n'
        '        print(VOCABULARIO_FECHADO)\n'
        '    return 1 if (aberto or cegos or folgas) else 0\n'
        '\n'
        '\n'
        'def entrega(raiz: Path) -> int:\n'
        '    codigo, atual = corre(f\'cd "{raiz}" && {COMANDO_DA_BRANCH}\')\n'
        '    if codigo != 0 or not atual:\n'
        '        print(FORA_DE_REPOSITORIO)\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_ENTREGA}")\n'
        '    codigo, alvo = corre(f\'cd "{raiz}" && {COMANDO_DO_UPSTREAM}\')\n'
        '    if codigo != 0 or not alvo:\n'
        '        codigo, alvo = corre(\n'
        '            f\'cd "{raiz}" && {COMANDO_DO_ESPELHO.format(atual)}\')\n'
        '    if codigo != 0 or not alvo:\n'
        '        print(SEM_ENTREGA.format(atual, atual))\n'
        '        return 1\n'
        '    _, sobra = corre(\n'
        '        f\'cd "{raiz}" && {COMANDO_DO_QUE_FALTA.format(alvo)}\')\n'
        '    linhas = [l for l in sobra.split("\\n") if l.strip()]\n'
        '    if not linhas:\n'
        '        print(ENTREGA_LIMPA.format(atual, alvo))\n'
        '        return 0\n'
        '    print(ENTREGA_COM_SOBRA.format(len(linhas), atual, alvo))\n'
        '    for linha in linhas:\n'
        '        print(f"  {linha}")\n'
        '    return 1\n'
        '\n'
        '\n'
        'def dias_parado(arquivo: Path, agora: float) -> int:\n'
        '    return int((agora - arquivo.stat().st_mtime) // SEGUNDOS_DO_DIA)\n'
        '\n'
        '\n'
        'def arquivos_do_rascunho(raiz: Path) -> list:\n'
        '    pasta = raiz / RASCUNHO\n'
        '    return sorted(a for a in pasta.rglob("*")\n'
        '                  if a.is_file() and a.relative_to(pasta).parts[0]\n'
        '                  not in PASTAS_DE_INSTRUMENTO_NO_RASCUNHO)\n'
        '\n'
        '\n'
        'def esquecidos_no_rascunho(arquivos: list, rastreados: set, raiz: Path,\n'
        '                           agora: float) -> list:\n'
        '    return [(rel, dias) for arquivo in arquivos\n'
        '            if (rel := arquivo.relative_to(raiz).as_posix()) not in rastreados\n'
        '            and (dias := dias_parado(arquivo, agora))\n'
        '            > TETO_DE_DIAS_NO_RASCUNHO]\n'
        '\n'
        '\n'
        'def rascunho(raiz: Path) -> int:\n'
        '    if not (raiz / RASCUNHO).is_dir():\n'
        '        print(SEM_RASCUNHO.format(RASCUNHO))\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_RASCUNHO}")\n'
        '    for nome, motivo in sorted(PASTAS_DE_INSTRUMENTO_NO_RASCUNHO.items()):\n'
        '        print(LINHA_DA_PASTA_DE_INSTRUMENTO.format(f"{RASCUNHO}/{nome}",\n'
        '                                                   motivo))\n'
        '    rastreados = rastreados_por_git(raiz, COMANDO_DOS_RASCUNHOS_RASTREADOS)\n'
        '    if rastreados is None:\n'
        '        print(RASCUNHO_NAO_MEDIDO.format(COMANDO_DOS_RASCUNHOS_RASTREADOS))\n'
        '        return 1\n'
        '    arquivos = arquivos_do_rascunho(raiz)\n'
        '    esquecidos = esquecidos_no_rascunho(arquivos, set(rastreados), raiz,\n'
        '                                        time.time())\n'
        '    for rel, dias in esquecidos:\n'
        '        print(LINHA_DO_ESQUECIDO.format(rel, dias))\n'
        '    if esquecidos:\n'
        '        print(RASCUNHO_ENVELHECIDO.format(len(esquecidos), RASCUNHO,\n'
        '                                          TETO_DE_DIAS_NO_RASCUNHO))\n'
        '        return 1\n'
        '    print(RASCUNHO_EM_DIA.format(RASCUNHO, TETO_DE_DIAS_NO_RASCUNHO,\n'
        '                                 len(arquivos), len(rastreados)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'PASTA_DAS_EVIDENCIAS = "execucoes/evidencias"\n'
        'CAMPO_DO_CUSTO = re.compile(r\'"total_cost_usd":([0-9.]+)\')\n'
        'CAMPO_DOS_TURNOS = re.compile(r\'"num_turns":(\\d+)\')\n'
        'TITULO_DA_CONTA = "A CONTA — o que cada execução custou, do que já está gravado"\n'
        'SEM_EVIDENCIAS = ("sem evidência gravada em {} — a conta não tem o que ler, "\n'
        '                  "e isso não é achado")\n'
        'LINHA_DA_EXECUCAO = "  {:<22} US$ {:>7.2f}   {:>4} turno(s)"\n'
        'CONTA_DA_RODADA = ("Somam US$ {:.2f} em {} execução(ões), {} turno(s). Não há "\n'
        '                   "teto declarado: esta rotina MEDE e não reprova, por "\n'
        '                   "decisão do dono em 30/08 — número sem procedência não "\n'
        '                   "vira cobrança, e a procedência se junta rodando.")\n'
        '\n'
        '\n'
        'def custo_por_execucao(raiz: Path) -> list:\n'
        '    pasta = raiz / PASTA_DAS_EVIDENCIAS\n'
        '    if not pasta.is_dir():\n'
        '        return []\n'
        '    contas = {}\n'
        '    for log in sorted(pasta.glob("*/*.log")):\n'
        '        trabalho = log.parent.name\n'
        '        dolar, turnos = contas.get(trabalho, (0.0, 0))\n'
        '        try:\n'
        '            texto = log.read_text(encoding="utf-8", errors="replace")\n'
        '        except OSError:\n'
        '            continue\n'
        '        for achado in CAMPO_DO_CUSTO.finditer(texto):\n'
        '            dolar += float(achado.group(1))\n'
        '        for achado in CAMPO_DOS_TURNOS.finditer(texto):\n'
        '            turnos += int(achado.group(1))\n'
        '        contas[trabalho] = (dolar, turnos)\n'
        '    return sorted(((n, d, t) for n, (d, t) in contas.items() if d),\n'
        '                  key=lambda linha: -linha[1])\n'
        '\n'
        '\n'
        'def conta(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_DA_CONTA}")\n'
        '    linhas = custo_por_execucao(raiz)\n'
        '    if not linhas:\n'
        '        print(SEM_EVIDENCIAS.format(PASTA_DAS_EVIDENCIAS))\n'
        '        return 0\n'
        '    for nome, dolar, turnos in linhas:\n'
        '        print(LINHA_DA_EXECUCAO.format(nome, dolar, turnos))\n'
        '    print(CONTA_DA_RODADA.format(sum(l[1] for l in linhas), len(linhas),\n'
        '                                 sum(l[2] for l in linhas)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def teto_da_largada(raiz: Path):\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_DE_CONFIGURACAO).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return None\n'
        '    declarado = dado.get(CHAVE_DO_TETO) if isinstance(dado, dict) else None\n'
        '    return declarado if isinstance(declarado, int) else None\n'
        '\n'
        '\n'
        'def largada(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_LARGADA}")\n'
        '    paga = medir(raiz)[1]["largada"]\n'
        '    teto = teto_da_largada(raiz)\n'
        '    if teto is None:\n'
        '        print(LARGADA_SEM_TETO.format(paga, ARQUIVO_DE_CONFIGURACAO,\n'
        '                                      CHAVE_DO_TETO))\n'
        '        return 0\n'
        '    if paga > teto:\n'
        '        print(LARGADA_ACIMA.format(paga, teto))\n'
        '        return 1\n'
        '    print(LARGADA_NA_REGUA.format(paga, teto))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def rastreados_por_git(raiz: Path, comando: str):\n'
        '    codigo, saida = corre(f\'cd "{raiz}" && {comando}\')\n'
        '    if codigo != 0:\n'
        '        return None\n'
        '    return sorted(l.strip() for l in saida.split("\\n") if l.strip())\n'
        '\n'
        '\n'
        'def escopo_do_instalador(raiz: Path) -> tuple:\n'
        '    escopo = {"__name__": NOME_DO_ESCOPO_DA_MATRICULA}\n'
        '    try:\n'
        '        fonte = (raiz / INSTALADOR).read_text(encoding="utf-8")\n'
        '        exec(compile(fonte, INSTALADOR, "exec"), escopo)\n'
        '    except Exception as erro:\n'
        '        return None, f"{type(erro).__name__}: {erro}"\n'
        '    return escopo, ""\n'
        '\n'
        '\n'
        'def matricula_do_instalador(raiz: Path) -> tuple:\n'
        '    escopo, erro = escopo_do_instalador(raiz)\n'
        '    if escopo is None:\n'
        '        return None, erro\n'
        '    declarados = set()\n'
        '    for valor in escopo.values():\n'
        '        if type(valor).__name__ == NOME_DO_GANCHO_DECLARADO:\n'
        '            declarados.update(CAMINHO_DE_GANCHO.findall(valor.comando))\n'
        '    por_modulo = set()\n'
        '    for arquivos in (escopo.get(NOME_DE_MODULOS) or {}).values():\n'
        '        por_modulo.update(arquivos)\n'
        '    return (tuple(escopo.get(NOME_DE_FONTES) or ()), declarados,\n'
        '            por_modulo), ""\n'
        '\n'
        '\n'
        'def embutidos_sob(raiz: Path, fontes: tuple, prefixo: str) -> set:\n'
        '    achados = set()\n'
        '    for padrao in fontes:\n'
        '        for caminho in raiz.glob(padrao):\n'
        '            relativo = caminho.relative_to(raiz).as_posix()\n'
        '            if relativo.startswith(prefixo) and caminho.is_file():\n'
        '                achados.add(relativo)\n'
        '    return achados\n'
        '\n'
        '\n'
        'def matriculas_orfas(raiz: Path, fontes: tuple, declarados: set) -> list:\n'
        '    prefixo = f"{PASTA_DOS_GANCHOS}/"\n'
        '    literais = {p for p in fontes if p.startswith(prefixo)\n'
        '                and not set(p) & set(CARACTERES_DE_GLOB)}\n'
        '    return sorted(c for c in literais | declarados\n'
        '                  if not (raiz / c).is_file())\n'
        '\n'
        '\n'
        'def ganchos_ligados_fora_do_git(raiz: Path, ganchos: list) -> list:\n'
        '    ligados = set()\n'
        '    for comando in comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE,\n'
        '                                        TODOS_OS_EVENTOS):\n'
        '        ligados.update(CAMINHO_DE_GANCHO.findall(comando))\n'
        '    return sorted(c for c in ligados\n'
        '                  if c not in set(ganchos) and (raiz / c).is_file())\n'
        '\n'
        '\n'
        'def saldos_da_matricula(raiz: Path, ganchos: list, fontes: tuple,\n'
        '                        declarados: set) -> list:\n'
        '    embutidos = embutidos_sob(raiz, fontes, f"{PASTA_DOS_GANCHOS}/")\n'
        '    ligados = set()\n'
        '    for comando in comandos_dos_ganchos(raiz, (ARQUIVO_SETTINGS,),\n'
        '                                        TODOS_OS_EVENTOS):\n'
        '        ligados.update(CAMINHO_DE_GANCHO.findall(comando))\n'
        '    saldos = [(c, SALDO_NAO_VIAJA) for c in ganchos\n'
        '              if c not in embutidos]\n'
        '    saldos += [(c, SALDO_ORFA)\n'
        '               for c in matriculas_orfas(raiz, fontes, declarados)]\n'
        '    saldos += [(c, SALDO_SEM_DECLARACAO)\n'
        '               for c in sorted(ligados - declarados)]\n'
        '    saldos += [(c, SALDO_DESLIGADO)\n'
        '               for c in sorted(declarados - ligados)\n'
        '               if (raiz / c).is_file()]\n'
        '    return saldos\n'
        '\n'
        '\n'
        'def saldos_dos_instrumentos(raiz: Path, instrumentos: list, fontes: tuple,\n'
        '                            por_modulo: set) -> list:\n'
        '    viajam = (embutidos_sob(raiz, fontes, f"{PASTA_DOS_INSTRUMENTOS}/")\n'
        '              | por_modulo | set(INSTRUMENTOS_QUE_FICAM))\n'
        '    saldos = [(c, SALDO_NAO_VIAJA) for c in instrumentos if c not in viajam]\n'
        '    saldos += [(c, SALDO_EXCECAO_VELHA)\n'
        '               for c in sorted(INSTRUMENTOS_QUE_FICAM)\n'
        '               if c not in instrumentos]\n'
        '    return saldos\n'
        '\n'
        '\n'
        'def matricula(raiz: Path) -> int:\n'
        '    if not (raiz / INSTALADOR).is_file():\n'
        '        print(SEM_INSTALADOR.format(INSTALADOR))\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_MATRICULA}")\n'
        '    ganchos = rastreados_por_git(raiz, COMANDO_DOS_GANCHOS_RASTREADOS)\n'
        '    instrumentos = rastreados_por_git(raiz,\n'
        '                                      COMANDO_DOS_INSTRUMENTOS_RASTREADOS)\n'
        '    if ganchos is None or instrumentos is None:\n'
        '        mudo = (COMANDO_DOS_GANCHOS_RASTREADOS if ganchos is None\n'
        '                else COMANDO_DOS_INSTRUMENTOS_RASTREADOS)\n'
        '        print(GIT_NAO_RESPONDEU.format(mudo))\n'
        '        return 1\n'
        '    lida, erro = matricula_do_instalador(raiz)\n'
        '    if lida is None:\n'
        '        print(INSTALADOR_ILEGIVEL.format(INSTALADOR, erro))\n'
        '        return 1\n'
        '    fontes, declarados, por_modulo = lida\n'
        '    saldos = saldos_da_matricula(raiz, ganchos, fontes, declarados)\n'
        '    saldos += saldos_dos_instrumentos(raiz, instrumentos, fontes, por_modulo)\n'
        '    for caminho, motivo in saldos:\n'
        '        print(LINHA_DO_SALDO.format(caminho, motivo))\n'
        '    fora_do_git = ganchos_ligados_fora_do_git(raiz, ganchos)\n'
        '    somem = ganchos_com_interpretador_que_some(raiz)\n'
        '    for chamado in somem:\n'
        '        print(INTERPRETADOR_QUE_SOME.format(chamado))\n'
        '    if saldos or somem:\n'
        '        print(MATRICULA_ABERTA.format(len(saldos) + len(somem)))\n'
        '        return 1\n'
        '    for caminho in fora_do_git:\n'
        '        print(GANCHO_LIGADO_FORA_DO_GIT.format(caminho))\n'
        '    print(MATRICULA_FECHADA.format(len(ganchos), len(instrumentos)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def chaves_declaradas(raiz: Path) -> tuple:\n'
        '    caminhos = rastreados_por_git(raiz, COMANDO_DOS_JSON_RASTREADOS)\n'
        '    if caminhos is None:\n'
        '        return None, []\n'
        '    declaradas, ilegiveis = [], []\n'
        '    for arquivo in caminhos:\n'
        '        caminho = raiz / arquivo\n'
        '        if not caminho.is_file():\n'
        '            continue\n'
        '        try:\n'
        '            dado = json.loads(caminho.read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError) as erro:\n'
        '            ilegiveis.append((arquivo, f"{type(erro).__name__}: {erro}"))\n'
        '            continue\n'
        '        if isinstance(dado, dict):\n'
        '            declaradas.extend((arquivo, chave, valor)\n'
        '                              for chave, valor in dado.items())\n'
        '    return declaradas, ilegiveis\n'
        '\n'
        '\n'
        'def excecoes_sem_leitor(raiz: Path) -> dict:\n'
        '    caminho = raiz / ARQUIVO_DE_CONFIGURACAO\n'
        '    if not caminho.is_file():\n'
        '        return {}\n'
        '    try:\n'
        '        dado = json.loads(caminho.read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return {}\n'
        '    declaradas = dado.get(CHAVE_DAS_EXCECOES_SEM_LEITOR) or []\n'
        '    if not isinstance(declaradas, list):\n'
        '        return {}\n'
        '    return {(entrada[CAMPO_DO_ARQUIVO], entrada[CAMPO_DA_CHAVE]):\n'
        '            entrada[CAMPO_DO_MOTIVO]\n'
        '            for entrada in declaradas\n'
        '            if isinstance(entrada, dict)\n'
        '            and entrada.get(CAMPO_DO_ARQUIVO) and entrada.get(CAMPO_DA_CHAVE)\n'
        '            and entrada.get(CAMPO_DO_MOTIVO)}\n'
        '\n'
        '\n'
        'def leitores_da_configuracao(raiz: Path) -> tuple:\n'
        '    caminhos = rastreados_por_git(raiz, COMANDO_DOS_LEITORES_RASTREADOS)\n'
        '    if caminhos is None:\n'
        '        return None, CHAVES_NAO_MEDIDAS.format(\n'
        '            COMANDO_DOS_LEITORES_RASTREADOS)\n'
        '    lidos = [(c, (raiz / c).read_text(encoding="utf-8", errors="replace"))\n'
        '             for c in caminhos\n'
        '             if c != INSTALADOR and (raiz / c).is_file()]\n'
        '    if (raiz / INSTALADOR).is_file():\n'
        '        escopo, erro = escopo_do_instalador(raiz)\n'
        '        if escopo is None:\n'
        '            return None, INSTALADOR_ILEGIVEL.format(INSTALADOR, erro)\n'
        '        for arquivos in (escopo.get(NOME_DE_MODULOS) or {}).values():\n'
        '            lidos.extend(arquivos.items())\n'
        '    return (len(caminhos), lidos), ""\n'
        '\n'
        '\n'
        'def onde_a_marca_aparece(marcas: tuple, fontes: list) -> str:\n'
        '    for arquivo, texto in fontes:\n'
        '        if not any(marca in texto for marca in marcas):\n'
        '            continue\n'
        '        for numero, linha in enumerate(texto.split("\\n"), 1):\n'
        '            if any(marca in linha for marca in marcas):\n'
        '                return f"{arquivo}:{numero}"\n'
        '    return ""\n'
        '\n'
        '\n'
        'def marcas_da_chave(chave: str) -> tuple:\n'
        '    return (f\'"{chave}"\', f"\'{chave}\'")\n'
        '\n'
        '\n'
        'def de_quem_e_a_chave(arquivo: str, valor) -> str:\n'
        '    molde = arquivo.endswith(SUFIXO_DO_EXEMPLO)\n'
        '    marcador = (isinstance(valor, str)\n'
        '                and VALOR_QUE_A_MAQUINA_PREENCHE.match(valor))\n'
        '    return CHAVE_DA_MAQUINA if molde or marcador else CHAVE_DO_REPOSITORIO\n'
        '\n'
        '\n'
        'def json_fora_do_universo(raiz: Path) -> str:\n'
        '    fora = rastreados_por_git(raiz, COMANDO_DOS_JSON_FORA_DO_GIT)\n'
        '    if fora is None:\n'
        '        return CHAVES_NAO_MEDIDAS.format(COMANDO_DOS_JSON_FORA_DO_GIT)\n'
        '    if not fora:\n'
        '        return NENHUM_FORA_DO_UNIVERSO.format(COMANDO_DOS_JSON_FORA_DO_GIT)\n'
        '    return FORA_DO_UNIVERSO.format(", ".join(fora))\n'
        '\n'
        '\n'
        'def chaves(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_DAS_CHAVES}")\n'
        '    declaradas, ilegiveis = chaves_declaradas(raiz)\n'
        '    if declaradas is None:\n'
        '        print(CHAVES_NAO_MEDIDAS.format(COMANDO_DOS_JSON_RASTREADOS))\n'
        '        return 1\n'
        '    for arquivo, erro in ilegiveis:\n'
        '        print(CONFIGURACAO_ILEGIVEL.format(arquivo, erro))\n'
        '    if ilegiveis:\n'
        '        return 1\n'
        '    if not declaradas:\n'
        '        print(SEM_CONFIGURACAO.format(COMANDO_DOS_JSON_RASTREADOS))\n'
        '        return 0\n'
        '    medido, erro = leitores_da_configuracao(raiz)\n'
        '    if medido is None:\n'
        '        print(erro)\n'
        '        return 1\n'
        '    quantos_leitores, leitores = medido\n'
        '    arquivos = len({arquivo for arquivo, _, _ in declaradas})\n'
        '    excecoes = excecoes_sem_leitor(raiz)\n'
        '    orfas = []\n'
        '    for arquivo, chave, valor in declaradas:\n'
        '        onde = onde_a_marca_aparece(marcas_da_chave(chave), leitores)\n'
        '        motivo = excecoes.get((arquivo, chave))\n'
        '        if not onde and motivo is None:\n'
        '            orfas.append((arquivo, chave))\n'
        '        print(LINHA_DA_CHAVE.format(\n'
        '            f"{arquivo} → {chave}", de_quem_e_a_chave(arquivo, valor),\n'
        '            onde or (EXCECAO_DECLARADA.format(motivo[:TETO_DO_MOTIVO])\n'
        '                     if motivo else SALDO_SEM_LEITOR)))\n'
        '    print(json_fora_do_universo(raiz))\n'
        '    if orfas:\n'
        '        print(CHAVES_ABERTAS.format(\n'
        '            len(orfas), len(declaradas), arquivos, ARQUIVO_DE_CONFIGURACAO,\n'
        '            CHAVE_DAS_EXCECOES_SEM_LEITOR, CAMPO_DO_ARQUIVO, CAMPO_DA_CHAVE,\n'
        '            CAMPO_DO_MOTIVO))\n'
        '        return 1\n'
        '    print(CHAVES_FECHADAS.format(len(declaradas), arquivos, quantos_leitores))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def corpos_dos_markdowns(raiz: Path, markdowns: list) -> tuple:\n'
        '    corpos, ilegiveis = {}, {}\n'
        '    for rel in markdowns:\n'
        '        try:\n'
        '            corpos[rel] = (raiz / rel).read_text(encoding="utf-8",\n'
        '                                                 errors="replace")\n'
        '        except OSError as erro:\n'
        '            ilegiveis[rel] = MARKDOWN_ILEGIVEL.format(\n'
        '                f"{type(erro).__name__}: {erro}")\n'
        '    return corpos, ilegiveis\n'
        '\n'
        '\n'
        'def fontes_que_nomeiam(raiz: Path, rastreados: list) -> list:\n'
        '    return [(c, (raiz / c).read_text(encoding="utf-8", errors="replace"))\n'
        '            for c in rastreados\n'
        '            if c.endswith(SUFIXOS_QUE_NOMEIAM) and c != INSTALADOR\n'
        '            and (raiz / c).is_file()]\n'
        '\n'
        '\n'
        'def apontadores_de_markdown(corpos: dict, rastreados: set) -> dict:\n'
        '    aponta = {}\n'
        '    for rel, texto in corpos.items():\n'
        '        pasta = posixpath.dirname(rel)\n'
        '        for citado in LINK_MARKDOWN.findall(texto):\n'
        '            perto = posixpath.normpath(posixpath.join(pasta, citado))\n'
        '            for alvo in (citado, perto):\n'
        '                if alvo in rastreados and alvo != rel:\n'
        '                    aponta.setdefault(alvo, VIA_DO_LINK.format(rel))\n'
        '    return aponta\n'
        '\n'
        '\n'
        'def markdowns_citados(fontes: list, rastreados: set, via: str) -> dict:\n'
        '    cita = {}\n'
        '    for arquivo, texto in fontes:\n'
        '        pasta = posixpath.dirname(arquivo)\n'
        '        for numero, linha in enumerate(texto.split("\\n"), 1):\n'
        '            for citado in CAMINHO_DE_MARKDOWN.findall(linha):\n'
        '                perto = posixpath.normpath(posixpath.join(pasta, citado))\n'
        '                for alvo in (citado, perto):\n'
        '                    if alvo in rastreados and alvo != arquivo:\n'
        '                        cita.setdefault(alvo,\n'
        '                                        via.format(f"{arquivo}:{numero}"))\n'
        '    return cita\n'
        '\n'
        '\n'
        'def irmao_do_roteiro(rel: str, rastreados: set) -> str:\n'
        '    roteiro = rel[:-len(SUFIXO_DA_PROSA)] + SUFIXO_DO_ROTEIRO\n'
        '    return VIA_DO_ROTEIRO.format(roteiro) if roteiro in rastreados else ""\n'
        '\n'
        '\n'
        'def dentro_do_modulo(rel: str) -> str:\n'
        '    partes = rel.split("/")\n'
        '    if len(partes) > 2 and partes[0] == PASTA_DOS_MODULOS:\n'
        '        return VIA_DO_MODULO.format(f"{partes[0]}/{partes[1]}")\n'
        '    return ""\n'
        '\n'
        '\n'
        'def pilha_do_markdown(rel: str, vias: tuple) -> tuple:\n'
        '    for pilha, prova in vias:\n'
        '        if prova:\n'
        '            return pilha, prova\n'
        '    if rel.rsplit("/", 1)[-1] in CARTOES_DE_PASTA:\n'
        '        return PILHA_NAO_CLASSIFICADO, CARTAO_DA_PASTA\n'
        '    return PILHA_SEM_LEITOR, ""\n'
        '\n'
        '\n'
        'def pilhas_do_markdown(raiz: Path):\n'
        '    rastreados = rastreados_por_git(raiz, COMANDO_DOS_RASTREADOS)\n'
        '    if rastreados is None:\n'
        '        return None\n'
        '    universo = set(rastreados)\n'
        '    markdowns = [c for c in rastreados if c.endswith(SUFIXO_DA_PROSA)]\n'
        '    corpos, ilegiveis = corpos_dos_markdowns(raiz, markdowns)\n'
        '    nomeado = markdowns_citados(fontes_que_nomeiam(raiz, rastreados),\n'
        '                                universo, VIA_DO_CODIGO)\n'
        '    citado = markdowns_citados(list(corpos.items()), universo, VIA_DA_PROSA)\n'
        '    aponta = apontadores_de_markdown(corpos, universo)\n'
        '    pilhas = {nome: [] for nome in ORDEM_DAS_PILHAS}\n'
        '    for rel in markdowns:\n'
        '        if rel in ilegiveis:\n'
        '            pilhas[PILHA_NAO_CLASSIFICADO].append((rel, ilegiveis[rel]))\n'
        '            continue\n'
        '        pilha, prova = pilha_do_markdown(rel, (\n'
        '            (PILHA_CONTRATO, nomeado.get(rel, "")),\n'
        '            (PILHA_CONTRATO, irmao_do_roteiro(rel, universo)),\n'
        '            (PILHA_PAGINA, aponta.get(rel, "")),\n'
        '            (PILHA_PAGINA, citado.get(rel, "")),\n'
        '            (PILHA_PAGINA, dentro_do_modulo(rel))))\n'
        '        pilhas[pilha].append((rel, prova))\n'
        '    return pilhas\n'
        '\n'
        '\n'
        'def markdown(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_DO_MARKDOWN}")\n'
        '    pilhas = pilhas_do_markdown(raiz)\n'
        '    if pilhas is None:\n'
        '        print(MARKDOWN_NAO_MEDIDO.format(COMANDO_DOS_RASTREADOS))\n'
        '        return 1\n'
        '    for nome in ORDEM_DAS_PILHAS:\n'
        '        print(LINHA_DA_PILHA.format(nome, len(pilhas[nome])))\n'
        '        for rel, prova in pilhas[nome]:\n'
        '            print(LINHA_DO_MARKDOWN.format(rel, prova).rstrip())\n'
        '    print(MARKDOWN_CLASSIFICADO.format(sum(len(p) for p in pilhas.values())))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def subagentes(raiz: Path) -> tuple:\n'
        '    achados = sorted((raiz / PASTA_DOS_SUBAGENTES).glob(GLOB_PAGINA))\n'
        '    sem_coleira = [a.name for a in achados\n'
        '                   if not CAMPO_DAS_FERRAMENTAS.search(\n'
        '                       a.read_text(encoding="utf-8", errors="replace"))]\n'
        '    return achados, sem_coleira\n'
        '\n'
        '\n'
        'def _recado_da_listagem(dados: dict) -> str:\n'
        '    bytes_da_maquina, quantas = dados["listagem_da_maquina"]\n'
        '    if not quantas:\n'
        '        return LISTAGEM_NAO_MEDIDA\n'
        '    total = bytes_da_maquina + dados["catalogo"]\n'
        '    return FORA_DO_ALCANCE.format(total, quantas, ORCAMENTO_DA_LISTAGEM,\n'
        '                                  round(total / ORCAMENTO_DA_LISTAGEM, 1))\n'
        '\n'
        '\n'
        'def medir(raiz: Path) -> tuple:\n'
        '    instrucoes = sum(len((raiz / n).read_bytes())\n'
        '                     for n in CARREGADOS_EM_TODA_SESSAO if (raiz / n).is_file())\n'
        '    catalogo = adiado = 0\n'
        '    skills = sorted(pasta_das_skills(raiz).glob(GLOB_SKILL))\n'
        '    acima_do_teto = []\n'
        '    for skill in skills:\n'
        '        listada, corpo = catalogo_e_corpo(skill)\n'
        '        catalogo += len(listada.encode())\n'
        '        peso = corpo + anexos_da_skill(skill)\n'
        '        adiado += peso\n'
        '        if peso > TETO_DO_CORPO_DA_SKILL:\n'
        '            acima_do_teto.append((skill.parent.name, peso))\n'
        '    paginas = sorted((raiz / PASTA_DO_CONHECIMENTO).glob(GLOB_PAGINA))\n'
        '    achados_de_subagente, subagentes_sem_coleira = subagentes(raiz)\n'
        '    contas_do_vocabulario = saldo_do_vocabulario(raiz)\n'
        '    injetado_por_gancho, ganchos_cegos = bytes_que_os_ganchos_injetam(\n'
        '        raiz)\n'
        '    dados = {\n'
        '        "largada": instrucoes + catalogo + injetado_por_gancho,\n'
        '        "instrucoes": instrucoes,\n'
        '        "catalogo": catalogo,\n'
        '        "injetado_por_gancho": injetado_por_gancho,\n'
        '        "ganchos_nao_medidos": ganchos_cegos,\n'
        '        "adiado": adiado,\n'
        '        "skills": len(skills),\n'
        '        "paginas": len(paginas),\n'
        '        "bytes_das_paginas": sum(len(p.read_bytes()) for p in paginas),\n'
        '        "ganchos": len(sorted((raiz / PASTA_DOS_GANCHOS).glob(GLOB_PYTHON))),\n'
        '        "subagentes": len(achados_de_subagente),\n'
        '        "vocabulario_aberto": sum(\n'
        '            saldo for _, _, _, saldo, _ in contas_do_vocabulario\n'
        '            if saldo is not None),\n'
        '        "vocabulario_nao_medido": sum(\n'
        '            1 for _, _, _, saldo, _ in contas_do_vocabulario\n'
        '            if saldo is None),\n'
        '        "excecoes_sem_referente": sum(\n'
        '            len(sem_referente)\n'
        '            for _, _, _, _, sem_referente in contas_do_vocabulario),\n'
        '        "subagentes_sem_coleira": len(subagentes_sem_coleira),\n'
        '        "skills_acima_do_teto": len(acima_do_teto),\n'
        '        "regras": quantas_regras(raiz),\n'
        '        "listagem_da_maquina": listagem_da_ferramenta(),\n'
        '    }\n'
        '    linhas = [\n'
        '        LINHA.format("largada — o que TODA sessão paga",\n'
        '                     f"{dados[\'largada\']} bytes"),\n'
        '        LINHA.format("  instruções (AGENTS.md, CLAUDE.md)",\n'
        '                     f"{dados[\'instrucoes\']} bytes"),\n'
        '        LINHA.format(f"  catálogo de {dados[\'skills\']} skills",\n'
        '                     f"{dados[\'catalogo\']} bytes"),\n'
        '        LINHA.format("  injetado por gancho de abertura",\n'
        '                     f"{dados[\'injetado_por_gancho\']} bytes"\n'
        '                     + (f" ({dados[\'ganchos_nao_medidos\']} gancho(s) não medido(s))"\n'
        '                        if dados["ganchos_nao_medidos"] else "")),\n'
        '        LINHA.format("corpo de skill — só ao disparar",\n'
        '                     f"{dados[\'adiado\']} bytes"),\n'
        '        LINHA.format(f"  acima do teto de {TETO_DO_CORPO_DA_SKILL} bytes",\n'
        '                     ", ".join(SKILL_ACIMA_DO_TETO.format(nome, peso)\n'
        '                               for nome, peso in acima_do_teto)\n'
        '                     or NENHUMA_SKILL_ACIMA),\n'
        '        LINHA.format("  fora do alcance deste repositório",\n'
        '                     _recado_da_listagem(dados)),\n'
        '        LINHA.format(f"páginas em {PASTA_DO_CONHECIMENTO}/",\n'
        '                     f"{dados[\'paginas\']} ({dados[\'bytes_das_paginas\']} bytes)"),\n'
        '        LINHA.format("ganchos no disco", dados["ganchos"]),\n'
        '        LINHA.format("subagentes no disco",\n'
        '                     f"{dados[\'subagentes\']}"\n'
        '                     f" ({dados[\'subagentes_sem_coleira\']} sem coleira)"),\n'
        '    ]\n'
        '    return linhas, dados\n'
        '\n'
        '\n'
        'def resumo_da_suite(saida: str) -> str:\n'
        '    linhas = [l for l in saida.splitlines() if l.strip()]\n'
        '    resumo = next((l for l in reversed(linhas)\n'
        '                   if l.startswith(MARCAS_DE_RESUMO)), linhas[-1] if linhas else "")\n'
        '    return resumo[:52]\n'
        '\n'
        '\n'
        'def instrumentos_com_teste(raiz: Path) -> list:\n'
        '    alvos = sorted(raiz.glob(GLOB_PYTHON))\n'
        '    alvos += sorted((raiz / PASTA_DOS_GANCHOS).glob(GLOB_PYTHON))\n'
        '    alvos += sorted((raiz / PASTA_DOS_INSTRUMENTOS).rglob(GLOB_PYTHON))\n'
        '    return [a for a in alvos\n'
        '            if BANDEIRA_DE_TESTE in a.read_text(encoding="utf-8", errors="replace")]\n'
        '\n'
        '\n'
        'def casos_da_suite(saida: str) -> int:\n'
        '    numeros = [int(p) for p in saida.replace(":", " ").split() if p.isdigit()]\n'
        '    return numeros[0] if saida.strip().startswith("OK") and numeros else 0\n'
        '\n'
        '\n'
        'def provar(raiz: Path) -> tuple:\n'
        '    linhas, caidos, rodados = [], [], 0\n'
        '    segundos, casos = 0.0, 0\n'
        '    for alvo in instrumentos_com_teste(raiz):\n'
        '        partida = time.monotonic()\n'
        '        codigo, saida = corre(\n'
        '            f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} "{alvo.relative_to(raiz)}" {BANDEIRA_DE_TESTE}\')\n'
        '        gasto = time.monotonic() - partida\n'
        '        segundos += gasto\n'
        '        provados = casos_da_suite(resumo_da_suite(saida))\n'
        '        casos += provados\n'
        '        rodados += 1\n'
        '        proprio_nada = codigo == 0 and provados == 0\n'
        '        if codigo != 0 or proprio_nada:\n'
        '            caidos.append(alvo.name)\n'
        '        linhas.append(LINHA_DE_CASO.format(\n'
        '            "NADA" if proprio_nada else ("OK  " if codigo == 0 else "CAIU"),\n'
        '            f"{alvo.relative_to(raiz)} — {gasto:.1f}s — "\n'
        '            f"{resumo_da_suite(saida)}"))\n'
        '    sem_teste = [p.name for p in sorted((raiz / PASTA_DOS_GANCHOS).glob(GLOB_PYTHON))\n'
        '                 if BANDEIRA_DE_TESTE not in p.read_text(encoding="utf-8",\n'
        '                                                         errors="replace")]\n'
        '    for nome in sem_teste:\n'
        '        linhas.append(LINHA_DE_CASO.format("CAIU", f"{nome} — sem --testar próprio"))\n'
        '    if (raiz / INSTALADOR).is_file():\n'
        '        codigo, _ = corre(f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} {INSTALADOR} --verificar\')\n'
        '        rodados += 1\n'
        '        if codigo != 0:\n'
        '            caidos.append(INSTALADOR)\n'
        '        linhas.append(LINHA_DE_CASO.format(\n'
        '            "OK  " if codigo == 0 else "CAIU", f"{INSTALADOR} --verificar"))\n'
        '    return linhas, {"rodados": rodados, "caem": len(caidos) + len(sem_teste),\n'
        '                    "sem_teste": len(sem_teste),\n'
        '                    "segundos": round(segundos, 1), "casos": casos}\n'
        '\n'
        '\n'
        'def _texto(valor):\n'
        '    return str(valor).lower()\n'
        '\n'
        '\n'
        'def _comeca_com(valor, aceitos):\n'
        '    return _texto(valor).lstrip(\' "\\\'\').startswith(tuple(aceitos))\n'
        '\n'
        '\n'
        'def quantas_regras(raiz: Path):\n'
        '    fonte = raiz / FONTE_DAS_REGRAS\n'
        '    if not fonte.is_file():\n'
        '        return None\n'
        '    try:\n'
        '        return len(json.loads(fonte.read_text(encoding="utf-8"))["regras"])\n'
        '    except (json.JSONDecodeError, KeyError, TypeError):\n'
        '        return None\n'
        '\n'
        '\n'
        'def perguntas(quantas_regras):\n'
        '    return (\n'
        '        ("abre na raiz", "onde_abrir",\n'
        '         lambda r: "raiz" in _texto(r.get("onde_abrir"))),\n'
        '        ("conta as regras", "quantas_regras",\n'
        '         lambda r: r.get("quantas_regras") == quantas_regras),\n'
        '        ("não commita por conta", "posso_commitar",\n'
        '         lambda r: _comeca_com(r.get("posso_commitar"),\n'
        '                               ("nao", "não", "depende"))),\n'
        '        ("segredo vira variável", "segredo_em_texto_rastreado",\n'
        '         lambda r: "${" in str(r.get("segredo_em_texto_rastreado"))\n'
        '         or "variáve" in _texto(r.get("segredo_em_texto_rastreado"))\n'
        '         or "variave" in _texto(r.get("segredo_em_texto_rastreado"))),\n'
        '        ("não toca em branch de longa duração", "branch_de_longa_duracao",\n'
        '         lambda r: any(p in _texto(r.get("branch_de_longa_duracao"))\n'
        '                       for p in ("não", "nao", "nunca"))),\n'
        '        ("pronto é o que instrumento provou", "o_que_e_pronto",\n'
        '         lambda r: "instrumento" in _texto(r.get("o_que_e_pronto"))\n'
        '         or "prov" in _texto(r.get("o_que_e_pronto"))),\n'
        '    )\n'
        '\n'
        '\n'
        'def colher_json(texto: str) -> dict:\n'
        '    for corte in (texto, texto[texto.find("{"):texto.rfind("}") + 1]):\n'
        '        with contextlib.suppress(ValueError):\n'
        '            dado = json.loads(corte)\n'
        '            if isinstance(dado, dict):\n'
        '                return dado\n'
        '    return {}\n'
        '\n'
        '\n'
        'def regioes_de_teste(arvore: ast.AST) -> list:\n'
        '    achadas = []\n'
        '    for no in ast.walk(arvore):\n'
        '        if isinstance(no, FORMAS_DE_FUNCAO) \\\n'
        '                and MARCA_DE_TESTE_NO_NOME in no.name.lower():\n'
        '            achadas.append((no, no.name))\n'
        '        elif isinstance(no, ast.If) \\\n'
        '                and MARCA_DA_BANDEIRA_DE_TESTE in ast.dump(no.test).lower():\n'
        '            achadas.append((no, ""))\n'
        '    return achadas\n'
        '\n'
        '\n'
        'def teste_toca_o_proprio_codigo(caminho: Path) -> bool:\n'
        '    with contextlib.suppress(OSError, SyntaxError):\n'
        '        arvore = ast.parse(caminho.read_text(encoding="utf-8"))\n'
        '        do_arquivo = {no.name for no in ast.walk(arvore)\n'
        '                      if isinstance(no, FORMAS_DE_FUNCAO)}\n'
        '        for regiao, nome_da_regiao in regioes_de_teste(arvore):\n'
        '            chamados = {c.func.id for c in ast.walk(regiao)\n'
        '                        if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)}\n'
        '            if chamados & (do_arquivo - {nome_da_regiao}):\n'
        '                return True\n'
        '    return False\n'
        '\n'
        '\n'
        'def simular(raiz: Path) -> tuple:\n'
        '    if not shutil.which("claude"):\n'
        '        return [SEM_CLAUDE], {"rodou": False}\n'
        '    fonte = raiz / FONTE_DAS_REGRAS\n'
        '    if not fonte.is_file():\n'
        '        return [SEM_REGRAS], {"rodou": False}\n'
        '\n'
        '    quantas = len(json.loads(fonte.read_text(encoding="utf-8"))["regras"])\n'
        '    alvo = raiz / ARQUIVO_PEDIDO\n'
        '    alvo.parent.mkdir(parents=True, exist_ok=True)\n'
        '    with contextlib.suppress(OSError):\n'
        '        alvo.unlink()\n'
        '\n'
        '    partida = time.monotonic()\n'
        '    _, bruto = corre(\n'
        '        f\'cd "{raiz}" && claude -p {json.dumps(PEDIDO.format(arquivo=ARQUIVO_PEDIDO))} \'\n'
        "        f'--output-format json --model {MODELO_DA_SIMULACAO} '\n"
        '        f\'--allowedTools "{FERRAMENTAS_DA_SIMULACAO}"\',\n'
        '        tempo=TEMPO_DA_SIMULACAO)\n'
        '    parede = time.monotonic() - partida\n'
        '\n'
        '    sessao = colher_json(bruto)\n'
        '    resposta = colher_json(str(sessao.get("result", "")))\n'
        '    do_nucleo = [(rotulo, bool(prova(resposta)),\n'
        '                  "" if prova(resposta) else str(resposta.get(chave, ""))[:44])\n'
        '                 for rotulo, chave, prova in perguntas(quantas)]\n'
        '    do_artefato = []\n'
        '\n'
        '    if alvo.is_file():\n'
        '        codigo_do_teste, berro = corre(\n'
        '            f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} "{ARQUIVO_PEDIDO}" {BANDEIRA_DE_TESTE}\')\n'
        '    else:\n'
        '        codigo_do_teste, berro = 1, "a sessão não escreveu o arquivo"\n'
        '    do_artefato.append((f"entregou {ARQUIVO_PEDIDO} com --testar que passa",\n'
        '                        alvo.is_file() and codigo_do_teste == 0,\n'
        '                        berro.strip().splitlines()[-1][:44] if berro else ""))\n'
        '    do_artefato.append(("o --testar exercita o código do arquivo",\n'
        '                        alvo.is_file() and teste_toca_o_proprio_codigo(alvo),\n'
        '                        ""))\n'
        '    acertos = do_nucleo + do_artefato\n'
        '    with contextlib.suppress(OSError):\n'
        '        alvo.unlink()\n'
        '\n'
        '    certos = sum(1 for _, ok, _ in acertos if ok)\n'
        '    uso = sessao.get("usage") or {}\n'
        '    linhas = [LINHA_DE_CASO.format("OK  " if ok else "CAIU",\n'
        '                                   f"{rotulo}{\'  \' + porque if porque else \'\'}")\n'
        '              for rotulo, ok, porque in acertos]\n'
        '    linhas += [\n'
        '        LINHA.format("acurácia", f"{certos}/{len(acertos)}"),\n'
        '        LINHA.format("turnos", sessao.get("num_turns", "?")),\n'
        '        LINHA.format("tempo de parede", f"{parede:.1f} s"),\n'
        '        LINHA.format("dólar", f"{sessao.get(\'total_cost_usd\', 0):.4f}"),\n'
        '        LINHA.format("tokens de saída", uso.get("output_tokens", "?")),\n'
        '    ]\n'
        '    return linhas, {"rodou": True, "acertos": certos, "casos": len(acertos),\n'
        '                    "certas_do_nucleo": sum(1 for _, ok, _ in do_nucleo if ok),\n'
        '                    "casos_do_nucleo": len(do_nucleo),\n'
        '                    "caidas_do_nucleo": [rotulo for rotulo, ok, _\n'
        '                                         in do_nucleo if not ok],\n'
        '                    "caidas_do_artefato": [rotulo for rotulo, ok, _\n'
        '                                           in do_artefato if not ok],\n'
        '                    "turnos": sessao.get("num_turns"),\n'
        '                    "segundos": round(parede, 1),\n'
        '                    "dolar": sessao.get("total_cost_usd")}\n'
        '\n'
        '\n'
        'PASSOS = (\n'
        '    ("medir", TITULO_MEDIR, medir),\n'
        '    ("provar", TITULO_PROVAR, provar),\n'
        '    ("simular", TITULO_SIMULAR, simular),\n'
        ')\n'
        '\n'
        'NUMEROS = {\n'
        '    "largada": ("medir", "largada"),\n'
        '    "adiado": ("medir", "adiado"),\n'
        '    "paginas": ("medir", "paginas"),\n'
        '    "ganchos": ("medir", "ganchos"),\n'
        '    "subagentes": ("medir", "subagentes"),\n'
        '    "vocabulario-aberto": ("medir", "vocabulario_aberto"),\n'
        '    "vocabulario-nao-medido": ("medir", "vocabulario_nao_medido"),\n'
        '    "subagentes-sem-coleira": ("medir", "subagentes_sem_coleira"),\n'
        '    "skills-acima-do-teto": ("medir", "skills_acima_do_teto"),\n'
        '    "injetado-por-gancho": ("medir", "injetado_por_gancho"),\n'
        '    "ganchos-nao-medidos": ("medir", "ganchos_nao_medidos"),\n'
