        '\n'
        '        declarar({"lida": 1, "ninguem_le": 2},\n'
        '                 [{CAMPO_DO_ARQUIVO: ARQUIVO_DE_CONFIGURACAO,\n'
        '                   CAMPO_DA_CHAVE: "ninguem_le"}])\n'
        '        caso("exceção sem motivo não vale, e a chave segue acusada",\n'
        '             chaves(raiz) == 1)\n'
        '\n'
        '        declarar({"so_o_modulo_le": 3})\n'
        '        (raiz / INSTALADOR).write_text(\n'
        '            INSTALADOR_DE_MENTIRA.replace(\n'
        '                f"\'{INSTRUMENTO_DE_MODULO_DE_MENTIRA}\': \'\'",\n'
        '                f"\'{INSTRUMENTO_DE_MODULO_DE_MENTIRA}\': "\n'
        '                "\'dado[\\\\\'so_o_modulo_le\\\\\']\'"),\n'
        '            encoding="utf-8")\n'
        '        caso("chave lida só pelo que chega por módulo não vira saldo",\n'
