        '                                              BANDEIRAS_DO_REPOSITORIO_DO_GH)\n'
        '                acoes.append((ACAO_RODAR.format("gh " + subverbo),\n'
        '                              repositorio_do_nome_remoto(declarado)\n'
        '                              if declarado\n'
        '                              else repositorio_do_caminho(".", onde)))\n'
        '        if tokens and Path(tokens[0]).name == COMANDO_CD and len(tokens) > 1:\n'
        '            destino = resolver(sem_o_par_de_aspas_que_envolve(tokens[1]), onde)\n'
        '            onde = str(destino) if destino else onde\n'
        '    return acoes\n'
        '\n'
        '\n'
        'def acoes_do_pedido(entrada: dict, onde: str) -> list:\n'
        '    ferramenta = entrada.get("tool_name", "")\n'
        '    dado = entrada.get("tool_input", {}) or {}\n'
        '    if ferramenta in FERRAMENTAS_DE_ESCRITA:\n'
        '        for campo in CAMPOS_DE_CAMINHO:\n'
        '            if dado.get(campo):\n'
        '                return [(ACAO_ESCREVER_EM.format(dado[campo]),\n'
        '                         repositorio_do_caminho(dado[campo], onde))]\n'
        '        return []\n'
        '    comando = dado.get("command", "")\n'
        '    return acoes_do_comando(comando, onde) if comando else []\n'
        '\n'
        '\n'
        'def recusa_do_pedido(entrada: dict, nomes, onde: str):\n'
        '    if not nomes:\n'
        '        return None\n'
        '    for acao, repositorio in acoes_do_pedido(entrada, onde):\n'
        '        if repositorio and repositorio in nomes:\n'
        '            return acao, repositorio\n'
        '    return None\n'
        '\n'
        '\n'
        'def raiz_do_projeto_nunca_o_cwd() -> Path:\n'
        '    declarada = os.environ.get(VARIAVEL_DA_RAIZ_DO_PROJETO)\n'
        '    if declarada:\n'
        '        return Path(declarada)\n'
        '    return Path(__file__).resolve().parents[NIVEIS_DO_GANCHO_ATE_A_RAIZ]\n'
        '\n'
        '\n'
        'def recusa_por_nao_entender(falha) -> int:\n'
        '    print(json.dumps({"hookSpecificOutput": {\n'
        '        "hookEventName": EVENTO_ANTES_DA_FERRAMENTA,\n'
        '        "permissionDecision": DECISAO_DE_NEGAR,\n'
        '        "permissionDecisionReason": RECUSA_SEM_ENTENDER.format(\n'
