        '            + MANDA_GRAVAR.format(APRENDIZADO)),\n'
        '    }}, ensure_ascii=False))\n'
        '    return SILENCIO\n'
        '\n'
        '\n'
        'NOME_DO_SOMENTE_LEITURA = "so-leitura"\n'
        'REVISOR_DO_TESTE = "quem-cuida"\n'
        'NOME_DO_QUE_ACEITA_ESCRITA = "pode-escrever"\n'
