        '        (pasta / "projetos" / nome / "x.py").write_text("velho",\n'
        '                                                        encoding="utf-8")\n'
        '    (pasta / "conhecimento").mkdir(parents=True, exist_ok=True)\n'
        '\n'
        '\n'
        'def pedido_de_shell(comando: str) -> dict:\n'
        '    return {"tool_name": "Bash", "tool_input": {"command": comando}}\n'
        '\n'
        '\n'
        'def pedido_de_escrita(ferramenta: str, caminho: str) -> dict:\n'
        '    campo = "notebook_path" if ferramenta == "NotebookEdit" else "file_path"\n'
        '    return {"tool_name": ferramenta, "tool_input": {campo: caminho}}\n'
        '\n'
        '\n'
        'BARRA = [\n'
        '    ("Write nasce dentro do somente leitura",\n'
        '     pedido_de_escrita("Write", "projetos/so-leitura/novo.py")),\n'
        '    ("Edit de arquivo que já existe lá",\n'
        '     pedido_de_escrita("Edit", "projetos/so-leitura/x.py")),\n'
        '    ("NotebookEdit lá dentro",\n'
        '     pedido_de_escrita("NotebookEdit", "projetos/so-leitura/n.ipynb")),\n'
        '    ("git commit por -C", pedido_de_shell(\n'
        '        "git -C projetos/so-leitura commit -m mudanca")),\n'
        '    ("git push por -C", pedido_de_shell("git -C projetos/so-leitura push")),\n'
        '    ("git push depois de cd", pedido_de_shell(\n'
        '        "cd projetos/so-leitura && git push origin HEAD")),\n'
        '    ("git checkout -b por -C", pedido_de_shell(\n'
        '        "git -C projetos/so-leitura checkout -b issue/1-teste")),\n'
        '    ("git merge por -C", pedido_de_shell(\n'
        '        "git -C projetos/so-leitura merge origin/main")),\n'
        '    ("git branch com nome novo", pedido_de_shell(\n'
