        ']\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    import tempfile\n'
        '    falhas, comportamento = [], []\n'
        '    with tempfile.TemporaryDirectory(prefix="veto-somente-leitura-") as tmp:\n'
        '        raiz = Path(tmp).resolve()\n'
        '        montar_workspace_de_mentira(raiz)\n'
        '        onde = str(raiz)\n'
        '        nomes = nomes_somente_leitura(raiz)\n'
        '\n'
        '        for rotulo, pedido in BARRA:\n'
        '            if not recusa_do_pedido(pedido, nomes, onde):\n'
        '                falhas.append(FALHA_BARRA.format(rotulo))\n'
        '        for rotulo, pedido in DEIXA_PASSAR:\n'
        '            recusa = recusa_do_pedido(pedido, nomes, onde)\n'
        '            if recusa:\n'
        '                falhas.append(FALHA_DEIXA_PASSAR.format(rotulo, recusa[0]))\n'
        '\n'
        '        def caso(rotulo, condicao):\n'
        '            comportamento.append((rotulo, bool(condicao)))\n'
        '\n'
        '        caso("gancho que veta e não entende o pedido RECUSA, e nomeia a "\n'
        '             "falha — quem não consegue julgar não pode dizer sim",\n'
        '             recusou_sem_entender(TypeError("forma que o gancho não conhece")))\n'
        '        caso("a lista declarada vira cerca",\n'
        '             nomes == frozenset({NOME_DO_SOMENTE_LEITURA}))\n'
        '        (raiz / "nucleo" / "executor.json").write_text(json.dumps({}),\n'
        '                                                       encoding="utf-8")\n'
        '        caso("sem o campo declarado, nada muda",\n'
        '             not nomes_somente_leitura(raiz)\n'
        '             and not recusa_do_pedido(BARRA[0][1],\n'
        '                                      nomes_somente_leitura(raiz), onde))\n'
        '        (raiz / "nucleo" / "executor.json").write_text(json.dumps(\n'
        '            {CHAVE_DOS_PROJETOS: {"alvo": {CHAVE_DO_REPOSITORIO: "${NOME}", CHAVE_DO_SO_LEITURA: True}}}), encoding="utf-8")\n'
        '        caso("nome ainda no molde não vira cerca",\n'
        '             not nomes_somente_leitura(raiz))\n'
        '        montar_workspace_de_mentira(raiz)\n'
        '\n'
        '        recusa = recusa_do_pedido(BARRA[3][1], nomes, onde)\n'
        '        mensagem = RECUSA.format(recusa[0], recusa[1],\n'
        '                                 revisor_de(raiz, recusa[1]),\n'
        '                                 CHAVE_DOS_PROJETOS, ARQUIVO_EXECUTOR)\n'
        '        caso("a mensagem nomeia o repositório",\n'
        '             NOME_DO_SOMENTE_LEITURA in mensagem)\n'
        '        caso("a mensagem nomeia o revisor declarado, nao só o território",\n'
        '             REVISOR_DO_TESTE in mensagem)\n'
        '        caso("sem revisor declarado, ela cai no território sem quebrar",\n'
        '             SEM_REVISOR in RECUSA.format(\n'
        '                 "x", "nao-declarado", revisor_de(raiz, "nao-declarado"),\n'
        '                 CHAVE_DOS_PROJETOS, ARQUIVO_EXECUTOR))\n'
        '        caso("a recusa nomeia a regra 9, diz onde o valor certo mora e "\n'
        '             "manda gravar o aprendizado em conhecimento/",\n'
        '             "Regra 9" in mensagem + MANDA_GRAVAR.format(APRENDIZADO)\n'
        '             and ARQUIVO_EXECUTOR in mensagem\n'
        '             and "regra 4" in MANDA_GRAVAR.format(APRENDIZADO)\n'
        '             and "`conhecimento/`" in MANDA_GRAVAR.format(APRENDIZADO))\n'
        '        caso("a mensagem ensina o pedido de incorporação como sugestão",\n'
        '             "SUGESTÃO" in mensagem and "incorporação" in mensagem)\n'
        '        caso("a mensagem ensina a marcar quem revisa",\n'
        '             "revisão" in mensagem and "território" in mensagem)\n'
        '        caso("a mensagem diz onde se muda a lista",\n'
        '             CHAVE_DOS_PROJETOS in mensagem\n'
        '             and ARQUIVO_EXECUTOR in mensagem)\n'
        '\n'
        '        caso("caminho absoluto é o mesmo repositório",\n'
        '             recusa_do_pedido(pedido_de_escrita(\n'
        '                 "Write", str(raiz / "projetos" / NOME_DO_SOMENTE_LEITURA\n'
        '                              / "abs.py")), nomes, onde))\n'
        '        caso("caminho fora de repositório nenhum passa",\n'
        '             not recusa_do_pedido(pedido_de_escrita("Write", "/dev/null"),\n'
        '                                  nomes, onde))\n'
        '        caso("aspas desbalanceadas não derrubam o gancho",\n'
        '             isinstance(acoes_do_comando(\n'
        '                 "echo \'sem fechar > projetos/so-leitura/x.txt", onde), list))\n'
        '        caso("documento literal não vira comando",\n'
        '             not recusa_do_pedido(pedido_de_shell(\n'
        '                 "python3 - <<\'PY\'\\ngit -C projetos/so-leitura push\\nPY"),\n'
        '                 nomes, onde))\n'
        '        caso("entrada sem ferramenta nem comando não devolve ação",\n'
        '             acoes_do_pedido({}, onde) == [])\n'
        '        caso("2>&1 não vira arquivo escrito",\n'
        '             not recusa_do_pedido(pedido_de_shell(\n'
        '                 "git -C projetos/so-leitura log 2>&1"), nomes, onde))\n'
        '\n'
        '        falhas += [FALHA_COMPORTAMENTO.format(rotulo)\n'
        '                   for rotulo, passou in comportamento if not passou]\n'
        '\n'
        '    total = len(BARRA) + len(DEIXA_PASSAR) + len(comportamento)\n'
        '    if falhas:\n'
        '        for falha in falhas:\n'
        '            print(LINHA_DE_FALHA.format(falha))\n'
        '        print(RESUMO_FALHOU.format(len(falhas), total))\n'
        '        return 1\n'
        '    print(RESUMO_OK.format(total, len(BARRA), len(DEIXA_PASSAR),\n'
        '                           len(comportamento)))\n'
        '    return 0\n'
        '\n'
        '\n'
        '\n'
        'def recusou_sem_entender(falha) -> bool:\n'
        '    import contextlib\n'
        '    import io\n'
        '    saida = io.StringIO()\n'
        '    with contextlib.redirect_stdout(saida):\n'
        '        recusa_por_nao_entender(falha)\n'
        '    try:\n'
        '        dado = json.loads(saida.getvalue())["hookSpecificOutput"]\n'
        '    except (ValueError, KeyError):\n'
        '        return False\n'
        '    return (dado.get("permissionDecision") == DECISAO_DE_NEGAR\n'
        '            and type(falha).__name__\n'
        '            in dado.get("permissionDecisionReason", ""))\n'
        '\n'
        '\n'
        'def main() -> int:\n'
        '    try:\n'
        '        return decidir()\n'
        '    except Exception as falha:\n'
        '        return recusa_por_nao_entender(falha)\n'
        '\n'
        '\n'
        'if __name__ == "__main__":\n'
        '    if BANDEIRA_DE_TESTE in sys.argv:\n'
        '        sys.exit(testar())\n'
        '    sys.exit(main())\n'
