        '            return [comentario_acrescentado(c, v, n, diretivas)\n'
        '                    for c, v, n in escritas(entrada)]\n'
        '\n'
        '        caso("Write compara com o que já está no disco",\n'
        '             veredito({"tool_name": "Write", "tool_input": {\n'
        '                 "file_path": "src/laco.ts",\n'
        '                 "content": "// explica o laço\\nconst total = 2\\n"}})\n'
        '             == [PASSA])\n'
        '        caso("Write que acrescenta comentário ao que estava no disco barra",\n'
        '             veredito({"tool_name": "Write", "tool_input": {\n'
        '                 "file_path": "src/laco.ts",\n'
        '                 "content": "// explica o laço\\n// e agora dois\\n"}})\n'
        '             == ["// e agora dois"])\n'
        '        caso("Write em arquivo que não existe trata tudo como novo",\n'
        '             veredito({"tool_name": "Write", "tool_input": {\n'
        '                 "file_path": "src/novo.ts",\n'
        '                 "content": "// nasce comentado"}}) == ["// nasce comentado"])\n'
        '        caso("Edit é alcançado",\n'
        '             veredito({"tool_name": "Edit", "tool_input": {\n'
        '                 "file_path": "src/laco.ts", "old_string": "const total = 1",\n'
        '                 "new_string": "// dobra o total\\nconst total = 2"}})\n'
        '             == ["// dobra o total"])\n'
        '        caso("MultiEdit alcança cada edição",\n'
        '             veredito({"tool_name": "MultiEdit", "tool_input": {\n'
        '                 "file_path": "src/laco.ts", "edits": [\n'
        '                     {"old_string": "a", "new_string": "b"},\n'
        '                     {"old_string": "c", "new_string": "// terceira"}]}})\n'
        '             == [PASSA, "// terceira"])\n'
        '        caso("ferramenta fora do veto não devolve escrita",\n'
        '             escritas({"tool_name": "Bash", "tool_input": {\n'
        '                 "command": "echo \'// explica\' >> src/laco.ts"}}) == [])\n'
        '        caso("pedido sem caminho não devolve escrita",\n'
        '             escritas({"tool_name": "Write", "tool_input": {\n'
        '                 "content": "// explica"}}) == [])\n'
        '        caso("entrada quebrada não prende a sessão", escritas({}) == [])\n'
        '        caso("edição malformada no MultiEdit não derruba o gancho",\n'
        '             escritas({"tool_name": "MultiEdit", "tool_input": {\n'
        '                 "file_path": "src/laco.ts", "edits": ["nada"]}}) == [])\n'
        '\n'
        '    falhas += [FALHA_COMPORTAMENTO.format(rotulo)\n'
        '               for rotulo, passou in comportamento if not passou]\n'
        '\n'
        '    total = len(BARRA) + len(DEIXA_PASSAR) + len(comportamento)\n'
        '    if falhas:\n'
        '        for falha in falhas:\n'
        '            print(LINHA_DE_FALHA.format(falha))\n'
        '        print(RESUMO_FALHOU.format(len(falhas), total))\n'
        '        return 1\n'
        '    print(RESUMO_OK.format(total, len(BARRA), len(DEIXA_PASSAR),\n'
        '                           len(comportamento)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def main() -> int:\n'
        '    try:\n'
        '        return decidir()\n'
        '    except Exception as falha:\n'
        '        return recusa_por_nao_entender(falha)\n'
        '\n'
        '\n'
        'if __name__ == "__main__":\n'
