        ']\n'
        '\n'
        'CALA = [\n'
        '    ("variável presente no ambiente",\n'
        '     dict(mcp=\'{"x": "${SINO_DE_VENTO_TOKEN}"}\')),\n'
        '    ("variável com padrão se vira sem valor",\n'
        '     dict(mcp=\'{"x": "${TAMBOR_MAIOR:-surdo}"}\')),\n'
        '    ("comando que está no PATH",\n'
        '     dict(declarado={"comando": ["prensa-de-flores"]})),\n'
        '    ("pasta que existe",\n'
        '     dict(declarado={"pasta": ["estufa"]})),\n'
        '    ("arquivo que existe",\n'
        '     dict(declarado={"arquivo": ["estufa/regras.md"]})),\n'
        '    ("receita que existe",\n'
        '     dict(declarado={"receita": "estufa/regras.md"})),\n'
        '    ("sem declaração nenhuma", dict()),\n'
        '    ("comentário do repositório e chave desconhecida ficam de fora",\n'
        '     dict(declarado={"comentario": "nota do repositório",\n'
        '                     "receita": None})),\n'
        '    ("lista vazia não inventa exigência",\n'
        '     dict(declarado={"comando": [], "pasta": [], "variavel": []})),\n'
        ']\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    import tempfile\n'
        '\n'
        '    with tempfile.TemporaryDirectory() as pasta:\n'
        '        raiz = Path(pasta)\n'
        '        caixa_de_ferramentas = raiz / "caixa-de-ferramentas"\n'
        '        caixa_de_ferramentas.mkdir()\n'
        '        util = caixa_de_ferramentas / "prensa-de-flores"\n'
        '        util.write_text("#!/bin/sh\\n", encoding="utf-8")\n'
        '        util.chmod(0o755)\n'
        '\n'
        '        (raiz / "estufa").mkdir()\n'
        '        (raiz / "estufa/regras.md").write_text("", encoding="utf-8")\n'
        '\n'
        '        ambiente = {"SINO_DE_VENTO_TOKEN": "presente"}\n'
        '\n'
        '        def faltas_do_caso(mcp=None, declarado=None, antigo=None):\n'
        '            for nome, conteudo in ((ARQUIVO_MCP, mcp),\n'
        '                                   (ARQUIVO_AMBIENTE, declarado),\n'
        '                                   (ARQUIVO_ANTIGO, antigo)):\n'
        '                alvo = raiz / nome\n'
        '                alvo.parent.mkdir(parents=True, exist_ok=True)\n'
        '                if conteudo is None:\n'
        '                    alvo.unlink(missing_ok=True)\n'
        '                elif isinstance(conteudo, str):\n'
        '                    alvo.write_text(conteudo, encoding="utf-8")\n'
        '                else:\n'
        '                    alvo.write_text(json.dumps(conteudo, ensure_ascii=False),\n'
        '                                    encoding="utf-8")\n'
        '            return faltas(raiz, env=ambiente,\n'
        '                          caminho_path=str(caixa_de_ferramentas))\n'
        '\n'
        '        falhas = []\n'
        '        for rotulo, caso in ACUSA:\n'
        '            problemas, _ = faltas_do_caso(**caso)\n'
        '            if not problemas:\n'
        '                falhas.append(FALHA_DEVIA_ACUSAR.format(rotulo))\n'
        '        for rotulo, caso in CALA:\n'
        '            problemas, _ = faltas_do_caso(**caso)\n'
        '            if problemas:\n'
        '                falhas.append(FALHA_DEVIA_CALAR.format(rotulo, problemas))\n'
        '\n'
        '        total = len(ACUSA) + len(CALA)\n'
