        '        for ferramenta in FERRAMENTAS_DE_TRABALHO)\n'
        '    return not houve_ferramenta_de_trabalho\n'
        '\n'
        '\n'
        'def decisao(entrada: dict, raiz: Path) -> str:\n'
        '    if cala_pelo_que_o_pedido_diz(entrada, raiz):\n'
        '        return NAO_LEMBRA\n'
        '    if cala_pelo_que_o_transcript_mostra(entrada):\n'
