        '            return SILENCIO\n'
        '        marca = raiz / PASTA_MARCAS / entrada["session_id"]\n'
        '        marca.parent.mkdir(parents=True, exist_ok=True)\n'
        '        marca.write_text(CONTEUDO_DA_MARCA, encoding="utf-8")\n'
        '    except Exception:\n'
        '        return FALHA_ABERTO\n'
        '\n'
        '    print(json.dumps({"hookSpecificOutput": {\n'
        '        "hookEventName": EVENTO_DE_PARADA,\n'
        '        "additionalContext": LEMBRETE,\n'
        '    }}))\n'
        '    return LEMBRETE_ENTREGUE\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    import io\n'
        '    import tempfile\n'
        '\n'
        '    falhas = []\n'
        '\n'
        '    def caso(rotulo, condicao):\n'
        '        if not condicao:\n'
        '            falhas.append(FALHA_DE_CASO.format(rotulo))\n'
        '\n'
        '    with tempfile.TemporaryDirectory(prefix="lembrar-teste-") as pasta:\n'
        '        raiz = Path(pasta)\n'
        '\n'
        '        def transcript(nome, tamanho, turnos, ferramenta, recheio_extra=""):\n'
        '            linhas = [\'{"type": "user", "message": "pedido"}\'] * turnos\n'
        '            if ferramenta:\n'
        '                linhas.append(\n'
        '                    f\'{{"type": "assistant", "name": "{ferramenta}"}}\')\n'
        '            if recheio_extra:\n'
        '                linhas.append(recheio_extra)\n'
        '            recheio = \'{"type": "assistant", "message": "\' \\\n'
        '                      + "x" * 200 + \'"}\'\n'
        '            while sum(len(linha) + 1 for linha in linhas) < tamanho:\n'
        '                linhas.append(recheio)\n'
        '            caminho = raiz / nome\n'
        '            caminho.write_text("\\n".join(linhas), encoding="utf-8")\n'
        '            return str(caminho)\n'
        '\n'
        '        trabalho = transcript("trabalho.jsonl", LIMIAR_BYTES + 1, 6, "Edit")\n'
        '        so_leitura = transcript("leitura.jsonl", LIMIAR_BYTES + 1, 6, "")\n'
        '        curto = transcript("curto.jsonl", 500, 6, "Edit")\n'
        '        poucos = transcript("poucos.jsonl", LIMIAR_BYTES + 1, 2, "Edit")\n'
        '        base = {"session_id": "s1", "transcript_path": trabalho}\n'
        '\n'
        '        CALA = [\n'
        '            ("laço: stop_hook_active", {**base, "stop_hook_active": True}),\n'
        '            ("sem session_id", {"transcript_path": trabalho}),\n'
        '            ("session_id com separador de caminho",\n'
        '             {**base, "session_id": "../fuga"}),\n'
        '            ("trabalho de fundo pendente",\n'
        '             {**base, "background_tasks": [{"id": 1}]}),\n'
        '            ("rotina agendada na sessão",\n'
        '             {**base, "session_crons": [{"id": 1}]}),\n'
        '            ("o esfriamento já apareceu na resposta",\n'
        '             {**base, "last_assistant_message": "Rodei o ESFRIAMENTO."}),\n'
        '            ("o esfriamento está no transcript, não na última resposta",\n'
        '             {**base, "transcript_path": transcript(\n'
        '                 "ja-esfriou.jsonl", LIMIAR_BYTES + 1, 6, "Edit",\n'
        '                 recheio_extra=\'{"type": "assistant", "message": \'\n'
        '                               \'"## Esfriamento — colhido"}\')}),\n'
        '            ("transcript pequeno", {**base, "transcript_path": curto}),\n'
        '            ("poucos turnos de usuário",\n'
        '             {**base, "transcript_path": poucos}),\n'
        '            ("sessão só de leitura",\n'
        '             {**base, "transcript_path": so_leitura}),\n'
        '            ("transcript que não existe",\n'
        '             {**base, "transcript_path": str(raiz / "nao-ha.jsonl")}),\n'
        '        ]\n'
        '        for rotulo, entrada in CALA:\n'
        '            if decisao(entrada, raiz):\n'
        '                falhas.append(FALHA_DEVIA_CALAR.format(rotulo))\n'
        '\n'
        '        caso("DEVIA LEMBRAR: sessão de trabalho sem esfriamento",\n'
        '             decisao(base, raiz) != NAO_LEMBRA)\n'
        '\n'
        '        guardado = os.environ.get(VARIAVEL_DA_RAIZ_DO_PROJETO)\n'
        '        os.environ[VARIAVEL_DA_RAIZ_DO_PROJETO] = pasta\n'
        '        try:\n'
        '            for rodada, esperado in (("primeira", True), ("segunda", False)):\n'
        '                sys.stdin = io.StringIO(json.dumps(base))\n'
        '                saida = io.StringIO()\n'
        '                stdout = sys.stdout\n'
        '                sys.stdout = saida\n'
        '                try:\n'
        '                    codigo = main()\n'
        '                finally:\n'
        '                    sys.stdout = stdout\n'
        '                caso(ROTULO_MAIN_SAI_ZERO.format(rodada), codigo == 0)\n'
