        '    ("cat lê o settings.json", pedido_de_shell("cat .claude/settings.json")),\n'
        '    ("grep varre os ganchos", pedido_de_shell(\n'
        '        "grep -n regra .claude/hooks/*.py")),\n'
        '    ("sed que só lê o gancho", pedido_de_shell(\n'
        '        "sed -n \'1,20p\' .claude/hooks/vetar-automacao.py")),\n'
        '    ("git show do settings.json", pedido_de_shell(\n'
        '        "git show HEAD:.claude/settings.json")),\n'
        '    ("a evidência da etapa, que é o trabalho da execução",\n'
        '     pedido_de_escrita("Write",\n'
        '                       "execucoes/evidencias/issue-185/1-trabalhar-c1.json")),\n'
        '    ("página nova em conhecimento/",\n'
        '     pedido_de_escrita("Write", "conhecimento/nova-pagina.md")),\n'
        '    ("o instalador, que é código e não política",\n'
        '     pedido_de_escrita("Edit", "montar.py")),\n'
        '    ("settings.local.json é pessoal e não é a política",\n'
        '     pedido_de_escrita("Edit", ".claude/settings.local.json")),\n'
        '    ("montar.py --sincronizar reescreve o settings por dentro e passa",\n'
