        '             ".claude/settings.json" in mensagem)\n'
        '        caso("a recusa nomeia a marca de ambiente e diz que em sessão do "\n'
        '             "dono ela não morde",\n'
        '             MARCA_DE_ETAPA_NO_AMBIENTE in mensagem\n'
        '             and "não morde" in mensagem)\n'
        '        caso("a recusa diz onde a lista se muda",\n'
        '             ARQUIVO_DOS_CAMINHOS_DE_POLITICA in mensagem)\n'
        '        caso("a recusa liga a cerca à bandeira que desligou a pergunta",\n'
        '             "--dangerously-skip-permissions" in mensagem)\n'
