            '\n'
            'def _guia_da_sessao() -> str:\n'
            '    return _cli_evidencia(["esquema-sessao"]).stdout.strip()\n'
            '\n'
            '\n'
            'def _bloco_de_regras(cwd) -> str:\n'
            '    fonte = Path(cwd) / ARQUIVO_DAS_REGRAS\n'
            '    try:\n'
            '        texto = fonte.read_text(encoding="utf-8")\n'
            '    except (OSError, UnicodeDecodeError):\n'
            '        return ""\n'
            '    try:\n'
            '        regras = json.loads(texto)["regras"]\n'
            '        frases = []\n'
            '        for regra in regras:\n'
            '            frases.append(_uma_linha(f"{regra[\'id\']}. {regra[\'regra\']}"))\n'
            '            if regra.get("id") in REGRAS_QUE_FALHARAM_EM_EXECUCAO:\n'
            '                frases += [f"- {_uma_linha(item)}"\n'
            '                           for item in regra.get("faca") or []]\n'
            '    except (json.JSONDecodeError, KeyError, TypeError):\n'
            '        print(AVISO_REGRAS_ILEGIVEIS.format(fonte), file=sys.stderr)\n'
            '        return ""\n'
            '    if not frases:\n'
            '        return ""\n'
            '    citado = _citado(frases)\n'
            '    if len(citado) > TETO_CONFIGURACAO:\n'
            '        print(AVISO_REGRAS_ACIMA_DO_TETO.format(fonte=fonte,\n'
            '                                                teto=TETO_CONFIGURACAO),\n'
            '              file=sys.stderr)\n'
            '        return ""\n'
            '    return CABECALHO_DAS_REGRAS + citado + FIM_DO_BLOCO\n'
            '\n'
            '\n'
            'def _linhas_da_configuracao(dados: dict) -> list:\n'
            '    linhas = []\n'
            '    for chave, valor in dados.items():\n'
            '        if chave in CHAVES_FORA_DO_BLOCO_DA_CONFIGURACAO:\n'
