            '        if isinstance(valor, list):\n'
            '            linhas.append(f"{chave}:")\n'
            '            linhas += [f"- {_uma_linha(item)}" for item in valor]\n'
            '        else:\n'
            '            linhas.append(f"{chave}: {_uma_linha(valor)}")\n'
            '    return linhas\n'
            '\n'
            '\n'
            'def _bloco_de_configuracao(cwd) -> str:\n'
            '    configuracao = Path(cwd) / ARQUIVO_DA_CONFIGURACAO\n'
            '    try:\n'
            '        texto = configuracao.read_text(encoding="utf-8")\n'
