            '        return ""\n'
            '    try:\n'
            '        linhas = _linhas_da_configuracao(json.loads(texto))\n'
            '    except (json.JSONDecodeError, AttributeError, TypeError):\n'
            '        print(AVISO_CONFIGURACAO_ILEGIVEL.format(configuracao),\n'
            '              file=sys.stderr)\n'
            '        return ""\n'
            '    if not linhas:\n'
            '        return ""\n'
            '    return CABECALHO_DA_CONFIGURACAO + _citado(linhas) + FIM_DO_BLOCO\n'
            '\n'
            '\n'
            'def _texto_do_prompt(etapa: dict) -> str:\n'
            '    referencia = etapa.get("prompt-de")\n'
