            '            encoding="utf-8")\n'
            '    except OSError:\n'
            '        return ""\n'
            '\n'
            '\n'
            'def _prompt_da_sessao(etapa: dict, cwd) -> str:\n'
            '    return (_bloco_de_regras(cwd) + _bloco_de_configuracao(cwd)\n'
            '            + _bloco_de_onde_esta(cwd) + _texto_do_prompt(etapa))\n'
            '\n'
            '\n'
            'def _branch_atual(cwd) -> str:\n'
            '    if not cwd:\n'
            '        return ""\n'
            '    try:\n'
            '        feito = subprocess.run(\n'
            '            ["git", "-C", str(cwd), "branch", "--show-current"],\n'
            '            capture_output=True, text=True, timeout=TEMPO_DO_GIT_LOCAL)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return ""\n'
            '    return feito.stdout.strip() if feito.returncode == 0 else ""\n'
            '\n'
            '\n'
            'def branch_que_a_issue_pede(padrao, issue) -> str:\n'
            '    if not padrao or isinstance(issue, bool) or not isinstance(issue, int):\n'
            '        return ""\n'
            '    if issue <= 0 or MARCA_DO_NUMERO_NO_PADRAO not in padrao:\n'
            '        return ""\n'
            '    return padrao.replace(MARCA_DO_NUMERO_NO_PADRAO, str(issue))\n'
            '\n'
            '\n'
            'def branch_fora_do_lugar(esperada: str, atual: str) -> bool:\n'
            '    if not esperada or not atual:\n'
            '        return False\n'
            '    molde = ".+".join(re.escape(pedaco)\n'
            '                      for pedaco in MARCA_LIVRE_NO_PADRAO.split(esperada))\n'
            '    return re.fullmatch(molde, atual) is None\n'
            '\n'
            '\n'
            'def onde_a_branch_se_mede(cwd, ambiente) -> tuple:\n'
            '    declarado = (ambiente or {}).get(VARIAVEL_DO_ALVO, "").strip()\n'
            '    if not declarado:\n'
            '        return cwd, TEXTOS_DA_BRANCH_DO_WORKSPACE\n'
            '    alvo = Path(declarado).expanduser()\n'
            '    if not alvo.is_absolute() and cwd:\n'
            '        alvo = Path(cwd) / alvo\n'
            '    return alvo, TEXTOS_DA_BRANCH_DO_ALVO\n'
            '\n'
            '\n'
            'def _recusa_da_branch(cwd, ambiente=None) -> dict:\n'
            '    esperada = _EM_CURSO.get("branch_esperada") or ""\n'
            '    onde, textos = onde_a_branch_se_mede(cwd, ambiente)\n'
            '    atual = _branch_atual(onde) if esperada else ""\n'
            '    if not branch_fora_do_lugar(esperada, atual):\n'
            '        return {}\n'
