            '            "proximo": PROXIMO_DA_BRANCH.format(esperada=esperada)}\n'
            '\n'
            '\n'
            'def _linhas_do_corpo_da_issue() -> list:\n'
            '    corpo = (_EM_CURSO.get(CORPO_DA_ISSUE) or "").strip()\n'
            '    if not corpo:\n'
            '        return []\n'
            '    cortado = len(corpo) > TETO_DO_CORPO_NO_PROMPT\n'
            '    linhas = [ONDE_CORPO_DA_ISSUE]\n'
            '    linhas += [ONDE_LINHA_DO_CORPO.format(linha) for linha in\n'
            '               corpo[:TETO_DO_CORPO_NO_PROMPT].splitlines()]\n'
            '    if cortado:\n'
            '        linhas.append(CORPO_CORTADO_NO_PROMPT.format(\n'
            '            teto=TETO_DO_CORPO_NO_PROMPT, total=len(corpo)))\n'
            '    return linhas\n'
            '\n'
            '\n'
            'def _enderecos_declarados(raiz: Path) -> list:\n'
            '    try:\n'
            '        dados = json.loads((raiz / ARQUIVO_DA_CONFIGURACAO).read_text(\n'
            '            encoding="utf-8"))\n'
            '    except (OSError, UnicodeDecodeError, ValueError):\n'
            '        return []\n'
            '    declarados = (dados.get(CHAVE_DOS_ENDERECOS)\n'
            '                  if isinstance(dados, dict) else None)\n'
            '    if not isinstance(declarados, list):\n'
            '        return []\n'
            '    return [caminho for caminho in declarados\n'
            '            if isinstance(caminho, str) and caminho]\n'
            '\n'
            '\n'
            'def _linhas_dos_enderecos(cwd) -> list:\n'
            '    if not cwd:\n'
            '        return []\n'
            '    raiz = Path(cwd)\n'
            '    achados = [caminho for caminho in _enderecos_declarados(raiz)\n'
            '               if (raiz / caminho).exists()]\n'
            '    if not achados:\n'
            '        return []\n'
            '    return [ONDE_ENDERECOS] + [ONDE_UM_ENDERECO.format(caminho)\n'
            '                               for caminho in achados]\n'
            '\n'
            '\n'
            'def _bloco_de_onde_esta(cwd=None) -> str:\n'
            '    if not _EM_CURSO.get("trabalho"):\n'
            '        return ""\n'
            '    pasta = Path(_EM_CURSO["dir_base"]) / _EM_CURSO["trabalho"]\n'
            '    linhas = [ONDE_TRABALHO.format(_EM_CURSO["trabalho"]),\n'
            '              ONDE_EVIDENCIAS.format(pasta)]\n'
            '    if _EM_CURSO.get("issue"):\n'
            '        linhas.append(ONDE_ISSUE.format(_EM_CURSO["issue"]))\n'
            '    if _EM_CURSO.get("bloco"):\n'
            '        linhas.append(ONDE_ESCOPO.format(_EM_CURSO["bloco"]))\n'
            '        linhas.append(ONDE_ESCOPO_NA_COBRANCA)\n'
            '    if (branch := _branch_atual(cwd)):\n'
            '        linhas.append(ONDE_BRANCH.format(branch))\n'
            '    linhas += _linhas_do_corpo_da_issue()\n'
            '    linhas += _linhas_dos_enderecos(cwd)\n'
            '    try:\n'
            '        foto = foto_das_etapas(pasta)\n'
            '    except OSError as erro:\n'
            '        print(AVISO_FOTO_ILEGIVEL.format(erro), file=sys.stderr)\n'
            '        foto = {}\n'
            '    if foto:\n'
            '        linhas.append(ONDE_JA_RODARAM)\n'
            '        for nome in sorted(foto):\n'
            '            ciclo, veredito = foto[nome]\n'
            '            linhas.append(ONDE_UMA_ETAPA.format(nome=nome, veredito=veredito,\n'
            '                                                ciclo=ciclo))\n'
            '    if (faltam := [n for n in _EM_CURSO.get("etapas", []) if n not in foto]):\n'
            '        linhas.append(ONDE_SEM_EVIDENCIA.format(", ".join(faltam)))\n'
            '    if (resposta := _EM_CURSO.get("resposta")):\n'
            '        linhas.append(ONDE_O_DONO_RESPONDEU)\n'
            '        linhas += [ONDE_LINHA_DA_RESPOSTA.format(linha)\n'
            '                   for linha in resposta.splitlines()]\n'
            '\n'
            '    bloco = (CABECALHO_DE_ONDE_ESTA + "\\n".join(linhas) + FIM_DE_ONDE_ESTA)\n'
            '    if len(bloco) > TETO_CONFIGURACAO:\n'
            '        print(AVISO_ONDE_ACIMA_DO_TETO.format(TETO_CONFIGURACAO),\n'
            '              file=sys.stderr)\n'
            '        return ""\n'
            '    return bloco\n'
            '\n'
            '\n'
            'def _com_os_valores(bandeiras: list, guia: str, turnos: str) -> list:\n'
            '    posto = {MARCA_DO_GUIA: guia, MARCA_DOS_TURNOS: turnos}\n'
            '    return [posto.get(bandeira, bandeira) for bandeira in bandeiras]\n'
            '\n'
            '\n'
            'def _modelo_por_etapa_declarado(cwd) -> dict:\n'
            '    try:\n'
            '        dado = json.loads((Path(cwd) / ARQUIVO_DA_CONFIGURACAO).read_text(\n'
            '            encoding="utf-8"))\n'
            '    except (OSError, UnicodeDecodeError, ValueError):\n'
            '        return {}\n'
            '    declarado = dado.get(CAMPO_MODELO_POR_ETAPA) if isinstance(dado, dict) \\\n'
            '        else None\n'
            '    return declarado if isinstance(declarado, dict) else {}\n'
            '\n'
            '\n'
            'def _modelo_da_etapa(etapa: dict, cwd) -> str:\n'
            '    proprio = etapa.get("modelo")\n'
            '    if isinstance(proprio, str) and proprio:\n'
            '        return proprio\n'
            '    central = _modelo_por_etapa_declarado(cwd).get(etapa["nome"])\n'
            '    return central if isinstance(central, str) else ""\n'
            '\n'
            '\n'
            'def _comando_sessao(etapa: dict, cwd, retomar: str = "") -> list:\n'
            '    comando = list(SESSAO)\n'
            '    if retomar:\n'
            '        comando += [*RETOMADA_DA_SESSAO, retomar]\n'
            '    if etapa.get("bare") and BANDEIRA_SEM_CAMADA:\n'
            '        comando.append(BANDEIRA_SEM_CAMADA)\n'
            '    if modelo := _modelo_da_etapa(etapa, cwd):\n'
            '        comando += [BANDEIRA_MODELO, modelo]\n'
            '    if (negadas := etapa.get("ferramentas-negadas")) \\\n'
            '            and BANDEIRA_FERRAMENTAS_NEGADAS:\n'
            '        comando += [BANDEIRA_FERRAMENTAS_NEGADAS, ",".join(negadas)]\n'
            '    return comando + _com_os_valores(\n'
            '        BANDEIRAS_DA_SESSAO, _guia_da_sessao(),\n'
            '        str(etapa.get("max-turnos", MAX_TURNOS_PADRAO)))\n'
            '\n'
            '\n'
            'def rodar_etapa(etapa, ordem, trabalho, dir_base, cwd, ambiente, teto,\n'
            '                materializados=None, configuracao=None, issue=None):\n'
            '    base = ["--dir", dir_base, "--trabalho", trabalho,\n'
            '            "--etapa", etapa["nome"], "--ordem", str(ordem),\n'
            '            "--teto", str(teto)]\n'
            '\n'
            '    if not etapa.get("ligada", True):\n'
            '        return _evidencia_sintetica(base, "desligada")\n'
            '    if etapa["tipo"] == "verificacao":\n'
            '        return _rodar_verificacao(etapa, base, ordem, trabalho, dir_base, cwd,\n'
            '                                  ambiente, materializados)\n'
            '    if etapa["tipo"] == "aprovacao-manual":\n'
            '        return _rodar_aprovacao_manual(etapa, base, cwd, trabalho,\n'
            '                                       configuracao, issue)\n'
            '    if etapa["tipo"] == "sessao" and (parada := _recusa_da_branch(\n'
            '            cwd, ambiente)):\n'
            '        return _materializar_envelope(base, parada)\n'
            '\n'
            '    log = _log_da_etapa(dir_base, trabalho, ordem, etapa["nome"])\n'
            '    marcas = {}\n'
            '    try:\n'
            '        if etapa["tipo"] == "codigo":\n'
            '            codigo_saida, saida, erro = _rodar_processo(\n'
            '                etapa["comando"], shell=True, cwd=cwd, env=ambiente,\n'
            '                entrada=None, tempo=etapa.get("tempo-limite", TEMPO_CODIGO))\n'
            '        else:\n'
            '            codigo_saida, saida, erro, marcas = _sessao_com_retomada(\n'
            '                etapa, cwd=cwd, ambiente=ambiente, log=log,\n'
            '                rotulo=f"{ordem:02d}-{etapa[\'nome\']}")\n'
            '    except TempoEstourado as estouro:\n'
            '        log.write_text(f"{estouro}\\n", encoding="utf-8")\n'
            '        return _evidencia_sintetica(base, "morta",\n'
            '                                    DETALHE_TEMPO_ESTOURADO.format(\n'
            '                                        estouro=estouro, log=log))\n'
            '\n'
            '    _guardar_no_log(log, etapa["tipo"], saida, erro)\n'
            '    if codigo_saida != 0:\n'
            '        detalhe = _porque_morreu(codigo_saida, saida, log)\n'
            '        if etapa["tipo"] == "sessao" and marcas.get("ditos"):\n'
            '            detalhe += DETALHE_DO_QUE_ELA_DIZIA.format(\n'
            '                " ⏎ ".join(dito[:LIMITE_DO_DITO]\n'
            '                           for dito in marcas["ditos"][-DITOS_NA_EVIDENCIA:]))\n'
            '        return _evidencia_sintetica(base, "morta",\n'
            '                                    detalhe[:LIMITE_DO_DETALHE])\n'
            '    feito = _cli_evidencia(["materializar"] + base\n'
            '                           + _bandeira_de_turnos(saida)\n'
            '                           + _bandeira_de_custo(saida), entrada=saida)\n'
            '    return feito.stdout.strip()\n'
            '\n'
            '\n'
            'def _bandeira_de_turnos(saida: str) -> list:\n'
            '    turnos = _resultado_da_sessao(saida).get("num_turns")\n'
            '    return ([BANDEIRA_DOS_TURNOS, str(turnos)]\n'
            '            if isinstance(turnos, int) and turnos > 0 else [])\n'
            '\n'
            '\n'
            'def _numero_de_tokens(valor) -> bool:\n'
            '    return (isinstance(valor, int) and not isinstance(valor, bool)\n'
            '            and valor >= 0)\n'
            '\n'
            '\n'
            'def _custo_da_sessao(saida: str):\n'
            '    dado = _resultado_da_sessao(saida)\n'
            '    usd = dado.get("total_cost_usd")\n'
            '    uso = dado.get("usage")\n'
            '    if isinstance(usd, bool) or not isinstance(usd, (int, float)) \\\n'
            '            or usd < 0 or not isinstance(uso, dict):\n'
            '        return None\n'
            '    tokens = {nosso: uso.get(deles) for nosso, deles in TOKENS_DO_CUSTO}\n'
            '    if not all(_numero_de_tokens(valor) for valor in tokens.values()):\n'
            '        return None\n'
            '    return {"usd": usd, "tokens": tokens}\n'
            '\n'
            '\n'
            'def _bandeira_de_custo(saida: str) -> list:\n'
            '    custo = _custo_da_sessao(saida)\n'
            '    return ([BANDEIRA_DO_CUSTO, json.dumps(custo, ensure_ascii=False)]\n'
            '            if custo else [])\n'
            '\n'
            '\n'
            'def _custo_da_execucao(pasta) -> str:\n'
            '    total, medidas, todas = 0.0, 0, 0\n'
            '    for arquivo in sorted(Path(pasta).glob("*.json")):\n'
            '        if not PADRAO_NOME_EVIDENCIA.match(arquivo.name):\n'
            '            continue\n'
            '        todas += 1\n'
            '        try:\n'
            '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
            '        except (OSError, ValueError):\n'
            '            continue\n'
            '        custo = dado.get("custo") if isinstance(dado, dict) else None\n'
            '        usd = custo.get("usd") if isinstance(custo, dict) else None\n'
            '        if isinstance(usd, (int, float)) and not isinstance(usd, bool):\n'
            '            total += usd\n'
            '            medidas += 1\n'
            '    if not medidas:\n'
            '        return CUSTO_SEM_MEDICAO\n'
            '    return CUSTO_MEDIDO.format(total=total, medidas=medidas, todas=todas)\n'
            '\n'
            '\n'
            'def _log_da_etapa(dir_base, trabalho, ordem, nome) -> Path:\n'
            '    previsto, _ = _evidencia.caminho_da_evidencia(dir_base, trabalho, ordem,\n'
            '                                                  nome)\n'
            '    log = previsto.with_suffix(".log")\n'
            '    log.parent.mkdir(parents=True, exist_ok=True)\n'
            '    return log\n'
            '\n'
            '\n'
            'def _guardar_no_log(log: Path, tipo: str, saida: str, erro: str) -> None:\n'
            '    if tipo != "sessao":\n'
            '        log.write_text(MOLDE_DO_LOG.format(saida=saida, erro=erro),\n'
            '                       encoding="utf-8")\n'
            '    elif erro.strip():\n'
            '        with log.open("a", encoding="utf-8") as diario:\n'
            '            diario.write(SO_O_STDERR.format(erro))\n'
            '\n'
            '\n'
            'def _porque_morreu(codigo_saida: int, saida: str, log) -> str:\n'
            '    dado = _resultado_da_sessao(saida)\n'
            '    partes = []\n'
            '    if (motivo := MORTE_CONHECIDA.get(dado.get("subtype"))):\n'
            '        partes.append(motivo)\n'
            '    elif dado.get("subtype"):\n'
            '        partes.append(MORTE_DESCONHECIDA.format(dado["subtype"]))\n'
            '    if isinstance(dado.get("result"), str) and dado["result"].strip():\n'
            '        partes.append(MORTE_O_QUE_ELA_DISSE.format(\n'
            '            dado["result"].strip()[:LIMITE_DO_RECADO]))\n'
            '    if (turnos := dado.get("num_turns")):\n'
            '        partes.append(MORTE_TURNOS_GASTOS.format(turnos))\n'
            '    if not partes:\n'
            '        return MORTE_SEM_CAUSA.format(codigo=codigo_saida, log=log)\n'
            '    return "; ".join(partes) + MORTE_LEIA_O_LOG.format(log)\n'
            '\n'
            '\n'
            'def auditar_ao_fim(pasta, cwd, ambiente,\n'
            '                   tempo=TEMPO_DA_AUDITORIA) -> None:\n'
            '    if not AUDITOR.is_file():\n'
            '        print(LOG_AUDITOR_AUSENTE.format(AUDITOR))\n'
            '        return\n'
            '    print(LOG_AUDITORIA_AO_FIM)\n'
            '    try:\n'
            '        _, saida, erro = _rodar_processo(\n'
            '            [sys.executable, str(AUDITOR), str(pasta), "--cwd", cwd],\n'
            '            shell=False, cwd=None, env=ambiente, entrada=None, tempo=tempo)\n'
            '    except (TempoEstourado, OSError) as falha:\n'
            '        print(LOG_AUDITORIA_NAO_RODOU.format(falha))\n'
            '        return\n'
            '    relato = f"{saida}{erro}".strip()\n'
            '    if relato:\n'
            '        print(relato)\n'
            '\n'
            '\n'
            'def verificacao_de(alvo) -> Path:\n'
            '    alvo = Path(alvo)\n'
            '    return alvo.parent / "verificacoes" / alvo.name\n'
            '\n'
            '\n'
            'CORPO_DA_ISSUE = "corpo_da_issue"\n'
            'MODO_CRITERIOS = "criterios"\n'
            'BANDEIRA_DOS_CRITERIOS = "--criterios"\n'
            'BANDEIRA_DO_BLOCO = "--bloco"\n'
            'BANDEIRA_DO_TEMPO_DA_PROVA = "--tempo-limite"\n'
            'ENTRADA_PADRAO = "-"\n'
            'ARGUMENTOS_DO_CORPO = ["issue", "view", "{numero}", "--repo", "{repo}",\n'
            '                       "--json", "body", "-q", ".body"]\n'
            'SEM_CORPO_DA_ISSUE = ("o corpo da issue nao foi lido — os criterios de pronto "\n'
            '                      "nao foram verificados nesta rodada")\n'
            'ACUSA_CORPO_NAO_LIDO = ("ACUSA issue declarada e corpo nao lido — os "\n'
            '                        "criterios de pronto nao foram verificados; o gh "\n'
            '                        "falhou ou a issue nao esta acessivel")\n'
            '\n'
            '\n'
            'def corpo_da_issue(configuracao, issue) -> str:\n'
            '    repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '    if not issue or not repositorio:\n'
            '        return ""\n'
            '    feito = _gh_na_conta_das_issues(configuracao, [\n'
            '        p.format(numero=issue, repo=repositorio) for p in ARGUMENTOS_DO_CORPO])\n'
            '    return feito.stdout if feito and feito.returncode == 0 else ""\n'
            '\n'
            '\n'
            'def _comando_de_criterios(pasta) -> list:\n'
            '    comando = [sys.executable, str(VERIFICAR), MODO_CRITERIOS, str(pasta),\n'
            '               BANDEIRA_DOS_CRITERIOS, ENTRADA_PADRAO]\n'
            '    if (bloco := _EM_CURSO.get("bloco")):\n'
            '        comando += [BANDEIRA_DO_BLOCO, str(bloco)]\n'
            '    return comando\n'
            '\n'
            '\n'
            'def _acusacoes_dos_criterios(trabalho, dir_base, ambiente, tempo):\n'
            '    corpo = _EM_CURSO.get(CORPO_DA_ISSUE) or ""\n'
            '    if not corpo.strip():\n'
            '        if _EM_CURSO.get("issue"):\n'
            '            return EXIT_VERIFICACAO_ACUSOU, ACUSA_CORPO_NAO_LIDO\n'
            '        return 0, SEM_CORPO_DA_ISSUE\n'
            '    pasta = Path(dir_base) / trabalho\n'
            '    try:\n'
            '        codigo, saida, erro = _rodar_processo(\n'
            '            _comando_de_criterios(pasta), shell=False, cwd=None,\n'
            '            env=ambiente, entrada=corpo, tempo=tempo)\n'
            '    except (TempoEstourado, OSError) as falha:\n'
            '        return 0, NAO_VERIFICADO_NA_JANELA.format(falha)\n'
            '    return codigo, f"{saida}{erro}".strip()\n'
            '\n'
            '\n'
            'def _comando_de_verificar(alvo, cwd) -> list:\n'
            '    comando = [sys.executable, str(VERIFICAR), "evidencia", str(alvo),\n'
            '               "--cwd", cwd]\n'
            '    if (teto := _EM_CURSO.get(CAMPO_DO_TEMPO_DA_PROVA)):\n'
            '        comando += [BANDEIRA_DO_TEMPO_DA_PROVA, str(teto)]\n'
            '    return comando\n'
            '\n'
            '\n'
            'def verificar_na_janela(alvo, cwd, ambiente, tempo) -> None:\n'
            '    onde = verificacao_de(alvo)\n'
            '    onde.parent.mkdir(parents=True, exist_ok=True)\n'
            '    try:\n'
            '        codigo, saida, erro = _rodar_processo(\n'
            '            _comando_de_verificar(alvo, cwd), shell=False, cwd=None,\n'
            '            env=ambiente, entrada=None, tempo=tempo)\n'
            '    except (TempoEstourado, OSError) as falha:\n'
            '        codigo, saida, erro = (EXIT_ERRO_DE_USO_OU_AMBIENTE, "",\n'
            '                               NAO_VERIFICADO_NA_JANELA.format(falha))\n'
            '    _evidencia.escrever_atomico(onde, {\n'
            '        "alvo": Path(alvo).name,\n'
            '        "quando": _evidencia.agora(),\n'
            '        "exit": codigo,\n'
            '        "saida": f"{saida}{erro}".strip(),\n'
            '    })\n'
            '\n'
            '\n'
            'def _verificacao_gravada(alvo):\n'
            '    gravado = verificacao_de(alvo)\n'
            '    if not gravado.is_file():\n'
            '        return None\n'
            '    try:\n'
            '        dado = json.loads(gravado.read_text(encoding="utf-8"))\n'
            '        return int(dado["exit"]), dado.get("saida", ""), "", True\n'
            '    except (OSError, ValueError, KeyError, TypeError) as ilegivel:\n'
            '        return (EXIT_ERRO_DE_USO_OU_AMBIENTE, "",\n'
            '                VERIFICACAO_DA_JANELA_ILEGIVEL.format(ilegivel), False)\n'
            '\n'
            '\n'
            'def _ciclo_que_acusou(dir_base, trabalho, nome):\n'
            '    ciclo, veredito = foto_das_etapas(\n'
            '        Path(dir_base) / trabalho).get(nome, (0, None))\n'
            '    return ciclo if veredito == "para" else None\n'
            '\n'
            '\n'
            'def _evidencias_que_a_retomada_pulou(dir_base, trabalho, nome) -> list:\n'
            '    ultimas = {}\n'
            '    for arquivo in (Path(dir_base) / trabalho).glob("*.json"):\n'
            '        casado = PADRAO_NOME_EVIDENCIA.match(arquivo.name)\n'
            '        if not casado or casado.group(2) == nome:\n'
            '            continue\n'
            '        etapa, ciclo = casado.group(2), int(casado.group(3))\n'
            '        if ciclo >= ultimas.get(etapa, (0, None))[0]:\n'
            '            ultimas[etapa] = (ciclo, arquivo)\n'
            '    return sorted(str(arquivo) for _, arquivo in ultimas.values())\n'
            '\n'
            '\n'
            'def _rodar_verificacao(etapa, base, ordem, trabalho, dir_base, cwd, ambiente,\n'
            '                       materializados):\n'
            '    log = _log_da_etapa(dir_base, trabalho, ordem, etapa["nome"])\n'
            '    alvos = list(materializados or [])\n'
            '    recobra = None\n'
            '    if not alvos:\n'
            '        recobra = _ciclo_que_acusou(dir_base, trabalho, etapa["nome"])\n'
            '        if recobra is None:\n'
            '            log.write_text(NADA_A_VERIFICAR + "\\n", encoding="utf-8")\n'
            '            return _materializar_envelope(base, _envelope_de_uma_prova(\n'
            '                NADA_A_VERIFICAR_AFIRMACAO, log, NADA_A_VERIFICAR))\n'
            '        alvos = _evidencias_que_a_retomada_pulou(dir_base, trabalho,\n'
            '                                                 etapa["nome"])\n'
            '\n'
            '    saidas, pior, na_janela = [], 0, 0\n'
            '    for alvo in alvos:\n'
            '        colhido = _verificacao_gravada(alvo)\n'
            '        if colhido:\n'
            '            codigo_um, saida_um, erro_um, contou = colhido\n'
            '            na_janela += 1 if contou else 0\n'
            '        else:\n'
            '            try:\n'
            '                codigo_um, saida_um, erro_um = _rodar_processo(\n'
            '                    _comando_de_verificar(alvo, cwd), shell=False, cwd=None,\n'
            '                    env=ambiente, entrada=None,\n'
            '                    tempo=etapa.get("tempo-limite", TEMPO_CODIGO))\n'
            '            except TempoEstourado as estouro:\n'
            '                log.write_text("\\n".join(saidas) + f"\\n{estouro}\\n",\n'
            '                               encoding="utf-8")\n'
            '                return _evidencia_sintetica(\n'
            '                    base, "morta", DETALHE_VERIFICACAO_MORTA.format(estouro))\n'
            '        saidas.append(CABECALHO_DE_UM_ALVO.format(\n'
            '            nome=Path(alvo).name, saida=saida_um, erro=erro_um).strip())\n'
            '        pior = max(pior, codigo_um)\n'
            '\n'
            '    codigo_criterios, saida_criterios = _acusacoes_dos_criterios(\n'
            '        trabalho, dir_base, ambiente,\n'
            '        etapa.get("tempo-limite", TEMPO_CODIGO))\n'
            '    saidas.append(saida_criterios)\n'
            '    pior = max(pior, codigo_criterios)\n'
            '\n'
            '    desfecho = SEM_ACUSACAO if pior == 0 else PIOR_EXIT.format(pior)\n'
            '    if recobra is None:\n'
            '        resumo = RESUMO_DA_VERIFICACAO.format(alvos=len(alvos),\n'
            '                                              na_janela=na_janela,\n'
            '                                              desfecho=desfecho)\n'
            '        passou = VERIFICACAO_SEM_ACUSACOES\n'
            '    else:\n'
            '        resumo = RESUMO_DA_RECOBRA.format(alvos=len(alvos), ciclo=recobra,\n'
            '                                          na_janela=na_janela,\n'
            '                                          desfecho=desfecho)\n'
            '        passou = RECOBRADA_SEM_ACUSACOES.format(ciclo=recobra)\n'
            '    log.write_text("\\n".join(saidas) + f"\\n{resumo}\\n", encoding="utf-8")\n'
            '\n'
            '    if pior == 0:\n'
            '        envelope = _envelope_de_uma_prova(passou, log, resumo)\n'
            '    elif pior == EXIT_VERIFICACAO_ACUSOU:\n'
            '        acusacoes = [linha for linha in "\\n".join(saidas).splitlines()\n'
            '                     if linha.startswith(PREFIXO_DA_ACUSACAO)]\n'
            '        envelope = {"veredito": "para", "provado": [], "suposto": [],\n'
            '                    "faltas": (acusacoes[:LIMITE_DAS_ACUSACOES]\n'
            '                               or [VERIFICACAO_ACUSOU]),\n'
            '                    "proximo": PROXIMO_DA_VERIFICACAO.format(\n'
            '                        log=log.name, trabalho=trabalho)}\n'
            '    else:\n'
            '        return _evidencia_sintetica(\n'
            '            base, "morta",\n'
            '            DETALHE_VERIFICACAO_COM_ERRO.format(EXIT_ERRO_DE_USO_OU_AMBIENTE))\n'
            '    return _materializar_envelope(base, envelope)\n'
            '\n'
            '\n'
            'def _rodar_aprovacao_manual(etapa, base, cwd, trabalho, configuracao=None,\n'
            '                            issue=None):\n'
            '    arquivo = Path(cwd) / etapa["aprovacao"]\n'
            '    if arquivo.is_file():\n'
            '        envelope = {"veredito": "segue",\n'
            '                    "provado": [{\n'
            '                        "afirmacao": APROVACAO_REGISTRADA,\n'
            '                        "comando": COMANDO_QUE_LE_A_APROVACAO.format(\n'
            '                            shlex.quote(str(arquivo))),\n'
            '                        "saida": SAIDA_APROVADO}],\n'
            '                    "suposto": [], "faltas": []}\n'
            '        return _materializar_envelope(base, envelope)\n'
            '\n'
            '    corpo, autor, _ = resposta_na_issue(configuracao, issue)\n'
            '    if corpo:\n'
            '        repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '        envelope = {"veredito": "segue",\n'
            '                    "provado": [{\n'
            '                        "afirmacao": APROVACAO_POR_COMENTARIO_REGISTRADA.format(\n'
            '                            autor),\n'
            '                        "comando": COMANDO_QUE_LE_A_APROVACAO_POR_COMENTARIO\n'
            '                        .format(issue=issue, repositorio=repositorio),\n'
            '                        "saida": autor}],\n'
            '                    "suposto": [], "faltas": []}\n'
            '        return _materializar_envelope(base, envelope)\n'
            '\n'
            '    relativo = (Path(arquivo).name if Path(arquivo).is_absolute()\n'
            '                else arquivo)\n'
            '    envelope = {"veredito": "pergunta", "provado": [], "suposto": [],\n'
            '                "faltas": [],\n'
            '                "pergunta": PERGUNTA_DA_APROVACAO.format(\n'
            '                    trabalho=trabalho, etapa=etapa["nome"],\n'
            '                    arquivo=relativo)}\n'
            '    return _materializar_envelope(base, envelope)\n'
            '\n'
            '\n'
            'def _rotulo(etapa, ordem, cwd="."):\n'
            '    inicio = f"{ordem:02d}-{etapa[\'nome\']}"\n'
            '    if not etapa.get("ligada", True):\n'
            '        texto = f"{inicio} {ROTULO_DESLIGADA}"\n'
            '    elif etapa["tipo"] == "codigo":\n'
            '        texto = f"{inicio} " + ROTULO_CODIGO.format(etapa["comando"])\n'
            '    elif etapa["tipo"] == "sessao":\n'
            '        modelo = _modelo_da_etapa(etapa, cwd)\n'
            '        rotulo = ROTULO_SESSAO_COM_MODELO if modelo else ROTULO_SESSAO\n'
            '        texto = f"{inicio} " + rotulo.format(\n'
            '            comando=" ".join(SESSAO), modelo=modelo,\n'
            '            turnos=etapa.get("max-turnos", MAX_TURNOS_PADRAO))\n'
            '    elif etapa["tipo"] == "aprovacao-manual":\n'
            '        texto = f"{inicio} " + ROTULO_APROVACAO.format(etapa["aprovacao"])\n'
            '    else:\n'
            '        texto = f"{inicio} {ROTULO_VERIFICACAO}"\n'
            '    return texto.replace("\\r", "\\\\r").replace("\\n", "\\\\n")\n'
            '\n'
            '\n'
            'def ensaio(roteiro, trabalho, dir_base, cwd=".") -> int:\n'
            '    etapas = roteiro["etapas"]\n'
            '    ordem_de = {e["nome"]: n for n, e in enumerate(etapas, start=1)}\n'
            '    print(LOG_ENSAIO.format(trabalho))\n'
            '    for n, estagio in enumerate(estagios_de(etapas), start=1):\n'
            '        nomes = ", ".join(_rotulo(e, ordem_de[e["nome"]], cwd) for e in estagio)\n'
            '        print(LOG_ESTAGIO_DO_ENSAIO.format(n=n,\n'
            '                                           marca=_marca_do_estagio(estagio),\n'
            '                                           nomes=nomes))\n'
            '    print(LOG_ONDE_AS_EVIDENCIAS_IRIAM.format(Path(dir_base) / trabalho))\n'
            '    return EXIT_COMPLETA\n'
            '\n'
            '\n'
            'def e_a_evidencia_do_proprio_teto(dado: dict) -> bool:\n'
            '    return (dado.get("origem") == ORIGEM_SINTETICA\n'
            '            and dado.get("motivo") == MOTIVO_DO_TETO)\n'
            '\n'
            '\n'
            'def _contar_paras(pasta: Path) -> int:\n'
            '    total = 0\n'
            '    if not pasta.is_dir():\n'
            '        return 0\n'
            '    for arquivo in pasta.glob("*.json"):\n'
            '        try:\n'
            '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
            '            if not isinstance(dado, dict):\n'
            '                raise ValueError(ERRO_NAO_E_OBJETO_DE_EVIDENCIA)\n'
            '            if (dado.get("veredito") == "para"\n'
            '                    and not e_a_evidencia_do_proprio_teto(dado)):\n'
            '                total += 1\n'
            '        except (OSError, ValueError):\n'
            '            print(AVISO_EVIDENCIA_ILEGIVEL.format(arquivo.name),\n'
            '                  file=sys.stderr)\n'
            '            total += 1\n'
            '    return total\n'
            '\n'
            '\n'
            'def caminho_do_estado(dir_base, trabalho) -> Path:\n'
            '    return Path(dir_base) / trabalho / ARQUIVO_ESTADO\n'
            '\n'
            '\n'
            'def duraveis_guardados(alvo: Path) -> dict:\n'
            '    try:\n'
            '        dado = json.loads(alvo.read_text(encoding="utf-8"))\n'
            '    except (OSError, ValueError):\n'
            '        return {}\n'
            '    if not isinstance(dado, dict):\n'
            '        return {}\n'
            '    return {campo: dado[campo] for campo in CAMPOS_DURAVEIS_DO_ESTADO\n'
            '            if dado.get(campo) is not None}\n'
            '\n'
            '\n'
            'def gravar_estado(dir_base, trabalho, situacao, **extra) -> None:\n'
            '    if situacao not in SITUACOES:\n'
            '        raise ValueError(ERRO_SITUACAO_DESCONHECIDA.format(situacao))\n'
            '    alvo = caminho_do_estado(dir_base, trabalho)\n'
            '    alvo.parent.mkdir(parents=True, exist_ok=True)\n'
            '    dado = {"situacao": situacao, "desde": _evidencia.agora(),\n'
            '            "pid": os.getpid(),\n'
            '            **duraveis_guardados(alvo),\n'
            '            **{k: v for k, v in extra.items() if v is not None}}\n'
            '    tmp = alvo.with_name(alvo.name + ".tmp")\n'
            '    tmp.write_text(json.dumps(dado, ensure_ascii=False, indent=2) + "\\n",\n'
            '                   encoding="utf-8")\n'
            '    tmp.replace(alvo)\n'
            '\n'
            '\n'
            'def gravar_ambiente_da_execucao(pasta, ambiente) -> None:\n'
            '    alvo = Path(pasta) / ARQUIVO_DO_AMBIENTE\n'
            '    alvo.parent.mkdir(parents=True, exist_ok=True)\n'
            '    dado = {"gravado": _evidencia.agora(),\n'
            '            "variaveis": {nome: ambiente[nome]\n'
            '                          for nome in VARIAVEIS_QUE_A_EVIDENCIA_GUARDA\n'
            '                          if (ambiente.get(nome) or "").strip()}}\n'
            '    tmp = alvo.with_name(alvo.name + ".tmp")\n'
            '    tmp.write_text(json.dumps(dado, ensure_ascii=False, indent=2) + "\\n",\n'
            '                   encoding="utf-8")\n'
            '    tmp.replace(alvo)\n'
            '\n'
            '\n'
            'def processo_vivo(pid) -> bool:\n'
            '    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:\n'
            '        return False\n'
            '    try:\n'
            '        os.kill(pid, 0)\n'
            '    except ProcessLookupError:\n'
            '        return False\n'
            '    except PermissionError:\n'
            '        return True\n'
            '    except OSError:\n'
            '        return False\n'
            '    return True\n'
            '\n'
            '\n'
            'def ultima_escrita_do_trabalho(dir_base, trabalho):\n'
            '    instantes = []\n'
            '    pasta = Path(dir_base) / trabalho\n'
            '    with contextlib.suppress(OSError):\n'
            '        for log in pasta.glob(f"*{SUFIXO_DO_LOG_DA_ETAPA}"):\n'
            '            with contextlib.suppress(OSError):\n'
            '                instantes.append(log.stat().st_mtime)\n'
            '    return max(instantes, default=None)\n'
            '\n'
            '\n'
            'def _instante_legivel(momento: float) -> str:\n'
            '    return datetime.fromtimestamp(momento).astimezone().isoformat(\n'
            '        timespec="seconds")\n'
            '\n'
            '\n'
            'def situacao_provada(dir_base, trabalho, gravado):\n'
            '    if not gravado or gravado.get("situacao") != "rodando":\n'
            '        return gravado\n'
            '    escrita = ultima_escrita_do_trabalho(dir_base, trabalho)\n'
            '    provada = dict(gravado)\n'
            '    if escrita is not None:\n'
            '        provada["escrita_em"] = _instante_legivel(escrita)\n'
            '    escreveu_agora = (escrita is not None\n'
            '                      and time.time() - escrita < FOLGA_DA_PROVA_DE_VIDA_S)\n'
            '    if not (processo_vivo(gravado.get("pid")) or escreveu_agora):\n'
            '        provada["situacao"] = SITUACAO_SEM_PROVA_DE_VIDA\n'
            '        provada["situacao_gravada"] = "rodando"\n'
            '    return provada\n'
            '\n'
            '\n'
            'def ler_estado(dir_base, trabalho):\n'
            '    alvo = caminho_do_estado(dir_base, trabalho)\n'
            '    try:\n'
            '        dado = json.loads(alvo.read_text(encoding="utf-8"))\n'
            '    except (OSError, ValueError):\n'
            '        return None\n'
            '    return (situacao_provada(dir_base, trabalho, dado)\n'
            '            if isinstance(dado, dict) else None)\n'
            '\n'
            '\n'
            'def _token_da_conta(conta):\n'
            '    if not conta:\n'
            '        return None\n'
            '    try:\n'
            '        achado = subprocess.run(GH + ["auth", "token", "--user", conta],\n'
            '                                capture_output=True, text=True,\n'
            '                                timeout=TEMPO_DO_TOKEN)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return None\n'
            '    return achado.stdout.strip() or None\n'
            '\n'
            '\n'
            'def _conta_das_issues(configuracao):\n'
            '    return _campo(configuracao or {}, CAMPO_DA_CONTA_DAS_ISSUES)\n'
            '\n'
            '\n'
            'def _conta_do_remoto(configuracao):\n'
            '    dado = configuracao or {}\n'
            '    return (_campo(dado, CAMPO_DA_CONTA_DO_REMOTO)\n'
            '            or _campo(dado, CAMPO_DA_CONTA_DAS_ISSUES))\n'
            '\n'
            '\n'
            'def _quantas_configuracoes_de_git(ambiente: dict) -> int:\n'
            '    try:\n'
            '        return max(int(ambiente.get("GIT_CONFIG_COUNT", "0")), 0)\n'
            '    except ValueError:\n'
            '        return 0\n'
            '\n'
            '\n'
            'def _com_a_conta_no_git(ambiente: dict) -> None:\n'
            '    quantas = _quantas_configuracoes_de_git(ambiente)\n'
            '    for valor in ("", AJUDANTE_QUE_LE_O_TOKEN):\n'
            '        ambiente[f"GIT_CONFIG_KEY_{quantas}"] = CHAVE_DO_AJUDANTE_DE_CREDENCIAL\n'
            '        ambiente[f"GIT_CONFIG_VALUE_{quantas}"] = valor\n'
            '        quantas += 1\n'
            '    ambiente["GIT_CONFIG_COUNT"] = str(quantas)\n'
            '\n'
            '\n'
            'def _ambiente_da_conta(conta, base=None):\n'
            '    ambiente = dict(os.environ if base is None else base)\n'
            '    token = _token_da_conta(conta)\n'
            '    if token:\n'
            '        ambiente["GH_TOKEN"] = token\n'
            '        _com_a_conta_no_git(ambiente)\n'
            '    return ambiente\n'
            '\n'
            '\n'
            'def sem_caminho_de_maquina(texto, *raizes):\n'
            '    if not texto:\n'
            '        return texto\n'
            '    conhecidas = []\n'
            '    for raiz in raizes:\n'
            '        if raiz:\n'
            '            conhecidas.append(str(Path(raiz).resolve()))\n'
            '    try:\n'
            '        pasta_pessoal = str(Path.home())\n'
            '    except RuntimeError:\n'
            '        pasta_pessoal = ""\n'
            '    for raiz in sorted(conhecidas, key=len, reverse=True):\n'
            '        for sep in ("/", os.sep):\n'
            '            texto = texto.replace(raiz + sep, "")\n'
            '        texto = texto.replace(raiz, ".")\n'
            '    if pasta_pessoal:\n'
            '        for sep in ("/", os.sep):\n'
            '            texto = texto.replace(pasta_pessoal + sep, "~" + sep)\n'
            '    return texto\n'
            '\n'
            '\n'
            'def _gh_da_conta(conta, argumentos, tempo=TEMPO_DO_GH):\n'
            '    try:\n'
            '        return subprocess.run(GH + argumentos, capture_output=True, text=True,\n'
            '                              timeout=tempo, env=_ambiente_da_conta(conta))\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return None\n'
            '\n'
            '\n'
            'def _gh_na_conta_das_issues(configuracao, argumentos, tempo=TEMPO_DO_GH):\n'
            '    return _gh_da_conta(_conta_das_issues(configuracao), argumentos, tempo)\n'
            '\n'
            '\n'
            'def _repositorio_do_remoto(cwd):\n'
            '    try:\n'
            '        achado = subprocess.run(\n'
            '            ["git", "-C", str(cwd), "remote", "get-url", REMOTO_GIT_PADRAO],\n'
            '            capture_output=True, text=True, timeout=TEMPO_DO_GIT)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return None\n'
            '    if achado.returncode != 0:\n'
            '        return None\n'
            '    casou = REPOSITORIO_NO_ENDERECO_DO_REMOTO.search(achado.stdout.strip())\n'
            '    return casou.group(1) if casou else None\n'
            '\n'
            '\n'
            'def _a_conta_le_o_repositorio(conta, repositorio):\n'
            '    if not _token_da_conta(conta):\n'
            '        return False, RESPOSTA_SEM_TOKEN.format(conta)\n'
            '    feito = _gh_da_conta(conta, ["api", SONDA_DO_REPOSITORIO.format(\n'
            '        repositorio)], TEMPO_DO_GH)\n'
            '    if feito is None:\n'
            '        return None, RECADO_GH_MUDO\n'
            '    if feito.returncode == 0:\n'
            '        return True, ""\n'
            '    berro = (feito.stderr or feito.stdout).strip()\n'
            '    return False, _uma_linha(berro)[:LIMITE_DO_ERRO_DO_GH]\n'
            '\n'
            '\n'
            'def _contas_que_vao_falar(configuracao, roteiro, cwd) -> list:\n'
            '    pares = []\n'
            '    repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '    conta = _conta_das_issues(configuracao)\n'
            '    if issue_do_roteiro_ou_do_ambiente(roteiro) and conta and repositorio:\n'
            '        pares.append((PAPEL_DAS_ISSUES, conta, repositorio))\n'
            '    repositorio = _repositorio_do_remoto(cwd)\n'
            '    conta = _conta_do_remoto(configuracao)\n'
            '    if conta and repositorio:\n'
            '        pares.append((PAPEL_DO_REMOTO, conta, repositorio))\n'
            '    return pares\n'
            '\n'
            '\n'
            'def problemas_de_acesso(configuracao, roteiro, cwd) -> tuple:\n'
            '    recusas, nao_medidos = [], []\n'
            '    for papel, conta, repositorio in _contas_que_vao_falar(configuracao,\n'
            '                                                           roteiro, cwd):\n'
            '        leu, resposta = _a_conta_le_o_repositorio(conta, repositorio)\n'
            '        if leu:\n'
            '            continue\n'
            '        molde = (ERRO_CONTA_SEM_ACESSO if leu is False\n'
            '                 else AVISO_ACESSO_NAO_MEDIDO)\n'
            '        (recusas if leu is False else nao_medidos).append(molde.format(\n'
            '            papel=papel, conta=conta, repositorio=repositorio,\n'
            '            resposta=resposta))\n'
            '    return recusas, nao_medidos\n'
            '\n'
            '\n'
            'def _por_ou_tirar_etiqueta(configuracao, issue, etiqueta, por, cor,\n'
            '                           descricao):\n'
            '    repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '    if not issue or not repositorio:\n'
            '        return False, RECADO_SEM_ISSUE_PARA_ETIQUETAR\n'
            '    if por:\n'
            '        _gh_na_conta_das_issues(\n'
            '            configuracao, ["label", "create", etiqueta,\n'
            '                           "--repo", repositorio, "--color", cor,\n'
            '                           "--description", descricao, "--force"])\n'
            '    bandeira = "--add-label" if por else "--remove-label"\n'
            '    feito = _gh_na_conta_das_issues(\n'
            '        configuracao, ["issue", "edit", str(issue), "--repo", repositorio,\n'
            '                       bandeira, etiqueta])\n'
            '    if feito is None or feito.returncode != 0:\n'
            '        berro = ((feito.stderr or feito.stdout).strip()[:LIMITE_DO_ERRO_DO_GH]\n'
            '                 if feito else RECADO_GH_MUDO)\n'
            '        return False, RECADO_ETIQUETA_FALHOU.format(\n'
            '            etiqueta=etiqueta, motivo=berro)\n'
            '    return True, (RECADO_ETIQUETA_POSTA if por else RECADO_ETIQUETA_TIRADA\n'
            '                  ).format(etiqueta=etiqueta)\n'
            '\n'
            '\n'
            'def marcar_que_parou_em_voce(configuracao, issue, situacao):\n'
            '    return _por_ou_tirar_etiqueta(\n'
            '        configuracao, issue, ETIQUETA_PARADO_EM_VOCE,\n'
            '        situacao in SITUACOES_QUE_PARAM_EM_VOCE,\n'
            '        COR_DA_ETIQUETA, DESCRICAO_DA_ETIQUETA)\n'
            '\n'
            '\n'
            'def marcar_parado_em_terceiros(configuracao, issue, por):\n'
            '    return _por_ou_tirar_etiqueta(\n'
            '        configuracao, issue, ETIQUETA_PARADO_EM_TERCEIROS, por,\n'
            '        COR_DA_ETIQUETA_DE_TERCEIROS, DESCRICAO_DA_ETIQUETA_DE_TERCEIROS)\n'
            '\n'
            '\n'
            'def tirar_parado_em_terceiros(configuracao, issue):\n'
            '    repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '    if not issue or not repositorio:\n'
            '        return False, ""\n'
            '    feito = _gh_na_conta_das_issues(\n'
            '        configuracao, ["issue", "edit", str(issue), "--repo", repositorio,\n'
            '                       "--remove-label", ETIQUETA_PARADO_EM_TERCEIROS])\n'
            '    if feito is not None and feito.returncode == 0:\n'
            '        return True, RECADO_ETIQUETA_TIRADA.format(\n'
            '            etiqueta=ETIQUETA_PARADO_EM_TERCEIROS)\n'
            '    berro = ((feito.stderr or feito.stdout).strip() if feito\n'
            '             else RECADO_GH_MUDO)\n'
            '    if MARCA_DE_ETIQUETA_INEXISTENTE in berro:\n'
            '        return True, ""\n'
