            '\n'
            '\n'
            'def _ler_evidencias(pasta: Path):\n'
            '    avisos, atuais = [], {}\n'
            '    paras, teto = 0, None\n'
            '    if not pasta.is_dir():\n'
            '        avisos.append(AVISO_DIRETORIO_INEXISTENTE.format(pasta))\n'
            '    for arquivo in sorted(pasta.glob("*.json")) if pasta.is_dir() else []:\n'
            '        try:\n'
            '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
            '            if not isinstance(dado, dict):\n'
            '                raise ValueError(ERRO_NAO_E_OBJETO_DE_EVIDENCIA)\n'
            '        except (OSError, ValueError):\n'
            '            avisos.append(\n'
            '                AVISO_EVIDENCIA_ILEGIVEL_NO_ANDAMENTO.format(arquivo.name))\n'
            '            paras += 1\n'
            '            continue\n'
            '        if dado.get("veredito") == "para":\n'
            '            paras += 1\n'
            '        ciclo = dado.get("ciclo", {})\n'
            '        if isinstance(ciclo, dict) and _inteiro_sao(ciclo.get("teto", 0)):\n'
            '            teto = ciclo["teto"]\n'
            '        pedacos = PADRAO_NOME_EVIDENCIA.match(arquivo.name)\n'
            '        if not pedacos:\n'
            '            avisos.append(AVISO_FORA_DO_PADRAO.format(arquivo.name))\n'
            '            continue\n'
            '        chave = (int(pedacos.group(1)), pedacos.group(2))\n'
            '        vez = int(pedacos.group(3))\n'
            '        if chave not in atuais or vez > atuais[chave][0]:\n'
            '            atuais[chave] = (vez, dado)\n'
            '    return atuais, paras, teto, avisos\n'
            '\n'
            '\n'
            'def _etapas_do_andamento(atuais: dict) -> list:\n'
            '    etapas = []\n'
            '    for ordem, nome in sorted(atuais):\n'
            '        _, dado = atuais[(ordem, nome)]\n'
            '        etapas.append({"ordem": ordem, "nome": nome,\n'
            '                       "veredito": dado.get("veredito"),\n'
            '                       "ciclo": dado.get("ciclo"),\n'
            '                       "faltas": dado.get("faltas", []),\n'
            '                       "proximo": dado.get("proximo"),\n'
            '                       "pergunta": dado.get("pergunta")})\n'
            '    return etapas\n'
            '\n'
            '\n'
            'def _git(cwd, *ordem, tempo=TEMPO_DO_GIT_LOCAL):\n'
            '    try:\n'
            '        return subprocess.run(["git", "-C", str(cwd), *ordem],\n'
            '                              capture_output=True, text=True, timeout=tempo)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return None\n'
            '\n'
            '\n'
            'def _berro_do_git(feito) -> str:\n'
            '    if feito is None:\n'
            '        return GIT_MUDO\n'
            '    return _uma_linha(feito.stderr or feito.stdout)[:LIMITE_DO_ERRO_DO_GH]\n'
            '\n'
            '\n'
            'def _branch_da_evidencia(atuais: dict) -> str:\n'
            '    for (_, nome), (_, dado) in atuais.items():\n'
            '        if nome != ETAPA_QUE_ABRE_A_BRANCH:\n'
            '            continue\n'
            '        for prova in dado.get("provado") or []:\n'
            '            if isinstance(prova, dict) \\\n'
            '                    and prova.get("comando") == COMANDO_DA_BRANCH_ATUAL:\n'
            '                return str(prova.get("saida", "")).strip()\n'
            '    return ""\n'
            '\n'
            '\n'
            'def _branch_do_ambiente(pasta: Path, padrao) -> str:\n'
            '    if not padrao:\n'
            '        return ""\n'
            '    try:\n'
            '        dado = json.loads(\n'
            '            (pasta / ARQUIVO_DO_AMBIENTE).read_text(encoding="utf-8"))\n'
            '    except (OSError, ValueError):\n'
            '        return ""\n'
            '    variaveis = dado.get("variaveis") if isinstance(dado, dict) else None\n'
            '    if not isinstance(variaveis, dict):\n'
            '        return ""\n'
            '    nome = padrao.replace(\n'
            '        MARCA_DO_NUMERO_NO_PADRAO,\n'
            '        str(variaveis.get(VARIAVEL_DA_ISSUE, "")).strip()).replace(\n'
            '        MARCA_DO_ASSUNTO_NO_PADRAO,\n'
            '        str(variaveis.get(VARIAVEL_DO_ASSUNTO, "")).strip())\n'
            '    return "" if MARCA_LIVRE_NO_PADRAO.search(nome) else nome\n'
            '\n'
            '\n'
            'def _nao_medido(falta, provado=()) -> dict:\n'
            '    return {"chegou": False, "provado": list(provado), "faltas": [falta]}\n'
            '\n'
            '\n'
            'def destino_do_trabalho(cwd, branch, integracao) -> dict:\n'
            '    if not Path(cwd).is_dir():\n'
            '        return _nao_medido(FALTA_CWD_INUTILIZAVEL.format(cwd))\n'
            '    if not branch:\n'
            '        return _nao_medido(FALTA_SEM_BRANCH)\n'
            '    no_remoto = _git(cwd, "ls-remote", "--heads", REMOTO_GIT_PADRAO, branch,\n'
            '                     tempo=TEMPO_DO_GIT)\n'
            '    if no_remoto is None or no_remoto.returncode != 0:\n'
            '        return _nao_medido(FALTA_REMOTO_MUDO.format(\n'
            '            branch=branch, erro=_berro_do_git(no_remoto)))\n'
            '    if no_remoto.stdout.strip():\n'
            '        return {"chegou": True, "faltas": [], "provado": [\n'
            '            {"afirmacao": DESTINO_NO_REMOTO.format(branch=branch),\n'
            '             "comando": COMANDO_DA_BRANCH_NO_REMOTO.format(branch=branch),\n'
            '             "saida": no_remoto.stdout.strip()}]}\n'
            '    fora = {"afirmacao": BRANCH_FORA_DO_REMOTO.format(branch=branch),\n'
            '            "comando": COMANDO_DA_BRANCH_CONTADA.format(branch=branch),\n'
            '            "saida": "0"}\n'
            '    if not integracao:\n'
            '        return _nao_medido(FALTA_SEM_INTEGRACAO.format(\n'
            '            arquivo=ARQUIVO_EXECUTOR, cwd=cwd, branch=branch), [fora])\n'
            '    commit = _git(cwd, "rev-parse", "--verify", f"{branch}^{{commit}}")\n'
            '    if commit is None or commit.returncode != 0 or not commit.stdout.strip():\n'
            '        return _nao_medido(FALTA_SEM_O_COMMIT.format(\n'
            '            branch=branch, integracao=integracao), [fora])\n'
            '    sha = commit.stdout.strip()\n'
            '    contido = _git(cwd, "merge-base", "--is-ancestor", sha,\n'
            '                   f"{REMOTO_GIT_PADRAO}/{integracao}")\n'
            '    if contido is None or contido.returncode not in (0, 1):\n'
            '        return _nao_medido(FALTA_INTEGRACAO_MUDA.format(\n'
            '            sha=sha, integracao=integracao, erro=_berro_do_git(contido)),\n'
            '            [fora])\n'
            '    chegou = contido.returncode == 0\n'
            '    molde = DESTINO_NA_INTEGRACAO if chegou else COMMIT_FORA_DA_INTEGRACAO\n'
            '    return {"chegou": chegou,\n'
            '            "faltas": [] if chegou else [FALTA_SEM_DESTINO.format(\n'
            '                branch=branch, integracao=integracao)],\n'
            '            "provado": [fora, {\n'
            '                "afirmacao": molde.format(branch=branch, sha=sha,\n'
            '                                          integracao=integracao),\n'
            '                "comando": COMANDO_DO_COMMIT_NA_INTEGRACAO.format(\n'
            '                    sha=sha, integracao=integracao),\n'
            '                "saida": (CONTIDO_NA_INTEGRACAO if chegou\n'
            '                          else FORA_DA_INTEGRACAO)}]}\n'
            '\n'
            '\n'
            'def _estado_e_acao(etapas, sem_evidencia, paras, teto, trabalho, dir_base,\n'
            '                   pasta):\n'
            '    parado = next((e for e in etapas if e["veredito"] == "para"), None)\n'
            '    aguarda = next((e for e in etapas if e["veredito"] == "pergunta"), None)\n'
            '    if not etapas:\n'
            '        return "em-curso", ACAO_NADA_RODOU.format(trabalho=trabalho,\n'
            '                                                  dir_base=dir_base)\n'
            '    if teto is not None and paras >= teto:\n'
            '        return "parada", ACAO_TETO_ESGOTADO.format(teto=teto, pasta=pasta)\n'
            '    if parado:\n'
            '        return "parada", parado["proximo"] or ACAO_LEIA_A_EVIDENCIA.format(\n'
            '            etapa=parado["nome"], pasta=pasta)\n'
            '    if aguarda:\n'
            '        return "aguardando-aprovacao", aguarda["pergunta"] \\\n'
            '            or ACAO_LEIA_A_EVIDENCIA.format(etapa=aguarda["nome"],\n'
