            '    if sem_evidencia:\n'
            '        return "em-curso", ACAO_ETAPA_SEM_EVIDENCIA.format(\n'
            '            nomes=", ".join(sem_evidencia))\n'
            '    return "completa", ACAO_NADA_A_FAZER.format(pasta)\n'
            '\n'
            '\n'
            'def _com_o_estado_gravado(estado, acao, gravado):\n'
            '    if gravado and gravado.get("situacao") == "dormindo":\n'
            '        return "dormindo", ACAO_DORMINDO.format(\n'
            '            ate=gravado.get("ate", "?"),\n'
            '            porque=gravado.get("porque", "espera"),\n'
            '            etapa=gravado.get("etapa", "?"))\n'
            '    if gravado and gravado.get("situacao") == "aguardando-resposta" \\\n'
            '            and gravado.get("issue"):\n'
            '        return estado, ACAO_AGUARDANDO_RESPOSTA.format(\n'
            '            acao=acao, issue=gravado["issue"],\n'
            '            desde=gravado.get("desde", "?"))\n'
            '    if gravado and gravado.get("situacao") == "rodando" \\\n'
            '            and estado == "completa":\n'
            '        return "em-curso", ACAO_EXECUCAO_VIVA\n'
            '    return estado, acao\n'
            '\n'
            '\n'
            'def _com_o_destino_medido(estado, acao, cwd, atuais, pasta):\n'
            '    if estado != "completa":\n'
            '        return estado, acao, None\n'
            '    configuracao, _ = carregar_executor(cwd)\n'
            '    branch = (_branch_da_evidencia(atuais)\n'
            '              or _branch_do_ambiente(pasta, _campo(\n'
            '                  configuracao or {}, "branches.padrao_de_trabalho")))\n'
            '    destino = destino_do_trabalho(\n'
