            '      "tipo": "codigo",\n'
            '      "comando": "python3 - <<\'PY\'\\nimport json\\nimport os\\nimport subprocess\\nfrom pathlib import Path\\n\\ndef evidencia(veredito, provado, faltas=(), proximo=None, suposto=()):\\n    dado = {\'etapa\': \'x\', \'trabalho\': \'x\', \'quando\': \'2000-01-01T00:00:00Z\',\\n            \'veredito\': veredito, \'provado\': list(provado),\\n            \'suposto\': list(suposto), \'faltas\': list(faltas),\\n            \'ciclo\': {\'i\': 1, \'teto\': 1}}\\n    if proximo:\\n        dado[\'proximo\'] = proximo\\n    print(json.dumps(dado, ensure_ascii=False))\\n    raise SystemExit(0)\\n\\ndeclarado = os.environ.get(\'PROJETO\', \'\').strip()\\nif not declarado:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'nao veio alvo nenhum no ambiente\',\\n          \'comando\': \\"printenv PROJETO | tr -d \'[:space:]\' | wc -c\\",\\n          \'saida\': \'0\'}],\\n        [\'PROJETO nao foi declarada, e sem alvo declarado o roteiro nao sabe \'\\n         \'em que repositorio mexer — adivinhar alvo e escrever no lugar \'\\n         \'errado\'],\\n        \'Exporte PROJETO com o caminho do repositorio alvo \'\\n        \'(PROJETO=projetos/<nome>) e reexecute.\')\\n\\nalvo = Path(declarado).expanduser()\\nif not (alvo / \'.git\').exists():\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o alvo declarado nao tem .git\',\\n          \'comando\': \'ls -d \\"$PROJETO/.git\\" 2>/dev/null | wc -l\',\\n          \'saida\': \'0\'}],\\n        [\'o caminho em PROJETO nao e a raiz de um repositorio git, e este \'\\n         \'roteiro so sabe trabalhar dentro de um\'],\\n        \'Aponte PROJETO para a pasta que tem o .git dentro e reexecute.\')\\n\\nconfiguracao = json.loads(\\n    Path(\'nucleo/executor.json\').read_text(encoding=\'utf-8\'))\\nso_leitura = {(p.get(\'repositorio\') or \'\').strip().lower()\\n              for p in (configuracao.get(\'projetos\') or {}).values()\\n              if isinstance(p, dict) and p.get(\'somente_leitura\')}\\nso_leitura.discard(\'\')\\n\\nnome_do_alvo = Path(os.path.realpath(alvo)).name.strip().lower()\\nif nome_do_alvo in so_leitura:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o alvo esta na lista de somente leitura que nucleo/executor.json declara\',\\n          \'comando\': \'python3 -c \\"import json, os; cfg = json.load(open(\\\\\'nucleo/executor.json\\\\\')); so = [(p.get(\\\\\'repositorio\\\\\') or \\\\\'\\\\\').lower() for p in (cfg.get(\\\\\'projetos\\\\\') or {}).values() if isinstance(p, dict) and p.get(\\\\\'somente_leitura\\\\\')]; print(os.path.basename(os.path.realpath(os.environ[\\\\\'PROJETO\\\\\'])).lower() in so)\\"\',\\n          \'saida\': \'True\'}],\\n        [nome_do_alvo + \' e somente leitura, sempre: dele se le, nele nao se \'\\n         \'escreve. Este roteiro recusa antes de comecar; o gancho recusa a \'\\n         \'escrita por qualquer caminho\'],\\n        \'Aponte PROJETO para um repositorio onde escrever e permitido e \'\\n        \'reexecute.\')\\n\\nbase = configuracao[\'branches\'][\'base\']\\nbranch = (configuracao[\'branches\'][\'padrao_de_trabalho\']\\n          .replace(\'<numero>\', os.environ.get(\'ISSUE\', \'0\'))\\n          .replace(\'<assunto-em-kebab>\', os.environ.get(\'ASSUNTO\',\\n                                                        \'trabalho\')))\\n\\ndef git(*argumentos):\\n    return subprocess.run([\'git\', \'-C\', str(alvo), *argumentos],\\n                          capture_output=True, text=True)\\n\\nbusca = git(\'fetch\', \'origin\', base)\\nif busca.returncode != 0:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o remoto do alvo nao respondeu pela base\',\\n          \'comando\': \'git -C \\"$PROJETO\\" fetch origin \' + base + \' 2>&1 \'\\n                     \'|| true\',\\n          \'saida\': (busca.stderr.strip() or busca.stdout.strip())[:300]}],\\n        [\'nao consegui buscar a base \' + base + \' no remoto do alvo\'],\\n        \'Confira o remoto do alvo e o acesso da conta declarada em \'\\n        \'remoto.conta_gh, e reexecute.\')\\n\\ncriacao = git(\'checkout\', \'-b\', branch, \'origin/\' + base)\\natual = git(\'branch\', \'--show-current\').stdout.strip()\\nif atual != branch:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'a branch de trabalho nao nasceu no alvo\',\\n          \'comando\': \'git -C \\"$PROJETO\\" branch --show-current\',\\n          \'saida\': atual}],\\n        [\'nao consegui criar \' + branch + \' no alvo: \'\\n         + criacao.stderr.strip()[:200]],\\n        \'Confira se a branch ja existe no alvo e se a arvore dele esta \'\\n        \'limpa, e reexecute.\')\\n\\nevidencia(\\n    \'segue\',\\n    [{\'afirmacao\': \'a branch de trabalho nasceu no alvo, a partir de \' + base,\\n      \'comando\': \'git -C \\"$PROJETO\\" branch --show-current\',\\n      \'saida\': atual},\\n     {\'afirmacao\': \'e aponta para o mesmo commit da base\',\\n      \'comando\': \'git -C \\"$PROJETO\\" rev-parse HEAD origin/\' + base,\\n      \'saida\': git(\'rev-parse\', \'HEAD\', \'origin/\' + base).stdout.strip()}])\\nPY",\n'
