            '      "comando": "python3 - <<\'PY\'\\nimport json\\nimport os\\nimport subprocess\\nfrom pathlib import Path\\n\\nLEITURA_DO_CADASTRO = (\\n    \'import json, os; \'\\n    \'projetos = json.load(open(\\"nucleo/executor.json\\"))\'\\n    \'.get(\\"projetos\\") or {}; \'\\n    \'alvo = os.path.basename(os.path.realpath(os.environ[\\"PROJETO\\"]))\'\\n    \'.strip().lower(); \'\\n    \'cadastro = [p for p in projetos.values() if isinstance(p, dict) and \'\\n    \'(p.get(\\"repositorio\\") or \\"\\").strip().lower() == alvo]; \'\\n)\\n\\nLEITURA_DA_CONFIGURACAO_DO_ALVO = (\\n    \\"python3 -c \'import json, os; \\"\\n    \'onde = os.path.join(os.environ[\\"PROJETO\\"], \\"nucleo/configuracao.json\\"); \'\\n    \'dado = json.load(open(onde)) if os.path.exists(onde) else {}; \'\\n    \\"print(int((dado.get(\\\\\\"autorizacoes\\\\\\") or {}).get(\\\\\\"push\\\\\\") is True))\'\\"\\n)\\n\\n\\ndef consulta(expressao):\\n    return \\"python3 -c \'\\" + LEITURA_DO_CADASTRO + \\"print(\\" + expressao + \\")\'\\"\\n\\n\\ndef evidencia(veredito, provado, faltas=(), proximo=None, suposto=()):\\n    dado = {\'etapa\': \'x\', \'trabalho\': \'x\', \'quando\': \'2000-01-01T00:00:00Z\',\\n            \'veredito\': veredito, \'provado\': list(provado),\\n            \'suposto\': list(suposto), \'faltas\': list(faltas),\\n            \'ciclo\': {\'i\': 1, \'teto\': 1}}\\n    if proximo:\\n        dado[\'proximo\'] = proximo\\n    print(json.dumps(dado, ensure_ascii=False))\\n    raise SystemExit(0)\\n\\n\\ndeclarado = os.environ.get(\'PROJETO\', \'\').strip()\\nif not declarado:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'nao veio alvo nenhum no ambiente\',\\n          \'comando\': \\"printenv PROJETO | tr -d \'[:space:]\' | wc -c\\",\\n          \'saida\': \'0\'}],\\n        [\'PROJETO sumiu entre as etapas, e sem alvo nao ha para onde \'\\n         \'empurrar: o trabalho nao chegou ao repositorio duravel\'],\\n        \'Exporte PROJETO com o caminho do repositorio alvo e reexecute a \'\\n        \'execucao inteira.\')\\n\\nalvo = str(Path(declarado).expanduser())\\nprojetos = (json.loads(Path(\'nucleo/executor.json\')\\n                       .read_text(encoding=\'utf-8\')).get(\'projetos\') or {})\\nnome_do_alvo = Path(os.path.realpath(alvo)).name.strip().lower()\\netiqueta, cadastro = next(\\n    ((nome, projeto) for nome, projeto in projetos.items()\\n     if isinstance(projeto, dict)\\n     and (projeto.get(\'repositorio\') or \'\').strip().lower() == nome_do_alvo),\\n    (\'\', None))\\n\\nif cadastro is None:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'nenhuma etiqueta declara o alvo \' + nome_do_alvo,\\n          \'comando\': consulta(\'len(cadastro)\'),\\n          \'saida\': \'0\'},\\n         {\'afirmacao\': \'e o mesmo instrumento acha os projetos declarados\',\\n          \'comando\': consulta(\'sum(1 for p in projetos.values() \'\\n                              \'if isinstance(p, dict))\'),\\n          \'saida\': str(sum(1 for p in projetos.values()\\n                           if isinstance(p, dict)))}],\\n        [\'o alvo \' + nome_do_alvo + \' nao tem etiqueta declarada em \'\\n         \'nucleo/executor.json: falta projetos.<etiqueta>.repositorio com \'\\n         \'esse nome, e sem cadastro nao da para saber se empurrar nele e \'\\n         \'permitido\'],\\n        \'Declare projetos.<etiqueta> em nucleo/executor.json com \'\\n        \'repositorio: \' + nome_do_alvo + \', e com somente_leitura dizendo \'\\n        \'se dele so se le, e reexecute.\')\\n\\nif cadastro.get(\'somente_leitura\'):\\n    revisor = (cadastro.get(\'revisor\') or \'\').strip()\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o cadastro do alvo declara somente_leitura\',\\n          \'comando\': consulta(\'sum(1 for c in cadastro \'\\n                              \'if c.get(\\"somente_leitura\\"))\'),\\n          \'saida\': \'1\'}],\\n        [\'o trabalho nao chegou ao repositorio duravel e nao chega por \'\\n         \'aqui: \' + etiqueta + \' e somente leitura, e nele nao se empurra \'\\n         \'— o commit continua so na arvore do alvo\'],\\n        (\'Leve o trabalho por pedido de incorporacao como SUGESTAO, com \'\\n         + revisor + \' como revisor: e o caminho que projetos.\' + etiqueta\\n         + \'.revisor declara.\') if revisor else\\n        (\'Peca ao dono o caminho: \' + etiqueta + \' e somente leitura e \'\\n         \'projetos.\' + etiqueta + \'.revisor nao esta declarado, entao nao \'\\n         \'ha a quem sugerir o pedido de incorporacao.\'))\\n\\ndo_cadastro = (cadastro.get(\'autorizacoes\') or {}).get(\'push\')\\ntry:\\n    do_alvo = (json.loads((Path(alvo) / \'nucleo\' / \'configuracao.json\')\\n                          .read_text(encoding=\'utf-8\'))\\n               .get(\'autorizacoes\') or {}).get(\'push\')\\nexcept (OSError, ValueError):\\n    do_alvo = None\\n\\nif not (do_cadastro if isinstance(do_cadastro, bool) else do_alvo is True):\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o cadastro do alvo nao liga autorizacoes.push\',\\n          \'comando\': consulta(\'sum(1 for c in cadastro if \'\\n                              \'(c.get(\\"autorizacoes\\") or {}).get(\\"push\\") \'\\n                              \'is True)\'),\\n          \'saida\': str(int(do_cadastro is True))},\\n         {\'afirmacao\': \'e o alvo tambem nao liga autorizacoes.push na \'\\n                       \'configuracao dele\',\\n          \'comando\': LEITURA_DA_CONFIGURACAO_DO_ALVO,\\n          \'saida\': str(int(do_alvo is True))},\\n         {\'afirmacao\': \'o mesmo instrumento acha o cadastro do alvo\',\\n          \'comando\': consulta(\'len(cadastro)\'),\\n          \'saida\': \'1\'}],\\n        [\'o trabalho nao chegou ao repositorio duravel: empurrar em \'\\n         + etiqueta + \' nao esta autorizado, e omissao nao e permissao\'],\\n        \'Ligue projetos.\' + etiqueta + \'.autorizacoes.push em \'\\n        \'nucleo/executor.json, ou peca ao dono que empurre a branch de \'\\n        \'trabalho do alvo, e reexecute.\')\\n\\n\\ndef git(*argumentos):\\n    return subprocess.run([\'git\', \'-C\', alvo, *argumentos],\\n                          capture_output=True, text=True)\\n\\n\\nbranch = git(\'branch\', \'--show-current\').stdout.strip()\\nif not branch:\\n    evidencia(\\n        \'para\',\\n        [{\'afirmacao\': \'o alvo nao esta na branch de trabalho\',\\n          \'comando\': \'git -C \\"$PROJETO\\" branch --show-current\',\\n          \'saida\': \'\'}],\\n        [\'sem branch de trabalho no alvo nao ha o que empurrar, e o \'\\n         \'trabalho nao chega ao repositorio duravel\'],\\n        \'Volte o alvo para a branch de trabalho da issue e reexecute.\')\\n\\nlocal = git(\'rev-parse\', \'HEAD\').stdout.strip()\\nenvio = git(\'push\', \'origin\', \'HEAD:refs/heads/\' + branch)\\nmedicao = git(\'ls-remote\', \'--heads\', \'origin\', branch)\\nremoto = medicao.stdout.strip()\\nsha = remoto.split()[0] if remoto else \'\'\\nchegou = bool(sha) and sha == local\\n\\nif medicao.returncode:\\n    faltas = [\'nao medido: o remoto do alvo nao respondeu ao ls-remote, e \'\\n              \'sem medicao nao se diz que o trabalho chegou ao \'\\n              \'repositorio duravel — \'\\n              + (medicao.stderr.strip() or medicao.stdout.strip())[:200]]\\nelif chegou:\\n    faltas = []\\nelse:\\n    faltas = [\'a branch de trabalho nao chegou ao repositorio duravel: o \'\\n              \'que foi commitado existe so na arvore do alvo, e some com \'\\n              \'ela\']\\n    if envio.returncode:\\n        faltas.append((envio.stderr.strip() or envio.stdout.strip())[:300])\\n\\nevidencia(\\n    \'segue\' if chegou else \'para\',\\n    [{\'afirmacao\': \'o commit da branch de trabalho no alvo\',\\n      \'comando\': \'git -C \\"$PROJETO\\" rev-parse HEAD\',\\n      \'saida\': local},\\n     {\'afirmacao\': \'a branch de trabalho existe no repositorio duravel do \'\\n                   \'alvo, no mesmo commit\',\\n      \'comando\': \'git -C \\"$PROJETO\\" ls-remote --heads origin \' + branch,\\n      \'saida\': remoto}],\\n    faltas,\\n    None if chegou else\\n    \'Empurre a branch de trabalho do alvo para o repositorio duravel e \'\\n    \'reexecute: trabalho que so existe na arvore do alvo some com ela.\')\\nPY"\n'
            '    },\n'
            '    {\n'
            '      "nome": "verificacao",\n'
            '      "tipo": "verificacao",\n'
            '      "depende": [\n'
            '        "trabalho-empurrado"\n'
            '      ]\n'
