            'def quem_responde_na_porta(porta: int) -> tuple:\n'
            '    try:\n'
            '        with urllib.request.urlopen(\n'
            '                f"http://{ENDERECO_LOCAL}:{porta}/trabalhos",\n'
            '                timeout=TIMEOUT_DA_PERGUNTA_A_PORTA_S) as resposta:\n'
            '            dado = json.loads(resposta.read())\n'
            '            return dado.get("repositorio"), dado.get("alvo")\n'
            '    except (OSError, ValueError, json.JSONDecodeError):\n'
            '        return None, None\n'
            '\n'
            '\n'
            'def descendentes_lendo_proc(pai: int) -> list:\n'
            '    filhos_por_pai = {}\n'
            '    try:\n'
            '        for entrada in os.listdir("/proc"):\n'
            '            if not entrada.isdigit():\n'
            '                continue\n'
            '            try:\n'
            '                with open(f"/proc/{entrada}/stat", encoding="utf-8") as arquivo:\n'
            '                    campos = arquivo.read().rsplit(")", 1)[1].split()\n'
            '                filhos_por_pai.setdefault(int(campos[1]), []).append(int(entrada))\n'
            '            except (OSError, IndexError, ValueError):\n'
            '                continue\n'
