            '                           "inicio": anterior, "fim": quando,\n'
            '                           "ciclo": (dado.get("ciclo") or {}).get("i"),\n'
            '                           "log": log.name if log.exists() else None})\n'
            '            anterior = quando\n'
            '        marcas = []\n'
            '        gravado = estado_que_o_motor_gravou(dir_evidencias, pasta.name) or {}\n'
            '        desde = str(gravado.get("desde") or "")\n'
            '        if gravado.get("situacao") in ("aguardando-resposta", "parada") \\\n'
            '                and desde.startswith(hoje):\n'
            '            marcas.append({"tipo": gravado["situacao"], "quando": desde})\n'
            '        if blocos or marcas:\n'
            '            raias.append({"trabalho": pasta.name, "blocos": blocos,\n'
            '                          "marcas": marcas})\n'
            '    return {"dia": hoje, "raias": raias}\n'
            '\n'
            '\n'
            'PADRAO_DA_LINHA_DA_CAIXA = re.compile(\n'
            '    r"^- \\*\\*(?P<id>[^*]+)\\*\\* `(?P<tipo>[a-z]+)` — (?P<texto>.*?)"\n'
            '    r"(?: · visto em (?P<visto>\\S+))?$")\n'
            '\n'
            '\n'
            'def linhas_do_corpo_da_caixa(corpo: str) -> list:\n'
            '    achadas = []\n'
            '    for linha in (corpo or "").splitlines():\n'
            '        casada = PADRAO_DA_LINHA_DA_CAIXA.match(linha.strip())\n'
            '        if casada:\n'
            '            achadas.append({"id": casada["id"], "tipo": casada["tipo"],\n'
            '                            "texto": casada["texto"],\n'
            '                            "visto": casada["visto"]})\n'
            '    return achadas\n'
            '\n'
            '\n'
            'def parece_roteiro(dado) -> bool:\n'
            '    return isinstance(dado, dict) and isinstance(dado.get("etapas"), list)\n'
            '\n'
            '\n'
            'CHAVE_DA_AUDITORIA = "auditoria"\n'
            '\n'
            '\n'
            'def lembrar_a_auditoria(cwd: Path, ligada: bool) -> None:\n'
            '    alvo = Path(cwd) / ARQUIVO_EXECUTOR\n'
            '    try:\n'
            '        dado = json.loads(alvo.read_text(encoding="utf-8"))\n'
            '    except (OSError, ValueError):\n'
            '        return\n'
            '    if not isinstance(dado, dict) or dado.get(CHAVE_DA_AUDITORIA) == ligada:\n'
            '        return\n'
            '    dado[CHAVE_DA_AUDITORIA] = ligada\n'
            '    try:\n'
            '        alvo.write_text(json.dumps(dado, ensure_ascii=False, indent=2) + "\\n",\n'
            '                        encoding="utf-8")\n'
            '    except OSError:\n'
            '        return\n'
            '\n'
            '\n'
            'def roteiro_do_pedido_com_verificacao(\n'
            '        prompt: str, teto: int = TETO_PADRAO_DE_CICLOS,\n'
            '        turnos: int = TURNOS_PADRAO_ACIMA_DO_TETO_DO_MOTOR,\n'
            '        issue: int = None, auditoria: bool = False) -> dict:\n'
            '    roteiro = {\n'
            '        "teto": teto,\n'
            '        "etapas": [\n'
            '            {"nome": ETAPA_DO_PEDIDO, "tipo": "sessao", "prompt": prompt,\n'
            '             "max-turnos": turnos},\n'
            '            {"nome": ETAPA_DA_VERIFICACAO, "tipo": "verificacao",\n'
            '             "depende": [ETAPA_DO_PEDIDO]},\n'
            '        ],\n'
            '    }\n'
            '    if issue:\n'
            '        roteiro["issue"] = int(issue)\n'
            '    if auditoria:\n'
            '        roteiro[CHAVE_DA_AUDITORIA] = True\n'
            '    return roteiro\n'
            '\n'
            '\n'
            'def tem_mudanca_nao_commitada(cwd: Path) -> bool:\n'
            '    try:\n'
            '        r = subprocess.run(["git", "status", "--porcelain"], cwd=cwd,\n'
            '                           capture_output=True, text=True,\n'
            '                           timeout=TIMEOUT_DO_GIT_S)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return False\n'
            '    return r.returncode == 0 and bool(r.stdout.strip())\n'
            '\n'
            '\n'
            'def _processo_vivo(pid) -> bool:\n'
            '    try:\n'
            '        os.kill(int(pid), 0)\n'
            '    except (ProcessLookupError, ValueError, TypeError):\n'
            '        return False\n'
            '    except PermissionError:\n'
            '        return True\n'
            '    return True\n'
            '\n'
            '\n'
            'def _conta_ativa_do_gh() -> str:\n'
            '    try:\n'
            '        feito = subprocess.run(["gh", "api", "user", "--jq", ".login"],\n'
            '                               capture_output=True, text=True,\n'
            '                               timeout=TIMEOUT_DO_GH_S)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return ""\n'
            '    return feito.stdout.strip() if feito.returncode == 0 else ""\n'
            '\n'
            '\n'
            'def _pid_ainda_e_do_encadeador(pid) -> bool:\n'
            '    if not Path("/proc").exists():\n'
            '        return True\n'
            '    try:\n'
            '        linha_de_comando = Path(f"/proc/{int(pid)}/cmdline").read_bytes()\n'
            '    except (OSError, ValueError, TypeError):\n'
            '        return False\n'
            '    return ENCADEADOR.name.encode() in linha_de_comando\n'
            '\n'
            '\n'
            'class PonteParaOEncadeador:\n'
            '\n'
            '    def __init__(self, cwd: Path, dir_evidencias: Path, dirs_roteiros: list):\n'
            '        self.cwd = cwd\n'
            '        self.dir = dir_evidencias\n'
            '        self.roteiros = dirs_roteiros\n'
            '        self.rodando: dict[str, subprocess.Popen] = {}\n'
            '        self.inicio: dict[str, float] = {}\n'
            '        self.em_voo: set[str] = set()\n'
            '        self.trava = threading.Lock()\n'
            '        self._quadro, self._quadro_em = None, 0.0\n'
            '        self._maquina, self._maquina_em = None, 0.0\n'
            '        self._caixas, self._caixas_em = None, 0.0\n'
            '        self._conta, self._conta_em = None, 0.0\n'
            '        self._containers, self._containers_em = None, 0.0\n'
            '        self._criterios = {}\n'
            '\n'
            '    def maquina_com_cache(self, relendo: bool = False) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            fresco = momento - self._maquina_em\n'
            '            if self._maquina and not relendo \\\n'
            '                    and fresco < INTERVALO_DA_MAQUINA_S:\n'
            '                return self._maquina\n'
            '        achado = {"skills": skills_no_disco(RAIZ),\n'
            '                  "mcp": servidores_mcp_com_estado(),\n'
            '                  "rotinas": rotinas_do_workspace(RAIZ),\n'
            '                  "guia": guia_do_executor(self),\n'
            '                  "configuracao": configuracao_que_falta_nesta_maquina(\n'
            '                      self.cwd)}\n'
            '        with self.trava:\n'
            '            self._maquina, self._maquina_em = achado, momento\n'
            '        return achado\n'
            '\n'
            '    def containers_com_cache(self) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            fresco = momento - self._containers_em\n'
            '            if self._containers and fresco < INTERVALO_DOS_CONTAINERS_S:\n'
            '                return self._containers\n'
            '        achado = containers_do_workspace(RAIZ)\n'
            '        with self.trava:\n'
            '            self._containers, self._containers_em = achado, momento\n'
            '        return achado\n'
            '\n'
            '    def _arquivo_de_trava_deste_alvo(self) -> Path:\n'
            '        resumo_do_caminho_do_alvo = hashlib.sha256(\n'
            '            str(self.cwd).encode()).hexdigest()[:DIGITOS_DO_RESUMO_DO_ALVO]\n'
            '        return self.dir / f"{PREFIXO_DA_TRAVA}{resumo_do_caminho_do_alvo}.json"\n'
            '\n'
            '    def _trabalho_desta_sessao_ainda_no_ar(self) -> str | None:\n'
            '        with self.trava:\n'
            '            for nome, proc in self.rodando.items():\n'
            '                if proc.poll() is None:\n'
            '                    return nome\n'
            '        return None\n'
            '\n'
            '    def _dono_vivo_da_trava_em_arquivo(self) -> str | None:\n'
            '        try:\n'
            '            dono = json.loads(self._arquivo_de_trava_deste_alvo()\n'
            '                              .read_text(encoding="utf-8"))\n'
            '            os.kill(int(dono["pid"]), 0)\n'
            '        except (OSError, ValueError, KeyError, json.JSONDecodeError):\n'
            '            return None\n'
            '        return RECADO_TRAVA_DE_OUTRO_PAINEL.format(\n'
            '            dono.get("trabalho", "?"), dono["pid"])\n'
            '\n'
            '    def ocupado(self) -> str | None:\n'
            '        return (self._trabalho_desta_sessao_ainda_no_ar()\n'
            '                or self._dono_vivo_da_trava_em_arquivo())\n'
            '\n'
            '    def gravar_trava(self, pid: int, trabalho: str) -> None:\n'
            '        self._arquivo_de_trava_deste_alvo().write_text(\n'
            '            json.dumps({"pid": pid, "trabalho": trabalho,\n'
            '                        "cwd": str(self.cwd)}),\n'
            '            encoding="utf-8")\n'
            '\n'
            '    def _roteiros_por_nome_com_a_primeira_pasta_vencendo(self) -> dict:\n'
            '        achados = {}\n'
            '        for pasta in self.roteiros:\n'
            '            if not pasta.is_dir():\n'
            '                continue\n'
            '            for candidato in sorted(pasta.glob("*.json")):\n'
            '                if not candidato.is_file() or candidato.name in achados:\n'
            '                    continue\n'
            '                try:\n'
            '                    dado = json.loads(candidato.read_text(encoding="utf-8"))\n'
            '                except (OSError, json.JSONDecodeError):\n'
            '                    continue\n'
            '                if parece_roteiro(dado):\n'
            '                    achados[candidato.name] = candidato\n'
            '        return achados\n'
            '\n'
            '    def catalogo(self) -> list:\n'
            '        return sorted(self._roteiros_por_nome_com_a_primeira_pasta_vencendo())\n'
            '\n'
            '    def catalogo_com_descricao(self) -> list:\n'
            '        achados = self._roteiros_por_nome_com_a_primeira_pasta_vencendo()\n'
            '        return [{"nome": nome,\n'
            '                 "descricao": descricao_do_roteiro(achados[nome]),\n'
            '                 "titulo": titulo_do_roteiro(\n'
            '                     nome, descricao_do_roteiro(achados[nome]))}\n'
            '                for nome in sorted(achados)]\n'
            '\n'
            '    def ler_roteiro_do_catalogo(self, nome: str) -> tuple[dict | None, str | None]:\n'
            '        alvo = self._roteiros_por_nome_com_a_primeira_pasta_vencendo().get(nome)\n'
            '        if alvo is None:\n'
            '            return None, ERRO_ROTEIRO_DESCONHECIDO.format(nome)\n'
            '        try:\n'
            '            dado = json.loads(alvo.read_text(encoding="utf-8"))\n'
            '        except (OSError, json.JSONDecodeError) as e:\n'
            '            return None, ERRO_ROTEIRO_ILEGIVEL.format(e)\n'
            '        if not parece_roteiro(dado):\n'
            '            return None, ERRO_ROTEIRO_SEM_ETAPAS\n'
            '        return dado, None\n'
            '\n'
            '    def disparar(self, roteiro: dict, trabalho: str) -> dict:\n'
            '        self.dir.mkdir(parents=True, exist_ok=True)\n'
            '        alvo = self.dir / f"{trabalho}{SUFIXO_DO_ROTEIRO}"\n'
            '        alvo.write_text(json.dumps(roteiro, ensure_ascii=False, indent=2),\n'
            '                        encoding="utf-8")\n'
            '        log = (self.dir / f"{trabalho}{SUFIXO_DO_LOG}").open("w",\n'
            '                                                             encoding="utf-8")\n'
            '        proc = subprocess.Popen(\n'
            '            [sys.executable, str(ENCADEADOR), "executar",\n'
            '             "--roteiro", str(alvo), "--trabalho", trabalho,\n'
            '             "--dir", str(self.dir), "--cwd", str(self.cwd)],\n'
            '            stdout=log, stderr=subprocess.STDOUT, cwd=str(self.cwd))\n'
            '        with self.trava:\n'
            '            self.rodando[trabalho] = proc\n'
            '            self.inicio[trabalho] = time.time()\n'
            '        self.gravar_trava(proc.pid, trabalho)\n'
            '        return {"trabalho": trabalho, "roteiro": alvo.name}\n'
            '\n'
            '    def _execucoes_vivas(self) -> dict:\n'
            '        vivas = {}\n'
            '        with self.trava:\n'
            '            for trabalho, proc in self.rodando.items():\n'
            '                if proc.poll() is None:\n'
            '                    vivas[trabalho] = {"pid": proc.pid, "proc": proc}\n'
            '        if self.dir.is_dir():\n'
            '            for pasta in self.dir.iterdir():\n'
            '                if not pasta.is_dir() or pasta.name in vivas:\n'
            '                    continue\n'
            '                gravado = estado_que_o_motor_gravou(self.dir,\n'
            '                                                    pasta.name) or {}\n'
            '                pid = gravado.get("pid")\n'
            '                if (gravado.get("situacao") in SITUACOES_QUE_O_PANICO_PARA\n'
            '                        and pid and _processo_vivo(pid)\n'
            '                        and _pid_ainda_e_do_encadeador(pid)):\n'
            '                    vivas[pasta.name] = {"pid": pid, "proc": None}\n'
            '        return vivas\n'
            '\n'
            '    @staticmethod\n'
            '    def _segue_viva(alvo) -> bool:\n'
            '        proc = alvo["proc"]\n'
            '        return proc.poll() is None if proc else _processo_vivo(alvo["pid"])\n'
            '\n'
            '    def panico(self) -> dict:\n'
            '        alvos = self._execucoes_vivas()\n'
            '        for alvo in alvos.values():\n'
            '            with contextlib.suppress(ProcessLookupError, PermissionError):\n'
            '                os.kill(alvo["pid"], signal.SIGTERM)\n'
            '        prazo = time.time() + PRAZO_DO_PANICO_S\n'
            '        parados = []\n'
            '        for trabalho, alvo in sorted(alvos.items()):\n'
            '            while time.time() < prazo and self._segue_viva(alvo):\n'
            '                time.sleep(0.3)\n'
            '            derrubado = self._segue_viva(alvo)\n'
            '            if derrubado:\n'
            '                with contextlib.suppress(ProcessLookupError,\n'
            '                                         PermissionError):\n'
            '                    os.kill(alvo["pid"], signal.SIGKILL)\n'
            '            parados.append({"trabalho": trabalho, "pid": alvo["pid"],\n'
            '                            "parada": "derrubada" if derrubado else "limpa"})\n'
            '        return {"parados": parados, "prazo_s": PRAZO_DO_PANICO_S}\n'
            '\n'
            '    def mudo(self, ligado: bool) -> dict:\n'
            '        marcador = Path(self.cwd) / MARCADOR_DE_MUDO\n'
            '        if ligado:\n'
            '            marcador.parent.mkdir(exist_ok=True)\n'
            '            marcador.touch()\n'
            '        else:\n'
            '            with contextlib.suppress(FileNotFoundError):\n'
            '                marcador.unlink()\n'
            '        return {"muda": marcador.exists()}\n'
            '\n'
            '    def _roteiro_pronto_para_retomar(self, trabalho: str) -> tuple:\n'
            '        if erro := recusa_do_nome_de_trabalho(trabalho or ""):\n'
            '            return None, {"erro": erro}\n'
            '        copia = self.dir / f"{trabalho}{SUFIXO_DO_ROTEIRO}"\n'
            '        roteiro = (copia if copia.exists()\n'
            '                   else roteiro_gravado_no_estado(self.dir, trabalho))\n'
            '        if not roteiro:\n'
            '            return None, {"erro": ERRO_SEM_ROTEIRO_PARA_RETOMAR}\n'
            '        with self.trava:\n'
            '            vivo = self.rodando.get(trabalho)\n'
            '            if trabalho in self.em_voo or (vivo and vivo.poll() is None):\n'
            '                return None, {"erro": ERRO_RESPONDER_COM_EXECUCAO_VIVA}\n'
            '            self.em_voo.add(trabalho)\n'
            '        if recado := self.ocupado():\n'
            '            self._liberar_a_reserva(trabalho)\n'
            '            return None, {"erro": ERRO_ALVO_OCUPADO.format(recado)}\n'
            '        return roteiro, None\n'
            '\n'
            '    def _liberar_a_reserva(self, trabalho: str) -> None:\n'
            '        with self.trava:\n'
            '            self.em_voo.discard(trabalho)\n'
            '\n'
            '    def _disparar_retomada(self, trabalho: str, roteiro: Path,\n'
            '                           resposta: str | None = None) -> None:\n'
            '        log = (self.dir / f"{trabalho}{SUFIXO_DO_LOG}").open(\n'
            '            "a", encoding="utf-8")\n'
            '        proc = subprocess.Popen(\n'
            '            comando_de_retomada(roteiro, trabalho, self.dir, self.cwd,\n'
            '                                resposta),\n'
            '            stdout=log, stderr=subprocess.STDOUT, cwd=str(self.cwd))\n'
            '        with self.trava:\n'
            '            self.rodando[trabalho] = proc\n'
            '            self.inicio[trabalho] = time.time()\n'
            '        self.gravar_trava(proc.pid, trabalho)\n'
            '\n'
            '    def responder(self, trabalho: str, resposta: str,\n'
            '                  devolver: bool = False) -> dict:\n'
            '        if not (resposta or "").strip():\n'
            '            return {"erro": ERRO_RESPOSTA_VAZIA}\n'
            '        if devolver:\n'
            '            return self._devolver_com_recado(trabalho, resposta.strip())\n'
            '        roteiro, recusa = self._roteiro_pronto_para_retomar(trabalho)\n'
            '        if recusa:\n'
            '            return recusa\n'
            '        try:\n'
            '            _, registro = self._comentar_a_resposta_na_issue(\n'
            '                trabalho, resposta.strip())\n'
            '            self._disparar_retomada(trabalho, roteiro, resposta.strip())\n'
            '        finally:\n'
            '            self._liberar_a_reserva(trabalho)\n'
            '        return {"trabalho": trabalho, "retomada": True, "registro": registro}\n'
            '\n'
            '    def _devolver_com_recado(self, trabalho: str, recado: str) -> dict:\n'
            '        if erro := recusa_do_nome_de_trabalho(trabalho or ""):\n'
            '            return {"erro": erro}\n'
            '        postou, registro = self._comentar_a_resposta_na_issue(\n'
            '            trabalho, MOLDE_DO_COMENTARIO_DE_DEVOLUCAO.format(recado),\n'
            '            molde_do_sucesso=RECADO_DEVOLUCAO_NA_ISSUE)\n'
            '        if not postou:\n'
            '            return {"erro": ERRO_DEVOLUCAO_SEM_REGISTRO.format(registro)}\n'
            '        return {"trabalho": trabalho, "devolvido": True, "registro": registro}\n'
            '\n'
            '    def retomar_em_um_clique(self, trabalho: str) -> dict:\n'
            '        roteiro, recusa = self._roteiro_pronto_para_retomar(trabalho)\n'
            '        if recusa:\n'
            '            return recusa\n'
            '        try:\n'
            '            self._disparar_retomada(trabalho, roteiro)\n'
            '        finally:\n'
            '            self._liberar_a_reserva(trabalho)\n'
            '        return {"trabalho": trabalho, "retomada": True}\n'
            '\n'
            '    def conta_com_cache(self) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            if self._conta and momento - self._conta_em < INTERVALO_DA_CONTA_S:\n'
            '                return self._conta\n'
            '        achado = conta_das_execucoes(self.dir)\n'
            '        with self.trava:\n'
            '            self._conta, self._conta_em = achado, momento\n'
            '        return achado\n'
            '\n'
            '    def caixas_com_cache(self) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            fresco = momento - self._caixas_em\n'
            '            if self._caixas and fresco < INTERVALO_DO_QUADRO_S_POR_CORTESIA_DE_REDE:\n'
            '                return self._caixas\n'
            '        configuracao = configuracao_do_executor_sem_validar(self.cwd) or {}\n'
            '        declaradas = configuracao.get("caixas") or {}\n'
            '        repositorio = (configuracao.get("issues") or {}).get(\n'
            '            "repositorio") or ""\n'
            '        numeros = sorted({int(str(v)) for v in declaradas.values()\n'
            '                          if str(v).isdigit()})\n'
            '        achado = {"caixas": []}\n'
            '        if not numeros or not repositorio \\\n'
            '                or MARCA_DE_MOLDE_NAO_PREENCHIDO in repositorio:\n'
            '            achado["recado"] = RECADO_SEM_CAIXA\n'
            '        for numero in numeros:\n'
            '            try:\n'
            '                r = subprocess.run(\n'
            '                    ["gh", "issue", "view", str(numero), "--repo",\n'
            '                     repositorio, "--json", "body,title"],\n'
            '                    capture_output=True, text=True, timeout=TIMEOUT_DO_GH_S)\n'
            '                if r.returncode != 0:\n'
            '                    achado["recado"] = RECADO_GH_MUDO\n'
            '                    continue\n'
            '                dado = json.loads(r.stdout)\n'
            '                achado["caixas"].append(\n'
            '                    {"numero": numero, "titulo": dado.get("title", ""),\n'
            '                     "linhas": linhas_do_corpo_da_caixa(dado.get("body"))})\n'
            '            except (OSError, subprocess.SubprocessError, ValueError):\n'
            '                achado["recado"] = RECADO_SEM_REDE_OU_GH\n'
            '        with self.trava:\n'
            '            self._caixas, self._caixas_em = achado, momento\n'
            '        return achado\n'
            '\n'
            '    def podar(self, identidade: str, motivo: str) -> dict:\n'
            '        if not (identidade or "").strip() or not (motivo or "").strip():\n'
            '            return {"erro": ERRO_PODA_SEM_ID_OU_MOTIVO}\n'
            '        try:\n'
            '            r = subprocess.run(\n'
            '                [sys.executable, str(CAIXA), "podar",\n'
            '                 "--id", identidade.strip(), "--motivo", motivo.strip(),\n'
            '                 "--cwd", str(self.cwd)],\n'
            '                capture_output=True, text=True, timeout=TIMEOUT_DO_GH_S * 3)\n'
            '        except (OSError, subprocess.SubprocessError) as e:\n'
            '            return {"erro": ERRO_DISPARO_FALHOU.format(e)}\n'
            '        with self.trava:\n'
            '            self._caixas, self._caixas_em = None, 0.0\n'
            '        return {"codigo": r.returncode,\n'
            '                "saida": (r.stdout + r.stderr).strip()[-1500:]}\n'
            '\n'
            '    def _comentar_a_resposta_na_issue(\n'
            '            self, trabalho: str, resposta: str,\n'
            '            molde_do_sucesso: str = RECADO_RESPOSTA_NA_ISSUE) -> tuple:\n'
            '        gravado = estado_que_o_motor_gravou(self.dir, trabalho) or {}\n'
            '        issue = gravado.get("issue")\n'
            '        configuracao = configuracao_do_executor_sem_validar(self.cwd) or {}\n'
            '        repositorio = (configuracao.get("issues") or {}).get(\n'
            '            "repositorio") or ""\n'
            '        if not issue or not repositorio \\\n'
            '                or MARCA_DE_MOLDE_NAO_PREENCHIDO in repositorio:\n'
            '            return False, RECADO_RESPOSTA_SO_NA_RETOMADA\n'
            '        conta_das_issues = (configuracao.get("issues") or {}).get(\n'
            '            "conta_gh") or ""\n'
            '        if conta_das_issues \\\n'
            '                and MARCA_DE_MOLDE_NAO_PREENCHIDO not in conta_das_issues \\\n'
            '                and _conta_ativa_do_gh() == conta_das_issues:\n'
            '            return False, RECADO_CONTA_DO_MOTOR_NAO_ASSINA\n'
            '        try:\n'
            '            feito = subprocess.run(\n'
            '                ["gh", "issue", "comment", str(issue), "--repo", repositorio,\n'
            '                 "--body", resposta],\n'
            '                capture_output=True, text=True, timeout=TIMEOUT_DO_GH_S)\n'
            '        except (OSError, subprocess.SubprocessError):\n'
            '            return False, RECADO_SEM_REDE_OU_GH\n'
            '        return ((True, molde_do_sucesso.format(issue))\n'
            '                if feito.returncode == 0 else (False, RECADO_GH_MUDO))\n'
            '\n'
            '    def criterios_com_cache(self, trabalho: str) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            guardado, em = self._criterios.get(trabalho, (None, 0.0))\n'
            '            if guardado and (momento - em\n'
            '                             < INTERVALO_DO_QUADRO_S_POR_CORTESIA_DE_REDE):\n'
            '                return guardado\n'
            '        achado = self._criterios_da_issue(trabalho)\n'
            '        with self.trava:\n'
            '            self._criterios[trabalho] = (achado, momento)\n'
            '        return achado\n'
            '\n'
            '    def _criterios_da_issue(self, trabalho: str) -> dict:\n'
            '        gravado = estado_que_o_motor_gravou(self.dir, trabalho) or {}\n'
            '        issue = gravado.get("issue")\n'
            '        if not issue:\n'
            '            return {"recado": RECADO_TRABALHO_SEM_ISSUE}\n'
            '        configuracao = configuracao_do_executor_sem_validar(self.cwd) or {}\n'
            '        repositorio = (configuracao.get("issues") or {}).get(\n'
            '            "repositorio") or ""\n'
            '        if not repositorio or MARCA_DE_MOLDE_NAO_PREENCHIDO in repositorio:\n'
            '            return {"recado": RECADO_SEM_REPOSITORIO_DE_ISSUES}\n'
            '        try:\n'
            '            corpo = subprocess.run(\n'
            '                ["gh", "issue", "view", str(issue), "--repo", repositorio,\n'
            '                 "--json", "body", "-q", ".body"],\n'
            '                capture_output=True, text=True, timeout=TIMEOUT_DO_GH_S)\n'
            '            if corpo.returncode != 0:\n'
            '                return {"recado": RECADO_GH_MUDO}\n'
            '            medido = subprocess.run(\n'
            '                [sys.executable, str(VERIFICAR), "criterios",\n'
            '                 str(self.dir / trabalho), "--criterios", "-"],\n'
            '                input=corpo.stdout, capture_output=True, text=True,\n'
            '                timeout=TIMEOUT_DO_ANDAMENTO_S)\n'
            '        except (OSError, subprocess.SubprocessError):\n'
            '            return {"recado": RECADO_SEM_REDE_OU_GH}\n'
            '        if medido.returncode not in (0, 4):\n'
            '            return {"recado": (medido.stderr or medido.stdout)\n'
            '                    .strip()[:CAUDA_DO_ERRO_DO_ANDAMENTO]}\n'
            '        return {"issue": issue,\n'
            '                **placar_dos_criterios(\n'
            '                    medido.returncode, f"{medido.stdout}{medido.stderr}")}\n'
            '\n'
            '    def andamento(self, trabalho: str, roteiro: Path | None = None) -> dict:\n'
            '        comando = [sys.executable, str(ENCADEADOR), "andamento",\n'
            '                   "--trabalho", trabalho, "--dir", str(self.dir)]\n'
            '        alvo = (roteiro if roteiro and roteiro.exists()\n'
            '                else roteiro_gravado_no_estado(self.dir, trabalho))\n'
            '        if alvo:\n'
            '            comando += ["--roteiro", str(alvo)]\n'
            '        r = subprocess.run(comando, capture_output=True, text=True,\n'
            '                           cwd=str(self.cwd), timeout=TIMEOUT_DO_ANDAMENTO_S)\n'
            '        if r.returncode != 0:\n'
            '            return {"erro": (r.stderr or r.stdout)\n'
            '                    .strip()[:CAUDA_DO_ERRO_DO_ANDAMENTO]}\n'
            '        try:\n'
            '            estado = json.loads(r.stdout)\n'
            '        except json.JSONDecodeError:\n'
            '            return {"erro": ERRO_ANDAMENTO_SEM_JSON}\n'
            '        with self.trava:\n'
            '            proc = self.rodando.get(trabalho)\n'
            '        estado["processo"] = (PROCESSO_RODANDO if proc and proc.poll() is None\n'
            '                              else PROCESSO_ENCERRADO if proc\n'
            '                              else PROCESSO_DESCONHECIDO)\n'
            '        gravado = estado.get("gravado")\n'
            '        estado["vivacidade"] = vivacidade(proc, self.inicio.get(trabalho),\n'
            '                                          gravado)\n'
            '        calar_o_convite_a_disparar_o_que_ja_esta_no_ar(estado)\n'
            '        estado["espera_aprovacao"] = a_execucao_espera_aprovacao(estado)\n'
            '        if a_execucao_esta_no_ar(estado):\n'
            '            estado["etapa_viva"] = etapa_que_escreve_sem_ter_terminado(\n'
            '                self.dir / trabalho)\n'
            '        log = self.dir / f"{trabalho}{SUFIXO_DO_LOG}"\n'
            '        estado["log"] = (log.read_text(encoding="utf-8",\n'
            '                                       errors="replace")[-CAUDA_DO_LOG_NA_TELA:]\n'
            '                         if log.exists() else "")\n'
            '        return estado\n'
            '\n'
            '    def _issues_abertas_do_repositorio(self, repositorio: str) -> dict:\n'
            '        try:\n'
            '            r = subprocess.run(\n'
            '                ["gh", "issue", "list", "--repo", repositorio, "--state",\n'
            '                 "open", "--limit", str(LIMITE_DE_ISSUES_NO_QUADRO),\n'
            '                 "--json", "number,title,labels"],\n'
            '                capture_output=True, text=True, timeout=TIMEOUT_DO_GH_S)\n'
            '            if r.returncode != 0:\n'
            '                return {"issues": [], "recado": RECADO_GH_MUDO}\n'
            '            issues = json.loads(r.stdout)\n'
            '            for issue in issues:\n'
            '                issue["labels"] = [etiqueta.get("name", "")\n'
            '                                   for etiqueta in issue.get("labels") or []]\n'
            '            return {"issues": issues, "repositorio": repositorio}\n'
            '        except (OSError, subprocess.SubprocessError, ValueError):\n'
            '            return {"issues": [], "recado": RECADO_SEM_REDE_OU_GH}\n'
            '\n'
            '    def backlog_das_issues_com_cache(self) -> dict:\n'
            '        momento = time.time()\n'
            '        with self.trava:\n'
            '            fresco = momento - self._quadro_em\n'
            '            if self._quadro and fresco < INTERVALO_DO_QUADRO_S_POR_CORTESIA_DE_REDE:\n'
            '                return self._quadro\n'
            '        configuracao = configuracao_do_executor_sem_validar(self.cwd) or {}\n'
            '        repositorio = (configuracao.get("issues") or {}).get("repositorio") or ""\n'
            '        if not repositorio or MARCA_DE_MOLDE_NAO_PREENCHIDO in repositorio:\n'
            '            achado = {"issues": [], "recado": RECADO_SEM_REPOSITORIO_DE_ISSUES}\n'
            '        else:\n'
            '            achado = self._issues_abertas_do_repositorio(repositorio)\n'
            '        with self.trava:\n'
            '            self._quadro, self._quadro_em = achado, momento\n'
            '        return achado\n'
            '\n'
            '    def _resumo_do_trabalho(self, nome: str) -> dict:\n'
            '        gravado = estado_provado_do_motor(self.dir, nome) or {}\n'
            '        tem_roteiro_ao_lado = (self.dir / f"{nome}{SUFIXO_DO_ROTEIRO}").exists()\n'
            '        return {"nome": nome,\n'
            '                "execucao": bool(gravado) or tem_roteiro_ao_lado,\n'
            '                "situacao": gravado.get("situacao"),\n'
            '                "issue": gravado.get("issue")}\n'
            '\n'
            '    def trabalhos(self) -> list:\n'
            '        if not self.dir.is_dir():\n'
            '            return []\n'
            '        achados = [(self._resumo_do_trabalho(pasta.name),\n'
            '                    instante_da_pasta_ou_o_comeco_do_tempo(pasta))\n'
            '                   for pasta in self.dir.iterdir() if pasta.is_dir()]\n'
            '        achados.sort(key=lambda par: (par[0]["execucao"], par[1],\n'
            '                                      par[0]["nome"]), reverse=True)\n'
            '        return [resumo for resumo, _ in achados]\n'
            '\n'
            '\n'
            'LOGICA_DA_MESA = """\n'
            '// A lógica da mesa: conta e monta texto, nunca toca no documento. Mora\n'
            '// separada porque assim ela roda fora do navegador — o --testar deste\n'
            '// arquivo executa estas funções no node e verifica o HTML que sai delas.\n'
            '// Enquanto viviam no meio do DOM, ninguém conseguia medi-las.\n'
            'function esc(s){return String(s??\'\').replace(/[<&>"\']/g,c=>({\'<\':\'&lt;\',\'&\':\'&amp;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]))}\n'
            "function mm(s){return s==null?'':Math.floor(s/60)+'m'+String(s%60).padStart(2,'0')}\n"
            '\n'
            '// Vivacidade: sessão de modelo espera a API quase o tempo todo — medido, 443s\n'
            '// de relógio para 5s de CPU. O sinal aqui não é processador: é o processo\n'
            '// existir, quantas sessões respiram, e quanto falta para o teto que mata\n'
            '// sozinho. Espera com prazo não é travamento.\n'
            '//\n'
            '// Onde não houve medida, o pedaço SOME. O "?" que o rodapé mostrava dizia\n'
            '// que a mesa mediu e o resultado foi esse — e ninguém tinha medido nada.\n'
            'function vivo(v){\n'
            "  if(!v||v.situacao==='desconhecida')return '';\n"
            "  if(v.situacao==='encerrado')return `processo <b>encerrado</b> · exit ${v.codigo}`;\n"
            '  const p=[];\n'
            '  // Espera não é trabalho. O motor grava dormindo e aguardando-resposta, e a\n'
            '  // mesa repete o que ele gravou em vez de dizer "trabalhando" com ninguém\n'
            '  // trabalhando — era o defeito 4.\n'
            "  if(v.situacao==='dormindo'){\n"
            "    p.push('<b>dormindo</b>'+(v.ate?` até ${esc(v.ate)}`:'')\n"
            "           +(v.porque?` (${esc(v.porque)})`:''));\n"
            '    if(v.etapa)p.push(`na etapa <b>${esc(v.etapa)}</b>`);\n'
            "    p.push('ninguém está trabalhando');\n"
            "  }else if(v.situacao==='aguardando-resposta'){\n"
            "    p.push('<b>aguardando você</b>'+(v.issue?` na issue ${esc(v.issue)}`:''));\n"
            '    if(v.etapa)p.push(`etapa <b>${esc(v.etapa)}</b>`);\n'
            "    p.push('responda lá e retome');\n"
            '  }else{\n'
            '    // Execução que a mesa não disparou: ela não tem o processo na mão, então\n'
            '    // não mede sessão nem relógio. Dizer de quem é a execução explica o\n'
            '    // rodapé curto — inventar número seria a mentira de novo.\n'
            "    if(v.de_fora)p.push('<b>execução aberta fora desta mesa</b>');\n"
            '    if(v.sessoes!=null)\n'
            "      p.push(`<b>${v.sessoes}</b> sessão${v.sessoes===1?'':'es'} viva${v.sessoes===1?'':'s'}`);\n"
            '    if(v.decorrido_s!=null)p.push(`<b>${mm(v.decorrido_s)}</b> corridos`);\n'
            '    if(v.resta_s!=null)p.push(`morre sozinha em ${mm(v.resta_s)}`);\n'
            '    if(v.desde)p.push(`desde ${esc(v.desde)}`);\n'
            '    if(v.etapa)p.push(`etapa <b>${esc(v.etapa)}</b>`);\n'
            '  }\n'
            '  // Estado sem carimbo de tempo não se audita: de quem diz estar no ar, a\n'
            '  // mesa mostra quando foi a última escrita de verdade. É a linha que separa\n'
            '  // "está trabalhando" de "está parado dizendo que trabalha".\n'
            '  if(v.escrita_em)p.push(`última escrita ${esc(v.escrita_em)}`);\n'
            "  return p.join(' · ');\n"
            '}\n'
            '\n'
            '// AGORA: a etapa em curso não fechou evidência nenhuma — e mesmo assim está\n'
            '// escrevendo. O fim do .log dela é a diferença entre "nada aconteceu" e\n'
            '// "está acontecendo isto". O bloco só existe enquanto ela escreve.\n'
            'function agora(d){\n'
            '  const e=d.etapa_viva;\n'
            "  if(!e)return '';\n"
            "  const ordem=String(e.ordem).padStart(2,'0');\n"
            '  return `<div class="agora">\n'
            '    <div class="agora-topo">\n'
            '      <span>agora · etapa ${ordem} ${esc(e.nome)}</span>\n'
            '      <span>ciclo ${esc(e.ciclo)} · ${esc(e.bytes)} bytes, sem evidência ainda</span>\n'
            '    </div><pre class="agora-cauda">${esc(e.cauda)}</pre></div>`;\n'
            '}\n'
            '\n'
            'function fita(d){\n'
            '  const et=d.etapas||[];\n'
            '  if(!et.length)return d.etapa_viva\n'
            '    ? `<p class="vazia">a etapa ${esc(d.etapa_viva.nome)} está escrevendo — `\n'
            '      + `a evidência só fecha quando ela termina</p>`\n'
            '    : \'<p class="vazia">nenhuma evidência ainda</p>\';\n'
            '  return et.map(e=>{\n'
            "    const vd=e.veredito||'espera';\n"
            "    const faltas=(e.faltas||[]).map(esc).join('<br>');\n"
            "    const perg=e.pergunta?`<b>${esc(e.pergunta)}</b>`:'';\n"
            "    const det=[perg,faltas].filter(Boolean).join('<br>');\n"
            '    return `<li class="linha-r">\n'
            '      <span class="ordem">${String(e.ordem).padStart(2,\'0\')}</span>\n'
            '      <span class="nome">${esc(e.nome)}</span>\n'
            '      <span class="vd ${vd}">${vd===\'espera\'?\'·····\':vd}</span>\n'
            '      <span class="ciclo">${e.ciclo?e.ciclo.i+\'/\'+e.ciclo.teto:\'\'}</span>\n'
            '      ${det?`<span class="detalhe">${det}</span>`:\'\'}</li>`;\n'
            "  }).join('');\n"
            '}\n'
            '\n'
            '// Os estágios da execução: a mesma matéria-prima da fita, lida de relance.\n'
            '// Cada etapa é um bloco — verde passou, vermelho parou, e a que está em curso\n'
            '// ganha o contorno. Quem olha vê o passo atual e o que falta sem ler linha.\n'
            '// Mora numa caixa com rótulo, como a fita e o agora: solto, o primeiro bloco\n'
            '// verde da tela parecia um botão, e o olho ia parar no lugar errado.\n'
            'function desenho(d){\n'
            '  const et=d.etapas||[];\n'
            "  if(!et.length)return '';\n"
            '  const atual=et.findIndex(e=>!e.veredito);\n'
            '  const passos=et.map((e,i)=>{\n'
            "    const vd=e.veredito||'espera';\n"
            "    const eu=(i===atual)?' agora':'';\n"
            '    return `<span class="passo ${vd}${eu}" title="${esc(e.nome)}: ${vd}">` +\n'
            '           `${esc(e.nome)}</span>`;\n'
            '  }).join(\'<span class="seta">→</span>\');\n'
            '  const feitas=et.filter(e=>e.veredito).length;\n'
            '  return `<div class="estagios">\n'
            '    <div class="estagios-topo"><span>estágios da execução</span>\n'
            '      <span>${feitas} de ${et.length} etapas · ${et.length-feitas} pela frente</span>\n'
            '    </div><div class="desenho">${passos}</div></div>`;\n'
            '}\n'
            '\n'
            '// O corpo da mesa, inteiro, em texto. Quem chama é que põe no documento.\n'
            '// A caixa do log recebe de fora o estado em que estava: repintar recria o\n'
            '// elemento, e <details> recriado nasce fechado. Era a caixa que se fechava\n'
            '// sozinha no meio da leitura, a cada 2,5s.\n'
            '// O HERÓI do "esperando você": a pergunta em corpo grande, o placar dos\n'
            '// critérios ao lado dos botões, e a resposta que retoma do ponto exato.\n'
            '// Nada roda enquanto o dono não falar — então a tela inteira aponta para cá.\n'
            'function heroi(d){\n'
            "  if(!d.espera_aprovacao)return '';\n"
            '  const perg=(d.etapas||[]).filter(e=>e.pergunta);\n'
            "  if(!perg.length)return '';\n"
            '  return `<div class="heroi" id="heroi">\n'
            '    <div class="heroi-rotulo">o executor de roteiros está esperando você</div>\n'
            '    <div class="heroi-pergunta">${perg.map(e=>esc(e.pergunta)).join(\'<br>\')}</div>\n'
            '    <div id="placar" class="placar">critérios da issue: medindo…</div>\n'
            '    <textarea id="resposta" placeholder="A resposta entra na retomada — a execução continua do ponto exato. Vazio, Aprovar segue com \'Aprovado.\'"></textarea>\n'
            '    <div class="heroi-botoes">\n'
            '      <button id="aprovar">Aprovar e retomar</button>\n'
            '      <button id="devolver" class="secundario">Devolver com recado</button>\n'
            '    </div>\n'
            '    <p class="nota">Ela fica parada até você responder — nada roda enquanto isso.\n'
            '    Aprovar comenta na issue em seu nome, e é o comentário que registra quem\n'
            '    aprovou. Devolver registra a recusa na issue, com o recado, e não retoma\n'
            '    nada — a execução segue parada. O arquivo que a pergunta cita continua\n'
            '    valendo para quem trabalha sem a issue à mão;\n'
            '    ele não ganha botão porque não tem autor.</p>\n'
            '  </div>`;\n'
            '}\n'
            '\n'
            '// CONFIGURAÇÃO FALTANDO: o exemplo público diz o que existe; o arquivo local\n'
            '// desta máquina diz o que foi preenchido. Sai daqui o NOME da chave e mais\n'
            '// nada — o valor local nomeia repositório e conta, e não sobe para a tela.\n'
            '// Sem nada a apontar o bloco SOME: caixa verde permanente vira paisagem, e\n'
            '// paisagem ninguém lê.\n'
            'function pintaConfiguracao(d){\n'
            "  if(!d) return '';\n"
            '  if(d.recado) return \'<div class="maq"><p class="naomedido">\'+esc(d.recado)+\'</p></div>\';\n'
            "  const bloco=(titulo,chaves)=>(chaves&&chaves.length)?'<h3>'+esc(titulo)+'</h3><ul>'\n"
            "    +chaves.map(c=>'<li><b>'+esc(c)+'</b></li>').join('')+'</ul>':'';\n"
            "  const corpo=bloco('declaradas no exemplo e ausentes aqui',d.faltando)\n"
            "    +bloco('presentes com valor por preencher',d.por_preencher);\n"
            '  return corpo?\'<div class="maq">\'+corpo+\'</div>\':\'\';\n'
            '}\n'
            '\n'
            'function corpoDaMesa(d,logAberto){\n'
            '  if(d.erro)return `<div class="recado ruim"><b>não consegui ler</b>${esc(d.erro)}</div>`;\n'
            '  const v=vivo(d.vivacidade);\n'
            '  return `\n'
            '    ${heroi(d)}\n'
            '    ${desenho(d)}\n'
            '    ${agora(d)}\n'
            '    <div class="fita">\n'
            '      <div class="fita-topo"><span>fita de evidências</span>\n'
            "        <span>${esc(d.estado||'')} · ${d.paras??0} parada${d.paras===1?'':'s'}</span></div>\n"
            '      <ul class="tira">${fita(d)}</ul>\n'
            '    </div>\n'
            '    ${d.proxima_acao?`<div class="recado"><b>próxima ação</b>${esc(d.proxima_acao)}</div>`:\'\'}\n'
            '    ${v?`<div class="rodape">${v}</div>`:\'\'}\n'
            '    ${d.log?`<details class="log"${logAberto?\' open\':\'\'}><summary>log da execução</summary><pre>${esc(d.log)}</pre></details>`:\'\'}`;\n'
            '}\n'
            '"""\n'
            '\n'
            '\n'
            'PAGINA_MOLDE = """<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">\n'
            '<meta name="viewport" content="width=device-width,initial-scale=1">\n'
            '<title>Mesa do executor de roteiros</title><style>\n'
            '/* A mesa é um instrumento, não um site. Uma família monoespaçada carrega\n'
            '   todo dado e todo rótulo — placa de equipamento, silkscreen —, e a sans\n'
            '   entra só onde há frase para ler. Cor é SINAL: o que não é estado não tem\n'
            '   cor.\n'
            '\n'
            '   A PALETA é uma só, e é a escura aprovada no épico — não há mais versão\n'
            '   clara para o navegador escolher. Cada valor abaixo é do desenho aprovado;\n'
            '   nenhum hex nasce fora daqui, e o único tom derivado se deriva à vista.\n'
            '   Semântica, igual em toda aba: violeta = rodando · âmbar = esperando você ·\n'
            '   verde = completa · vermelho = falha · cinza = fila. Cor nunca sozinha:\n'
            '   sempre ponto mais rótulo. */\n'
            ':root{\n'
            '  --papel:#08090a; --superficie:#0f1011; --sulco:#161718;\n'
            '  --risco:#1b1d21; --linha:#23252a; --borda:#2a2e33;\n'
            '  --tinta:#f7f8f8; --grafite:#8a8f98;\n'
            '  --fraco:color-mix(in srgb,#8a8f98 72%,#08090a);\n'
            '  --corre:#5e6ad2; --segue:#4cb782; --pergunta:#f2c94c; --para:#eb5757;\n'
            '  --mono:ui-monospace,"SF Mono","Cascadia Mono","Roboto Mono",Menlo,monospace;\n'
            '  --sans:ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;\n'
            '}\n'
            '/* Número não dança ao atualizar: onde o mono carrega dado, largura fixa. */\n'
            '.selo,.coord dd,.ordem,.ciclo,.linha-i .num,.rodape,.agora-topo,\n'
            '.estagios-topo,.linha-r{font-variant-numeric:tabular-nums}\n'
            '*{box-sizing:border-box}\n'
            '[hidden]{display:none!important}\n'
            'body{margin:0;padding:0;background:var(--papel);color:var(--tinta);\n'
            '  font:14px/1.55 var(--sans);-webkit-font-smoothing:antialiased}\n'
            '\n'
            '/* AS CINCO ABAS: barra lateral de 220px, em texto, com a versão da camada ao\n'
            '   lado do nome. Cada aba marca a própria linha, e só a folha dela fica sem\n'
            '   [hidden] — trocar de assunto não recarrega página nem perde a execução que\n'
            '   a mesa está acompanhando. */\n'
            '.mesa{display:grid;grid-template-columns:220px minmax(0,1fr)}\n'
            '.abas{position:sticky;top:0;align-self:start;height:100vh;display:flex;\n'
            '  flex-direction:column;gap:2px;padding:14px 10px;\n'
            '  background:var(--superficie);border-right:1px solid var(--borda)}\n'
            '.marca{display:flex;align-items:center;gap:8px;flex-wrap:wrap;\n'
            '  padding:6px 10px 16px;font:600 11px/1.4 var(--mono);letter-spacing:.18em;\n'
            '  text-transform:uppercase;color:var(--grafite)}\n'
            '.aba{width:100%;min-height:36px;padding:9px 11px;border-radius:4px;\n'
            '  background:transparent;color:var(--grafite);text-align:left;\n'
            '  font:500 13px/1.2 var(--sans);letter-spacing:0;text-transform:none}\n'
            '.aba:hover{background:var(--sulco);color:var(--tinta)}\n'
            '.aba.atual{background:var(--sulco);color:var(--tinta);\n'
            '  box-shadow:inset 2px 0 0 var(--corre)}\n'
            '.conteudo{min-width:0;padding-bottom:64px}\n'
            '.folha{max-width:1200px;margin:0 auto;padding:0 20px}\n'
            '.folha>h2{font:600 11px/1 var(--mono);letter-spacing:.18em;\n'
            '  text-transform:uppercase;color:var(--fraco);margin:22px 0 8px}\n'
            '\n'
            '/* O QUE A ABA AINDA NÃO TEM. Esta fatia distribuiu nas abas o que as rotas\n'
            '   de hoje já servem; o resto do desenho aprovado espera rota. Aba que não\n'
            '   tem tudo diz o que falta na cara — tela vazia sem explicação faz quem olha\n'
            '   achar que a mesa quebrou. */\n'
            '.falta{border-left:2px solid var(--pergunta);background:var(--sulco);\n'
            '  padding:11px 14px;margin:12px 0 0;border-radius:0 3px 3px 0;\n'
            '  font:12.5px/1.6 var(--sans);color:var(--grafite)}\n'
            '\n'
            '/* A FAIXA DE ESTADO: fixa no topo, respondendo "preciso agir?" antes de\n'
            '   qualquer outra coisa — em qualquer estado. À esquerda o estado em voz de\n'
            '   placa; no meio a resposta em uma frase; à direita a ÚNICA ação principal\n'
            '   da tela. O resto da mesa mora nas duas colunas abaixo. */\n'
            '.faixa{position:sticky;top:0;z-index:5;display:flex;align-items:center;\n'
            '  gap:8px 16px;flex-wrap:wrap;min-height:44px;padding:8px 20px;\n'
            '  background:var(--papel);border-bottom:2px solid var(--tinta)}\n'
            '.faixa .estado{display:flex;align-items:center;gap:8px;\n'
            '  font:600 12px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase}\n'
            '.faixa .devo{font:12.5px/1.4 var(--sans);color:var(--grafite)}\n'
            '.abas #panico{margin-top:auto;color:var(--para);border-color:var(--para);\n'
            '  font-size:12px;min-height:36px}\n'
            '.abas #panico.armado{background:var(--para);color:var(--tinta)}\n'
            '.abas .selo-leitura{font:11px/1.4 var(--sans);color:var(--pergunta);\n'
            '  border:1px solid var(--pergunta);border-radius:8px;padding:4px 8px;\n'
            '  margin-top:auto;text-align:center}\n'
            '.abas .selo-leitura:not([hidden])+#panico{margin-top:8px}\n'
            '.mono-n{font-family:var(--mono);font-variant-numeric:tabular-nums}\n'
            '.raia{display:flex;align-items:center;gap:8px;margin:4px 0}\n'
            '.raia-nome{font:11px/1.2 var(--mono);color:var(--grafite);width:180px;\n'
            '  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:right}\n'
            '.raia-faixa{position:relative;flex:1;height:22px;background:var(--superficie);\n'
            '  border:1px solid var(--risco);border-radius:6px;overflow:hidden}\n'
            '.raia-faixa .bloco{position:absolute;top:2px;bottom:2px;background:var(--sulco);\n'
            '  border:1px solid var(--borda);border-radius:4px;font:10px/1.6 var(--mono);\n'
            '  color:var(--grafite);padding:0 4px;overflow:hidden;white-space:nowrap;\n'
            '  cursor:pointer}\n'
            '.raia-faixa .bloco:hover{color:var(--tinta);border-color:var(--corre)}\n'
            '.raia-faixa .marca{position:absolute;top:0;bottom:0;width:2px;\n'
            '  background:var(--pergunta)}\n'
            '.tempo-log pre{max-height:16rem;overflow:auto;font:11px/1.5 var(--mono);\n'
            '  background:var(--superficie);border:1px solid var(--risco);border-radius:6px;\n'
            '  padding:8px;margin-top:6px}\n'
            '.linha-t .retomar-1{margin-left:auto;font:11px/1 var(--sans);color:var(--segue);\n'
            '  border:1px solid var(--segue);border-radius:8px;padding:3px 8px}\n'
            '.linha-t .retomar-1:hover{background:var(--segue);color:var(--papel)}\n'
            '.linha-i.caixa-fixa{border-style:dashed;opacity:.85}\n'
            '.podar-linha{color:var(--para);border-color:var(--para)}\n'
            '.faixa .sino{font:12px/1 var(--sans);color:var(--papel);background:var(--pergunta);\n'
            '  border-radius:10px;padding:5px 10px;white-space:nowrap}\n'
            '.faixa .sino b{font-variant-numeric:tabular-nums}\n'
            '.faixa #mudo{min-height:32px;font-size:12px}\n'
            '.faixa #mudo.muda{color:var(--pergunta);border-color:var(--pergunta)}\n'
            '.faixa #acao{margin-left:auto;min-height:40px}\n'
            '.selo{font:500 10px/1 var(--mono);letter-spacing:.1em;\n'
            '  color:var(--fraco);border:1px solid var(--linha);border-radius:2px;\n'
            '  padding:3px 6px;text-transform:none}\n'
            '.bulbo{width:8px;height:8px;border-radius:50%;background:var(--fraco);\n'
            '  box-shadow:0 0 0 3px color-mix(in srgb,var(--fraco) 22%,transparent)}\n'
            '.f-corre .bulbo{background:var(--corre);box-shadow:0 0 0 3px color-mix(in srgb,var(--corre) 22%,transparent);animation:pulsa 1.6s ease-in-out infinite}\n'
            '.f-corre .estado{color:var(--corre)} .f-segue .bulbo{background:var(--segue)}\n'
            '.f-segue .estado{color:var(--segue)}\n'
            '.f-para .bulbo{background:var(--para)} .f-para .estado{color:var(--para)}\n'
            '.f-pergunta .bulbo{background:var(--pergunta)}\n'
            '.f-pergunta .estado{color:var(--pergunta)}\n'
            '@keyframes pulsa{0%,100%{opacity:1}50%{opacity:.35}}\n'
            '@media(prefers-reduced-motion:reduce){.f-corre .bulbo{animation:none}}\n'
            '\n'
            '/* AS DUAS COLUNAS DA ABA MESA: a fila de issues (de onde o trabalho sai) e o\n'
            '   palco (onde a execução viva aparece). A fila é estreita e de linhas curtas;\n'
            '   o palco recebe o resto. */\n'
            '.colunas{display:grid;grid-template-columns:340px minmax(0,1fr);\n'
            '  gap:8px 30px;margin:14px 0 0;align-items:start}\n'
            '.fila h2,.palco h2{font:600 10px/1 var(--mono);letter-spacing:.18em;\n'
            '  text-transform:uppercase;color:var(--fraco);margin:18px 0 6px}\n'
            '.linha-t{display:flex;align-items:center;gap:10px;min-height:44px;\n'
            '  width:100%;padding:4px 10px;border:0;border-bottom:1px solid var(--risco);\n'
            '  background:transparent;color:var(--tinta);font:13px/1.4 var(--mono);\n'
            '  text-align:left;cursor:pointer;text-transform:none;letter-spacing:0}\n'
            '.linha-t:hover{background:var(--sulco)}\n'
            '.linha-t span:first-child{min-width:0;overflow:hidden;\n'
            '  text-overflow:ellipsis;white-space:nowrap}\n'
            '.linha-t.atual{border-left:2px solid var(--corre);background:var(--sulco)}\n'
            '.linha-t .selo-s{margin-left:auto;font:600 9px/1 var(--mono);\n'
            '  letter-spacing:.12em;text-transform:uppercase;color:var(--grafite)}\n'
            '.linha-i{display:flex;align-items:center;gap:8px;min-height:44px;\n'
            '  padding:4px 10px;border-bottom:1px solid var(--risco);font:13px/1.4 var(--mono)}\n'
            '.linha-i .num{color:var(--fraco);min-width:3.2rem}\n'
            '.linha-i .tit{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;\n'
            '  white-space:nowrap}\n'
            '.linha-i button{padding:7px 12px;font-size:10px}\n'
            '\n'
            '/* O HERÓI do esperando-você: pergunta grande, placar ao lado dos botões. */\n'
            '.heroi{border:1px solid var(--linha);border-left:3px solid var(--pergunta);\n'
            '  border-radius:0 3px 3px 0;background:var(--sulco);padding:16px 18px;\n'
            '  margin:14px 0 0}\n'
            '.heroi-rotulo{font:600 10px/1 var(--mono);letter-spacing:.16em;\n'
            '  text-transform:uppercase;color:var(--pergunta);margin-bottom:10px}\n'
            '.heroi-pergunta{font:600 19px/1.45 var(--sans);margin-bottom:12px}\n'
            '.placar{border:1px solid var(--linha);border-radius:3px;background:var(--papel);\n'
            '  padding:10px 12px;font:12.5px/1.6 var(--sans);color:var(--grafite)}\n'
            '.placar b{color:var(--tinta)}\n'
            '.placar ul{margin:6px 0 0;padding-left:18px}\n'
            '.heroi-botoes{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}\n'
            'button.secundario{background:transparent;color:var(--tinta);\n'
            '  border:1px solid var(--tinta)}\n'
            '\n'
            '/* comandos */\n'
            '.comandos{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:6px}\n'
            'label.campo{display:flex;align-items:center;gap:7px;\n'
            '  font:500 10px/1 var(--mono);letter-spacing:.14em;color:var(--fraco);\n'
            '  text-transform:uppercase}\n'
            'select,input,textarea{font:13px/1.4 var(--mono);color:var(--tinta);\n'
            '  background:var(--sulco);border:1px solid var(--linha);border-radius:3px;\n'
            '  padding:7px 9px}\n'
            'select{max-width:100%;min-width:0}\n'
            '.fila,.palco{min-width:0}\n'
            'label.campo{flex-wrap:wrap;max-width:100%;min-width:0}\n'
            'textarea{width:100%;min-height:104px;resize:vertical;margin:10px 0 0;\n'
            '  background:var(--sulco)}\n'
            'button{font:600 11px/1 var(--mono);letter-spacing:.16em;text-transform:uppercase;\n'
            '  color:#fff;background:var(--corre);border:0;border-radius:3px;\n'
            '  padding:11px 20px;cursor:pointer}\n'
            'button:disabled{opacity:.4;cursor:default}\n'
            ':focus-visible{outline:2px solid var(--corre);outline-offset:2px}\n'
            '.nota{font:12px/1.5 var(--sans);color:var(--fraco);flex:1 1 220px}\n'
            '.direita{margin-left:auto}\n'
            '\n'
            '/* COMEÇAR UM TRABALHO: o formulário completo mora na aba Execuções, abaixo\n'
            '   da lista. O caminho de um clique é a linha do backlog, que fica na aba\n'
            '   Mesa — a que abre; este é o caminho do pedido escrito à mão. */\n'
            '#pedido{margin-top:18px;border-top:1px solid var(--linha);padding-top:14px}\n'
            '\n'
            '/* A MÁQUINA: o que existe aqui e não é do trabalho em curso. Chega pela rota\n'
            '   /maquina e se reparte entre duas abas — servidores e rotinas em\n'
            '   Instrumentos, guia e skills em Prompts & skills. É consulta, não\n'
            '   acompanhamento: muda em dias, não em segundos, então só se lê quando\n'
            '   alguém abre a aba. A distinção que a cor carrega é uma só: medido e vazio\n'
            '   é um fato; não medido é a confissão de que ninguém olhou. */\n'
            '.coord{display:grid;grid-template-columns:auto 1fr;gap:0 18px;\n'
            '  border-bottom:1px solid var(--linha);padding:10px 0;margin:8px 0 12px}\n'
            '.coord dt{font:500 10px/1.9 var(--mono);letter-spacing:.16em;color:var(--fraco);\n'
            '  text-transform:uppercase}\n'
            '.coord dd{margin:0;font:13px/1.9 var(--mono);word-break:break-all}\n'
            '.maq-topo{display:flex;align-items:center;gap:.6rem;margin:.4rem 0 .8rem}\n'
            'button.miudo{padding:.25rem .6rem;font-size:10px}\n'
            '.maq h3{font:600 11px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;\n'
            '  color:var(--grafite);margin:1.1rem 0 .4rem}\n'
            '.maq ul{list-style:none;padding:0;margin:0}\n'
            '.maq li{padding:.35rem 0;border-bottom:1px solid var(--risco);\n'
            '  font:12px/1.5 var(--sans)}\n'
            '.maq li b{font:600 12px/1.5 var(--mono);color:var(--tinta)}\n'
            '.maq li span{color:var(--grafite)}\n'
            '.maq p{font:12px/1.6 var(--sans);color:var(--grafite);margin:.2rem 0 .6rem}\n'
            '.maq .naomedido{color:var(--pergunta)}\n'
            '.maq .depe{color:var(--segue)}\n'
            '.maq .caido{color:var(--para)}\n'
            '.faixa .depe{color:var(--segue)}\n'
            '.faixa .caido{color:var(--para)}\n'
            '\n'
            '/* AGORA: o único bloco da mesa que muda sozinho enquanto você olha. Fica\n'
            '   acima da fita porque é o presente, e a fita é o passado. Some no instante\n'
            '   em que a etapa fecha a evidência — a partir dali quem conta a história é a\n'
            '   fita. */\n'
            '.agora{margin:20px 0 0;border:1px solid var(--linha);\n'
            '  border-left:2px solid var(--corre);border-radius:0 3px 3px 0;\n'
            '  background:var(--sulco);overflow:hidden}\n'
            '.agora-topo{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;\n'
            '  padding:9px 14px;border-bottom:1px solid var(--linha);\n'
            '  font:600 10px/1.4 var(--mono);letter-spacing:.14em;text-transform:uppercase;\n'
            '  color:var(--corre)}\n'
            '.agora-topo span+span{color:var(--fraco);font-weight:500;letter-spacing:.1em}\n'
            '.agora-cauda{margin:0;border:0;border-radius:0;max-height:190px;\n'
            '  background:transparent}\n'
            '\n'
            '/* A ASSINATURA: a fita de evidências. O encadeador imprime uma evidência por etapa,\n'
            '   em ordem — a tela mostra a fita saindo dele, com a borda serrilhada de\n'
            '   papel picotado feita só com gradiente. */\n'
            '.fita{margin:24px 0 0;border:1px solid var(--linha);border-radius:3px;\n'
            '  background:var(--sulco);overflow:hidden}\n'
            '.fita-topo{display:flex;justify-content:space-between;align-items:center;\n'
            '  padding:9px 14px 9px 30px;border-bottom:1px solid var(--linha);\n'
            '  font:500 10px/1 var(--mono);letter-spacing:.16em;color:var(--fraco);\n'
            '  text-transform:uppercase}\n'
            '.tira{position:relative;margin:0;padding:0;list-style:none}\n'
            '.tira::before{content:"";position:absolute;left:9px;top:0;bottom:0;width:7px;\n'
            '  background:radial-gradient(circle at 3.5px 5px,var(--papel) 2.2px,transparent 2.4px)\n'
            '    0 0/7px 13px repeat-y}\n'
            '.linha-r{display:grid;grid-template-columns:34px 1fr 84px 52px;gap:12px;\n'
            '  align-items:baseline;padding:11px 14px 11px 30px;\n'
            '  border-bottom:1px dashed var(--linha);font:13px/1.5 var(--mono)}\n'
            '.linha-r:last-child{border-bottom:0}\n'
            '.ordem{color:var(--fraco);font-size:11px;letter-spacing:.08em}\n'
            '.nome{font-weight:500}\n'
            '.vd{font:600 10px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase}\n'
            '.vd.segue{color:var(--segue)}\n'
            '.estagios{margin:14px 0 0;border:1px solid var(--linha);border-radius:3px;\n'
            '  background:var(--sulco);overflow:hidden}\n'
            '.estagios-topo{display:flex;justify-content:space-between;gap:12px;\n'
            '  flex-wrap:wrap;padding:9px 14px;border-bottom:1px solid var(--linha);\n'
            '  font:500 10px/1.4 var(--mono);letter-spacing:.16em;text-transform:uppercase;\n'
            '  color:var(--fraco)}\n'
            '.desenho{display:flex;flex-wrap:wrap;align-items:center;gap:.35rem;\n'
            '  padding:12px 14px}\n'
            '.passo{padding:.2rem .5rem;border-radius:3px;font-size:.82rem;\n'
            '  border:1px solid var(--linha);white-space:nowrap}\n'
            '.passo.segue{background:var(--segue);color:#fff;border-color:var(--segue)}\n'
            '.passo.para{background:var(--para);color:#fff;border-color:var(--para)}\n'
            '.passo.pergunta{background:var(--pergunta);color:#000;border-color:var(--pergunta)}\n'
            '.passo.espera{opacity:.55}\n'
            '.passo.agora{outline:2px solid var(--corre);outline-offset:1px;font-weight:600}\n'
            '.seta{opacity:.4;font-size:.8rem}\n'
            '.quadro{max-height:24rem;overflow:auto}\n'
            '.quadro-topo{padding:.35rem 10px;color:var(--fraco);font:11px/1.5 var(--sans)}\n'
            '.vd.para{color:var(--para)}\n'
            '.vd.pergunta{color:var(--pergunta)} .vd.espera{color:var(--fraco)}\n'
            '.ciclo{color:var(--fraco);font-size:11px;text-align:right}\n'
            '.detalhe{grid-column:2/-1;font:12.5px/1.55 var(--sans);color:var(--grafite);\n'
            '  margin-top:5px;max-height:8.5em;overflow-y:auto}\n'
            '.detalhe b{color:var(--tinta)}\n'
            '.vazia{padding:22px 30px;color:var(--fraco);font:13px/1 var(--mono)}\n'
            '\n'
            '\n'
            '/* recados */\n'
            '.recado{border-left:2px solid var(--corre);background:var(--sulco);\n'
            '  padding:12px 15px;margin:20px 0 0;border-radius:0 3px 3px 0;\n'
            '  font:13.5px/1.6 var(--sans)}\n'
            '.recado b{font:600 10px/1 var(--mono);letter-spacing:.16em;text-transform:uppercase;\n'
            '  display:block;margin-bottom:6px;color:var(--grafite)}\n'
            '.recado.perg{border-left-color:var(--pergunta)}\n'
            '.recado.perg b{color:var(--pergunta)}\n'
            '.recado.ruim{border-left-color:var(--para)} .recado.ruim b{color:var(--para)}\n'
            '\n'
            '/* rodapé de vivacidade e o log cru */\n'
            '.rodape{display:flex;gap:10px 26px;flex-wrap:wrap;align-items:baseline;\n'
            '  margin-top:16px;padding-top:12px;border-top:1px solid var(--linha);\n'
            '  font:12px/1.6 var(--mono);color:var(--grafite)}\n'
            '.rodape b{color:var(--tinta);font-weight:600}\n'
            'details{margin-top:16px}\n'
            'summary{cursor:pointer;font:500 10px/1 var(--mono);letter-spacing:.16em;\n'
            '  color:var(--fraco);text-transform:uppercase;padding:6px 0}\n'
            'pre{margin:8px 0 0;padding:13px 15px;background:var(--sulco);\n'
            '  border:1px solid var(--linha);border-radius:3px;overflow:auto;max-height:300px;\n'
            '  font:12px/1.6 var(--mono);white-space:pre-wrap;color:var(--grafite)}\n'
            '.oquefaz{grid-column:1/-1;margin:2px 0 6px;padding:8px 10px;\n'
            '  border-left:3px solid var(--linha);background:var(--sulco);\n'
            '  font:12px/1.55 var(--mono);white-space:pre-wrap;color:var(--grafite)}\n'
            '/* TELA ESTREITA: a barra lateral deita e vira uma tira rolável no topo, as\n'
            '   colunas empilham, o palco sobe, a fila vira gaveta logo abaixo, e o botão\n'
            '   principal ganha dedo (48px). */\n'
            '@media(max-width:700px){\n'
            '  .mesa{grid-template-columns:1fr}\n'
            '  .abas{position:static;height:auto;flex-direction:row;flex-wrap:wrap;\n'
            '    padding:8px;border-right:0;border-bottom:1px solid var(--borda)}\n'
            '  .marca{padding:6px 10px;flex-basis:100%}\n'
            '  .aba{width:auto;min-height:44px;white-space:nowrap}\n'
            '  .colunas{grid-template-columns:1fr;gap:4px}\n'
            '  .palco{order:0}\n'
            '  .fila{order:1;border-top:1px solid var(--linha);padding-top:6px}\n'
            '  .faixa #acao,#b{min-height:48px}\n'
            '  #b{width:100%}\n'
            '  .linha-r{grid-template-columns:28px 1fr;gap:6px}\n'
            '  .vd,.ciclo{grid-column:2;text-align:left}\n'
            '}\n'
            '</style></head><body>\n'
            '\n'
            '<div class="mesa">\n'
            '<nav class="abas" id="abas" aria-label="as cinco abas da mesa">\n'
            '  <div class="marca">a mesa<span class="selo" id="versao">—</span></div>\n'
            '  <button class="aba atual" id="aba-mesa" data-aba="mesa">Mesa</button>\n'
            '  <button class="aba" id="aba-execucoes" data-aba="execucoes">Execuções</button>\n'
            '  <button class="aba" id="aba-instrumentos" data-aba="instrumentos">Instrumentos</button>\n'
            '  <button class="aba" id="aba-prompts" data-aba="prompts">Prompts &amp; skills</button>\n'
            '  <button class="aba" id="aba-nucleo" data-aba="nucleo">Configurações</button>\n'
            '  <span class="selo-leitura" id="selo-leitura" hidden>só-leitura — o servidor recusa escrita</span>\n'
            '  <button id="panico" title="parada limpa: sinal educado, ponto de retomada na issue, prazo curto, derrubada">parada de emergência</button>\n'
            '</nav>\n'
            '\n'
            '<div class="conteudo">\n'
            '<header class="faixa" id="faixa">\n'
            '  <span class="estado"><span class="bulbo"></span><span id="farol-txt">medindo…</span></span>\n'
            '  <span class="devo" id="devo">preciso agir? medindo…</span>\n'
            '  <span class="devo mono-n" id="conta-dia" hidden title="soma dos registros do executor gravados hoje"></span>\n'
            '  <span class="devo" id="containers" hidden title="containers deste workspace, medidos pelo docker"></span>\n'
            '  <span class="sino" id="sino" hidden><b id="sino-n">0</b> esperando você</span>\n'
            '  <button id="mudo" title="mudo cala a narração na hora — a execução nunca pausa">som</button>\n'
            '  <button id="acao" hidden></button>\n'
            '</header>\n'
            '\n'
            '<section class="folha" id="folha-mesa">\n'
            '<div class="colunas">\n'
            '<aside class="fila" id="fila">\n'
            '  <h2>a fila de issues</h2>\n'
            '  <div id="quadro" class="quadro"></div>\n'
            '</aside>\n'
            '\n'
            '<main class="palco" id="palco">\n'
            '  <div id="saida"></div>\n'
            '</main>\n'
            '</div>\n'
            '<h2>a linha do tempo do dia</h2>\n'
            '<div id="tempo-raias"><p class="nota">nenhuma etapa gravada hoje.</p></div>\n'
            '<div id="tempo-log" class="tempo-log" hidden><pre id="tempo-log-texto"></pre></div>\n'
            '</section>\n'
            '\n'
            '<section class="folha" id="folha-execucoes" hidden>\n'
            '  <h2>execuções</h2>\n'
            '  <div id="execucoes"></div>\n'
            '  <label class="campo" title="mostrar também os trabalhos que já terminaram">\n'
            '    <input id="historico" type="checkbox"> mostrar o histórico\n'
            '  </label>\n'
            '  <div id="pedido">\n'
            '    <h2>começar um trabalho do zero</h2>\n'
            '    <div class="comandos">\n'
            '      <label class="campo">o que executar\n'
            '        <select id="modo"><option value="prompt">um pedido meu</option></select>\n'
            '      </label>\n'
            '      <div id="oquefaz" class="oquefaz" hidden></div>\n'
            '    </div>\n'
            '    <textarea id="p" placeholder="O pedido, completo. A sessão nasce sem contexto: diga onde olhar, o que medir e o que você aceita como prova."></textarea>\n'
            '    <div class="comandos">\n'
            '      <label class="campo" id="lissue" title="o número da issue que este trabalho atende: a execução conta a história lá, passo a passo">nº da issue\n'
            '        <input id="issue" type="number" min="1" placeholder="—" style="width:64px">\n'
            '      </label>\n'
            '      <label class="campo" id="lturnos" title="quantos turnos de sessão cada etapa pode gastar antes de fechar">turnos por etapa\n'
            '        <input id="turnos" type="number" value="24" min="4" max="120" style="width:62px">\n'
            '      </label>\n'
            '      <label class="campo" id="lteto" title="quantas vezes a execução pode reprovar antes de escalar">tentativas\n'
            '        <input id="teto" type="number" value="3" min="1" max="9" style="width:52px">\n'
            '      </label>\n'
            '      <label class="campo" id="lauditoria" title="ao fim da execução o auditor relê as evidências e diz o que ficou por provar; desligado, nada muda">\n'
            '        <input id="auditoria" type="checkbox"> auditar ao fim\n'
            '      </label>\n'
            '    </div>\n'
            '    <div class="comandos">\n'
            '      <button id="b">Executar</button>\n'
            '      <span class="nota" id="dica"></span>\n'
            '    </div>\n'
            '  </div>\n'
            '</section>\n'
            '\n'
            '<section class="folha" id="folha-instrumentos" hidden>\n'
            '  <h2>instrumentos</h2>\n'
            '  <div class="maq-topo">\n'
            '    <span class="nota">lido uma vez e guardado; nada aqui é do trabalho em curso.</span>\n'
            '    <button class="maquina-reler miudo">reler</button>\n'
            '  </div>\n'
            '  <div id="instrumentos-corpo"></div>\n'
            '  <h2>o quadro das caixas</h2>\n'
            '  <div id="caixas-corpo"><p class="nota">abra a aba para ler — o quadro custa rede.</p></div>\n'
            '  <p class="falta">Esta aba mostra o que as rotas <b>/maquina</b> e\n'
            '  <b>/caixas</b> medem: servidores MCP, rotinas agendadas e as linhas das\n'
            '  caixas permanentes, com poda por linha. As rotinas de verificação com botão\n'
            '  e o instalador esperam rota que os sirva — a fatia seguinte é que os traz.</p>\n'
            '</section>\n'
            '\n'
            '<section class="folha" id="folha-prompts" hidden>\n'
            '  <h2>prompts &amp; skills</h2>\n'
            '  <div class="maq-topo">\n'
            '    <span class="nota">lido uma vez e guardado; nada aqui é do trabalho em curso.</span>\n'
            '    <button class="maquina-reler miudo">reler</button>\n'
            '  </div>\n'
            '  <div id="prompts-corpo"></div>\n'
            '  <p class="falta">Esta aba mostra o que a rota <b>/maquina</b> já mede: o guia\n'
            '  do executor de roteiros e as skills lidas do disco, com o para-quê de cada\n'
            '  uma. Os prompts de abertura, com abrir no editor e copiar, esperam rota que\n'
            '  os sirva — nenhuma existe hoje.</p>\n'
            '</section>\n'
            '\n'
            '<section class="folha" id="folha-nucleo" hidden>\n'
            '  <h2>configurações</h2>\n'
            '  <dl class="coord">\n'
            '    <dt>repositório</dt><dd id="repositorio">—</dd>\n'
            '    <dt>sessão</dt><dd id="alvo">—</dd>\n'
            '    <dt>evidências</dt><dd id="evidencias">—</dd>\n'
            '    <dt>modo</dt><dd id="modo-lido">—</dd>\n'
            '    <dt>auditar ao fim</dt><dd id="auditoria-lida">—</dd>\n'
            '    <dt>narração</dt><dd>chaves <code>notificacao.ferramenta</code> ("desktop" usa a notificação do sistema), <code>notificacao.tipos</code> e <code>notificacao.silencio</code> (HH:MM-HH:MM) no executor.json — o mudo do cabeçalho cala na hora, sem pausar execução</dd>\n'
            '  </dl>\n'
            '  <div class="maq-topo">\n'
            '    <span class="nota">desligar derruba só a mesa: execução viva sobrevive e segue gravando evidência.</span>\n'
            '    <button id="desligar" class="miudo" title="POST /desligar — servidor.shutdown()">desligar a mesa</button>\n'
            '  </div>\n'
            '  <div class="maq-topo">\n'
            '    <span class="nota">o exemplo público contra o arquivo desta máquina: só o nome do que falta.</span>\n'
            '    <button class="maquina-reler miudo">reler</button>\n'
            '  </div>\n'
            '  <div id="nucleo-corpo"></div>\n'
            '  <p class="falta">Esta aba mostra o que as rotas <b>/trabalhos</b> e\n'
            '  <b>/maquina</b> já medem: onde a mesa está apoiada, o modo do executor de\n'
            '  roteiros, a auditoria gravada e as chaves de configuração que esta máquina\n'
            '  não preencheu. Abrir cada arquivo do núcleo no editor espera rota que\n'
            '  sirva — nenhuma existe hoje.</p>\n'
            '</section>\n'
            '</div>\n'
            '</div>\n'
            '<script>\n'
            'const $=i=>document.getElementById(i);\n'
            "let atual=null, assinatura='', parado=false, ultimoQuadro={};\n"
            'let ultimaConta={}, tempoLidoEm=0;\n'
            '\n'
            '/* a lógica da mesa entra aqui */\n'
            '\n'
            "const ESTADOS={'aguardando-aprovacao':['f-pergunta','esperando você'],\n"
            "  'parada':['f-para','parada'],'completa':['f-segue','completa'],\n"
            "  'em-curso':['f-corre','executando'],'dormindo':['f-corre','dormindo']};\n"
            "const TITULOS={'aguardando-aprovacao':'❓ ESPERANDO VOCÊ','parada':'⛔ parada',\n"
            "  'completa':'✓ completa','em-curso':'⏳ executando'};\n"
            '\n'
            "function modoRoteiro(){return $('modo').value!=='prompt'}\n"
            '\n'
            'let ROTINAS={};\n'
            'function ajusta(){\n'
            '  const m=modoRoteiro();\n'
            "  for(const i of ['p','lteto','lturnos'])$(i).style.display=m?'none':'';\n"
            "  const cx=$('oquefaz'), texto=m?(ROTINAS[$('modo').value]||''):'';\n"
            '  cx.textContent=texto; cx.hidden=!texto;\n'
            "  $('dica').textContent=m\n"
            "    ?'execução de várias etapas — o prompt de cada uma está dentro do arquivo'\n"
            "    :'vira uma execução de uma etapa mais a verificação. Turnos de menos = a sessão morre sem entregar nada';\n"
            '}\n'
            '\n'
            '// Mesa sem execução: o palco convida, em vez de ficar em branco.\n'
            'const CONVITE=\'<div class="recado"><b>mesa sem execução</b>\'\n'
            "  +'Nada para acompanhar. Execute uma issue da fila ao lado, ou escreva '\n"
            "  +'um pedido — a fita de evidências aparece aqui.</div>';\n"
            '\n'
            '// A FAIXA responde "preciso agir?" em qualquer estado, e carrega a ÚNICA\n'
            '// ação principal da tela. Texto curto de propósito: três segundos.\n'
            'function faixa(estado){\n'
            "  const [cls,txt]=ESTADOS[estado]||['','ocioso'];\n"
            "  $('faixa').className='faixa '+cls; $('farol-txt').textContent=txt;\n"
            "  document.title=(TITULOS[estado]?TITULOS[estado]+' · ':'')+'Mesa do executor de roteiros';\n"
            '  const backlog=(ultimoQuadro.issues||[]);\n'
            '  const casos={\n'
            "    'aguardando-aprovacao':['sim — responda a pergunta.','Responder',()=>rolarAte('heroi')],\n"
            "    'parada':['sim — leia a falta e decida.','Ler a falta',()=>rolarAte('saida')],\n"
            "    'em-curso':['não — acompanhe; a etapa atual ainda escreve.','Acompanhar',()=>rolarAte('saida')],\n"
            "    'dormindo':['não — o motor dorme e volta sozinho.','Acompanhar',()=>rolarAte('saida')],\n"
            '  };\n'
            '  let par=casos[estado];\n'
            '  if(!par)par=backlog.length\n'
            "    ?['sim — a fila tem trabalho.','Executar a primeira da fila',()=>executarIssue(backlog[0].number)]\n"
            "    :['sim — escreva um pedido.','Escrever um pedido',abrirPedido];\n"
            "  $('devo').textContent='preciso agir? '+par[0];\n"
            "  const a=$('acao'); a.hidden=false; a.textContent=par[1]; a.onclick=par[2];\n"
            '}\n'
            '// AS CINCO ABAS. Só uma fica sem [hidden], e a barra marca a própria linha.\n'
            '// A escolhida vive no endereço para o F5 devolver quem olha onde ele estava.\n'
            '// A máquina custa rede, então só se lê quando a aba que a mostra abre.\n'
            "const ABAS=['mesa','execucoes','instrumentos','prompts','nucleo'];\n"
            "const ABAS_QUE_LEEM_A_MAQUINA=['instrumentos','prompts','nucleo'];\n"
            'function irPara(aba){\n'
            '  if(!ABAS.includes(aba))aba=ABAS[0];\n'
            '  for(const a of ABAS){\n'
            "    $('folha-'+a).hidden=(a!==aba);\n"
            "    $('aba-'+a).classList.toggle('atual',a===aba);\n"
            '  }\n'
            '  if(location.hash.slice(1)!==aba)location.hash=aba;\n'
            '  if(ABAS_QUE_LEEM_A_MAQUINA.includes(aba)&&!maquinaLida)maquina(false);\n'
            '}\n'
            '\n'
            '// A faixa aponta para peças que moram na aba Mesa: levar até lá é parte de\n'
            '// chegar nelas — rolar até um elemento escondido não move nada.\n'
            "function rolarAte(id){irPara('mesa');const el=$(id);if(el)el.scrollIntoView({behavior:'smooth'})}\n"
            "function abrirPedido(){irPara('execucoes');const cx=$('p');cx.focus()}\n"
            '\n'
            '// A fila de execuções: linhas de 44px, clique acompanha. A fila nunca cai\n'
            '// num avulso por conta própria — sem escolha, vale o padrão do servidor.\n'
            "const SELOS={'dormindo':'💤','aguardando-resposta':'⏸',\n"
            "  'aguardando-aprovacao':'❓','completa':'✅','parada':'❌','rodando':'⏳'};\n"
            'function pintaFila(lista){\n'
            "  const alvo=$('execucoes');\n"
            "  const chave=lista.map(x=>x.nome+(x.situacao||'')+(x.nome===atual?'*':'')\n"
            "    +((ultimaConta[x.nome]||{}).usd||'')).join('|');\n"
            '  if(alvo.dataset.chave===chave)return;\n'
            '  alvo.dataset.chave=chave;\n'
            "  const custoDe=x=>{const c=ultimaConta[x.nome];if(!c||!c.usd)return '';\n"
            "    const etapas=Object.entries(c.etapas||{}).map(([e,v])=>e+': US$ '+v).join('\\\\n');\n"
            '    return `<span class="selo-s mono-n" title="${esc(etapas)}">US$ ${c.usd.toFixed(2)}</span>`};\n'
            '  alvo.innerHTML=lista.map(x=>\n'
            '    `<button class="linha-t${x.nome===atual?\' atual\':\'\'}" data-n="${esc(x.nome)}">\n'
            '      <span>${esc(x.nome)}</span>\n'
            '      ${x.issue?`<span class="selo-s">#${x.issue}</span>`:\'\'}\n'
            '      <span class="selo-s">${SELOS[x.situacao]||\'\'} ${esc(x.situacao||\'avulsa\')}</span>\n'
            '      ${custoDe(x)}\n'
            '      ${x.situacao===\'parada\'?`<span class="retomar-1" data-n="${esc(x.nome)}" title="retoma do ponto de retomada — etapa provada não se repete">retomar</span>`:\'\'}\n'
            "    </button>`).join('')\n"
            '    ||\'<p class="nota">nenhuma execução ainda.</p>\';\n'
            "  alvo.querySelectorAll('.linha-t').forEach(el=>el.onclick=()=>{\n"
            "    atual=el.dataset.n;assinatura='';ciclo()});\n"
            '  // Retomar em um clique: a linha parada carrega o próprio botão. O clique\n'
            '  // não abre a linha — retoma.\n'
            "  alvo.querySelectorAll('.retomar-1').forEach(el=>el.onclick=async ev=>{\n"
            '    ev.stopPropagation();\n'
            "    let r; try{ r=await (await fetch('/retomar',{method:'POST',\n"
            "      headers:{'Content-Type':'application/json'},\n"
            '      body:JSON.stringify({trabalho:el.dataset.n})})).json() }\n'
            '    catch(e){ r={erro:String(e)} }\n'
            "    if(r.erro)alert(r.erro); else {atual=el.dataset.n;assinatura='';ciclo()}\n"
            '  });\n'
            '}\n'
            '\n'
            '// O que o repintar não pode apagar: a caixa de log que você abriu. A mesa\n'
            '// guarda o estado dela aqui fora, porque lá dentro o elemento é recriado.\n'
            'let logAberto=false;\n'
            'function pinta(d){\n'
            "  $('saida').innerHTML=corpoDaMesa(d,logAberto);\n"
            "  const cauda=$('saida').querySelector('.agora-cauda');\n"
            '  if(cauda)cauda.scrollTop=cauda.scrollHeight;\n'
            "  const log=$('saida').querySelector('details.log');\n"
            '  if(log)log.ontoggle=()=>{logAberto=log.open};\n'
            '  ligarHeroi(d);\n'
            '}\n'
            '\n'
            '// O herói responde pelo dono: Aprovar retoma com "Aprovado." (ou com o que\n'
            '// estiver escrito); Devolver exige o recado. O placar dos critérios da issue\n'
            '// chega por /criterios e fica ao lado dos botões — nomeado, não somado.\n'
            'function ligarHeroi(d){\n'
            "  const ap=$('aprovar'); if(!ap)return;\n"
            "  ap.onclick=()=>responder((($('resposta')||{}).value||'').trim()||'Aprovado.',false);\n"
            "  $('devolver').onclick=()=>{\n"
            "    const r=(($('resposta')||{}).value||'').trim();\n"
            "    if(!r){$('resposta').focus();return}\n"
            '    responder(r,true);\n'
            '  };\n'
            '  pintaPlacar(d.trabalho);\n'
            '}\n'
            'async function pintaPlacar(t){\n'
            "  const alvo=$('placar'); if(!alvo)return;\n"
            '  let c; try{\n'
            "    c=await (await fetch('/criterios?trabalho='+encodeURIComponent(t||''))).json();\n"
            "  }catch(e){alvo.textContent='critérios da issue: não medi';return}\n"
            "  if(c.recado){alvo.textContent='critérios da issue: '+c.recado;return}\n"
            '  const feitos=c.total-(c.abertos||[]).length;\n'
            '  alvo.innerHTML=`<b>${feitos} de ${c.total}</b> critérios da issue com prova`\n'
            '    +((c.abertos||[]).length\n'
            "      ?` — faltam, nomeados:<ul>${c.abertos.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`\n"
            "      :' — todos.');\n"
            '}\n'
            'async function responder(texto,devolver){\n'
            "  const botoes=[$('aprovar'),$('devolver')].filter(Boolean);\n"
            '  botoes.forEach(b=>b.disabled=true);\n'
            '  let d; try{\n'
            "    d=await (await fetch('/responder',{method:'POST',\n"
            "      headers:{'content-type':'application/json'},\n"
            '      body:JSON.stringify({trabalho:atual,resposta:texto,devolver:!!devolver})})).json();\n'
            '  }catch(e){botoes.forEach(b=>b.disabled=false);return}\n'
            '  botoes.forEach(b=>b.disabled=false);\n'
            "  if(d.erro){$('saida').insertAdjacentHTML('afterbegin',\n"
            '    `<div class="recado ruim"><b>${devolver?\'não devolvi\':\'não retomei\'}</b>${esc(d.erro)}</div>`);return}\n'
            "  if(d.registro){$('saida').insertAdjacentHTML('afterbegin',\n"
            '    `<div class="recado"><b>${devolver?\'devolvido\':\'retomando\'}</b>${esc(d.registro)}</div>`)}\n'
            "  assinatura=''; ciclo();\n"
            '}\n'
            '\n'
            'async function ciclo(regarrado){\n'
            "  let d; try{ d=await (await fetch('/estado?trabalho='+encodeURIComponent(atual||''))).json() }\n"
            '  catch(e){ return }\n'
            "  $('versao').textContent='camada '+d.versao;\n"
            "  $('repositorio').textContent=d.repositorio; $('alvo').textContent=d.alvo;\n"
            "  $('evidencias').textContent=d.evidencias;\n"
            "  $('modo-lido').textContent=d.modo||'completo';\n"
            "  $('auditoria-lida').textContent=d.auditoria?'ligada':'desligada';\n"
            '  ultimoQuadro=d.quadro||{};\n'
            '\n'
            '  // O sino: quantos trabalhos param em você. Mudo cala a narração na\n'
            '  // hora e NUNCA pausa execução — a regra dura da F3.\n'
            "  const PARAM_EM_VOCE=['parada','aguardando-resposta','aguardando-aprovacao'];\n"
            '  const sinoN=d.trabalhos.filter(x=>PARAM_EM_VOCE.includes(x.situacao)).length;\n'
            "  $('sino-n').textContent=sinoN; $('sino').hidden=!sinoN;\n"
            "  $('selo-leitura').hidden=!d.so_leitura;\n"
            '\n'
            '  // O custo é coluna de primeira classe: por execução na fila, soma do\n'
            '  // dia na faixa. O número nasce dos registros do executor, nunca da mesa.\n'
            '  ultimaConta=(d.conta&&d.conta.por_trabalho)||{};\n'
            '  const somaDia=(d.conta&&d.conta.dia_usd)||0;\n'
            "  $('conta-dia').hidden=!somaDia;\n"
            "  $('conta-dia').textContent='US$ '+somaDia.toFixed(2)+' hoje';\n"
            '\n'
            "  const cs=d.containers||{}, chip=$('containers');\n"
            "  if(cs.recado){chip.hidden=false;chip.textContent='containers: não medidos';\n"
            '    chip.title=cs.recado}\n'
            '  else if((cs.itens||[]).length){chip.hidden=false;\n'
            '    chip.innerHTML=cs.itens.map(c=>\'<span class="\'+(c.de_pe?\'depe\':\'caido\')+\'">\'\n'
            "      +(c.de_pe?'●':'○')+' '+esc(c.nome)+'</span>').join(' ');\n"
            "    chip.title='containers deste workspace — '\n"
            "      +cs.itens.map(c=>c.nome+': '+c.estado).join(' · ')}\n"
            '  else chip.hidden=true;\n'
            '  if(Date.now()-tempoLidoEm>30000){tempoLidoEm=Date.now();pintaTempo()}\n'
            '\n'
            "  const mu=$('mudo');\n"
            "  mu.textContent=d.muda?'mudo':'som';\n"
            "  mu.classList.toggle('muda',!!d.muda);\n"
            "  mu.onclick=async()=>{try{await fetch('/mudo',{method:'POST',\n"
            "    headers:{'Content-Type':'application/json'},\n"
            '    body:JSON.stringify({ligado:!d.muda})})}catch(e){} ciclo()};\n'
            '\n'
            '  // O seletor de roteiro fala português: o rótulo é o título vindo da\n'
            '  // descrição, nunca o nome do arquivo.\n'
            "  const md=$('modo'), antesM=md.value, rot=d.rotinas||[];\n"
            "  const chaveM=rot.map(r=>r.nome).join('|');\n"
            '  if(md.dataset.chave!==chaveM){\n'
            '    md.dataset.chave=chaveM;\n'
            '    md.innerHTML=\'<option value="prompt">um pedido meu</option>\'\n'
            '      +rot.map(r=>`<option value="${esc(r.nome)}">${esc(r.titulo||r.nome)}</option>`).join(\'\');\n'
            '    if(antesM)md.value=antesM;\n'
            '  }\n'
            '  ROTINAS={}; for(const r of rot)ROTINAS[r.nome]=r.descricao;\n'
            "  const au=$('auditoria');\n"
            '  if(au&&!au.dataset.tocado)au.checked=!!d.auditoria;\n'
            '  ajusta();\n'
            '\n'
            '  // A fila de issues: cada linha EXECUTA em um clique — com três recusas\n'
            '  // da triagem: issue com execução viva não tem botão, caixa permanente é\n'
            '  // quadro e não se executa, e issue de outro projeto vai separada com a\n'
            '  // etiqueta dela.\n'
            "  const q=$('quadro');\n"
            '  const qs=(d.quadro&&d.quadro.issues)||[];\n'
            '  const caixasN=d.caixas_numeros||[], declarados=d.projetos_declarados||[];\n'
            '  const vivas=new Set(d.trabalhos\n'
            "    .filter(x=>['rodando','dormindo','aguardando-resposta','aguardando-aprovacao'].includes(x.situacao))\n"
            '    .map(x=>String(x.issue)));\n'
            "  const chave=JSON.stringify(qs)+(d.modo||'')+caixasN.join()+[...vivas].join()+(d.projeto_do_alvo||'');\n"
            '  if(q.dataset.chave!==chave){\n'
            '    q.dataset.chave=chave;\n'
            "    const soIssues=d.modo==='so-issues';\n"
            '    const etiquetaDe=i=>(i.labels||[]).find(l=>declarados.includes(l));\n'
            '    const linha=i=>{\n'
            '      const caixa=caixasN.includes(i.number), viva=vivas.has(String(i.number));\n'
            '      const etiqueta=etiquetaDe(i);\n'
            '      return `<div class="linha-i${caixa?\' caixa-fixa\':\'\'}"><span class="num">#${i.number}</span>\n'
            '        <span class="tit" title="${esc(i.title)}">${esc(i.title)}</span>\n'
            '        ${etiqueta?`<span class="selo-s">${esc(etiqueta)}</span>`:\'\'}\n'
            '        ${caixa?\'<span class="selo-s">caixa — não se executa</span>\':\'\'}\n'
            '        ${viva?\'<span class="selo-s">em execução</span>\':\'\'}\n'
            '        ${(soIssues||caixa||viva)?\'\':`<button class="executar-issue" data-n="${i.number}">executar</button>`}\n'
            '       </div>`};\n'
            '    const daCasa=qs.filter(i=>{const e=etiquetaDe(i);return !e||e===d.projeto_do_alvo});\n'
            '    const deFora=qs.filter(i=>{const e=etiquetaDe(i);return e&&e!==d.projeto_do_alvo});\n'
            '    q.innerHTML=qs.length\n'
            "      ? daCasa.map(linha).join('')\n"
            '        +(deFora.length?\'<div class="quadro-topo">outros projetos</div>\'+deFora.map(linha).join(\'\'):\'\')\n'
            '      : `<div class="quadro-topo">${esc((d.quadro||{}).recado||\'nenhuma issue aberta\')}</div>`;\n'
            "    q.querySelectorAll('.executar-issue').forEach(b=>b.onclick=()=>executarIssue(+b.dataset.n));\n"
            '  }\n'
            '\n'
            '  // Trabalho terminado sai da lista padrão: mesa com trinta itens mortos\n'
            '  // esconde o que está vivo. O histórico continua a um clique.\n'
            "  const tudo=$('historico')&&$('historico').checked;\n"
            '  const lista=tudo?d.trabalhos\n'
            "    :d.trabalhos.filter(x=>!['completa','parada'].includes(x.situacao));\n"
            '  const nomes=lista.map(x=>x.nome);\n'
            '  if(!atual||!nomes.includes(atual))atual=d.padrao||null;\n'
            '  pintaFila(lista);\n'
            '\n'
            '  // Com uma execução no ar, o botão de executar FECHA. A trava por alvo\n'
            '  // recusaria a segunda, mas deixar o botão vivo é convidar para o erro.\n'
            "  const EM_CURSO=['rodando','dormindo','aguardando-resposta'];\n"
            '  const ocupada=d.trabalhos.filter(x=>EM_CURSO.includes(x.situacao));\n'
            "  const b=$('b');\n"
            '  if(b){\n'
            '    b.disabled=ocupada.length>0;\n'
            '    b.title=ocupada.length\n'
            '      ? `${ocupada[0].nome} está no ar (${ocupada[0].situacao}) — a trava do alvo recusaria uma segunda execução`\n'
            "      : '';\n"
            "    b.textContent=ocupada.length?'No ar…':'Executar';\n"
            '  }\n'
            '\n'
            '  const a=d.andamento;\n'
            '  // Primeira pintura com execução no ar: o padrão acabou de chegar e o\n'
            '  // andamento ainda não veio — busca de novo UMA vez, em vez de piscar o\n'
            '  // convite de mesa vazia por 2,5s em cima de trabalho vivo.\n'
            '  if(!a&&atual&&!regarrado)return ciclo(true);\n'
            "  if(!a){assinatura='';$('saida').innerHTML=CONVITE;faixa(undefined);return}\n"
            '  if(!nomes.includes(atual)||!d.trabalhos.find(x=>x.nome===atual&&x.execucao)){\n'
            '    $(\'saida\').innerHTML=`<div class="recado"><b>fora do executor de roteiros</b>\n'
            "      <code>${esc(atual||'')}</code> é trilha de evidências avulsas — de um gancho, por\n"
            '      exemplo —, sem roteiro ao lado. Lida como execução daria estado falso,\n'
            '      então a mesa não opina.</div>`; faixa(undefined); return;\n'
            '  }\n'
            '  faixa(a.erro?undefined:a.estado);\n'
            '  // Só repinta quando algo mudou: a mesa fica aberta por horas e repintar\n'
            '  // HTML a cada 2,5s por nada custa bateria e derruba texto selecionado.\n'
            '  const nova=JSON.stringify(a);\n'
            '  if(nova!==assinatura){assinatura=nova; pinta(a)}\n'
            "  parado=a.processo!=='rodando';\n"
            '}\n'
            '\n'
            '// Executar a partir de uma issue da fila: UM clique, sem formulário.\n'
            'async function executarIssue(n){\n'
            '  await mandar({prompt:`Trabalhe a issue #${n}: leia o corpo dela e siga o `\n'
            '      +`prompt refinado que estiver lá.`,\n'
            "    teto:+$('teto').value||3,turnos:+$('turnos').value||24,issue:n,\n"
            "    auditoria:$('auditoria').checked});\n"
            '}\n'
            '\n'
            'async function executar(){\n'
            "  $('auditoria').dataset.tocado='1';\n"
            "  const corpo=modoRoteiro()?{roteiro:$('modo').value,auditoria:$('auditoria').checked,issue:+$('issue').value||null}\n"
            "    :{prompt:$('p').value.trim(),teto:+$('teto').value,turnos:+$('turnos').value,issue:+$('issue').value||null,auditoria:$('auditoria').checked};\n"
            '  if(!modoRoteiro()&&!corpo.prompt){abrirPedido();return}\n'
            '  await mandar(corpo);\n'
            '}\n'
            '\n'
            'async function mandar(corpo){\n'
            "  const b=$('b'); b.disabled=true; b.textContent='Executando…';\n"
            '  let d; try{\n'
            "    d=await (await fetch('/disparar',{method:'POST',\n"
            "      headers:{'content-type':'application/json'},body:JSON.stringify(corpo)})).json();\n"
            "  } finally { b.disabled=false; b.textContent='Executar' }\n"
            '  if(d.erro){$(\'saida\').innerHTML=`<div class="recado ruim"><b>não executei</b>${esc(d.erro)}</div>`;return}\n'
            "  atual=d.trabalho; assinatura=''; ciclo();\n"
            '}\n'
            '\n'
            '// Medido e vazio é um FATO; não medido é confissão. A tela separa os dois,\n'
            '// porque lista vazia com cara de resposta é o engano mais barato de acreditar.\n'
            'function blocoDeLista(titulo,d,linha){\n'
            "  const cabeca='<h3>'+esc(titulo)+'</h3>';\n"
            '  if(!d) return cabeca+\'<p class="naomedido">não medido: o painel de controle não recebeu este bloco.</p>\';\n'
            '  if(d.recado) return cabeca+\'<p class="naomedido">\'+esc(d.recado)+\'</p>\';\n'
            "  if(!d.itens||!d.itens.length) return cabeca+'<p>nenhum — e isto foi medido.</p>';\n"
            "  return cabeca+'<ul>'+d.itens.map(linha).join('')+'</ul>';\n"
            '}\n'
            '\n'
            '// A máquina chega numa leitura só e se reparte entre duas abas: o que está\n'
            '// de pé aqui fora vai para Instrumentos, e o que se lê do disco vai para\n'
            '// Prompts & skills.\n'
            'function pintaInstrumentos(d){\n'
            '  return \'<div class="maq">\'\n'
            "    +blocoDeLista('servidores MCP',d.mcp,\n"
            '      s=>\'<li><b>\'+esc(s.nome)+\'</b> <span class="\'+(s.de_pe?\'depe\':\'caido\')+\'">\'\n'
            "        +esc(s.estado)+'</span><br><span>'+esc(s.alvo)+'</span></li>')\n"
            "    +blocoDeLista('rotinas deste workspace',d.rotinas,\n"
            "      r=>'<li><b>'+esc(r.unidade)+'</b> <span>'+esc(r.ativa)+'</span><br><span>'\n"
            "        +esc(r.descricao)+'</span><br><span>próxima: '+esc(r.proxima||'—')\n"
            "        +' · última: '+esc(r.ultima||'—')+'</span></li>')\n"
            "    +((d.rotinas&&d.rotinas.de_fora)?'<p>e '+d.rotinas.de_fora\n"
            "      +' agendamento(s) do sistema operacional, que não são deste workspace.</p>':'')\n"
            "    +'</div>';\n"
            '}\n'
            '\n'
            'function pintaPromptsESkills(d){\n'
            "  const guia=(d.guia||[]).map(p=>'<li><b>'+esc(p.titulo)+'</b><br><span>'+esc(p.corpo)+'</span></li>').join('');\n"
            '  return \'<div class="maq">\'\n'
            "    +'<h3>como usar</h3><ul>'+guia+'</ul>'\n"
            "    +blocoDeLista('skills desta máquina',d.skills,\n"
            "      s=>'<li><b>'+esc(s.nome)+'</b><br><span>'+esc(s.descricao)+'</span></li>')\n"
            "    +'</div>';\n"
            '}\n'
            '\n'
            'let maquinaLida=false;\n'
            '// A linha do tempo do dia: uma raia por execução, um bloco por etapa\n'
            '// gravada hoje. O início de um bloco é o fim do anterior — o primeiro do\n'
            '// dia não tem largura conhecida e vira um traço. Clique abre o log.\n'
            'async function pintaTempo(){\n'
            "  const alvo=$('tempo-raias');\n"
            "  let d; try{ d=await (await fetch('/linha-do-tempo')).json() }catch(e){ return }\n"
            '  const raias=(d.raias||[]).filter(r=>r.blocos.length||r.marcas.length);\n'
            '  if(!raias.length){alvo.innerHTML=\'<p class="nota">nenhuma etapa gravada hoje.</p>\';return}\n'
            '  const ts=s=>s?new Date(s).getTime():null;\n'
            '  let min=Infinity,max=-Infinity;\n'
            '  for(const r of raias)for(const b of r.blocos){\n'
            '    const f=ts(b.fim),i=ts(b.inicio);\n'
            '    if(f){min=Math.min(min,i||f);max=Math.max(max,f)}\n'
            '  }\n'
            '  for(const r of raias)for(const m of r.marcas){\n'
            '    const q=ts(m.quando); if(q){min=Math.min(min,q);max=Math.max(max,q)}\n'
            '  }\n'
            '  const larg=Math.max(max-min,60000);\n'
            "  const pct=t=>((t-min)/larg*100).toFixed(2)+'%';\n"
            '  alvo.innerHTML=raias.map(r=>\n'
            '    \'<div class="raia"><span class="raia-nome">\'+esc(r.trabalho)+\'</span><div class="raia-faixa">\'\n'
            '    +r.blocos.map(b=>{\n'
            '      const f=ts(b.fim),i=ts(b.inicio)||f-30000;\n'
            '      return \'<span class="bloco" style="left:\'+pct(i)+\';width:\'\n'
            '        +Math.max((f-i)/larg*100,0.6).toFixed(2)+\'%"\'\n'
            '        +(b.log?\' data-t="\'+esc(r.trabalho)+\'" data-l="\'+esc(b.log)+\'"\':\'\')\n'
            '        +\' title="\'+esc(b.etapa)+(b.ciclo?\' (ciclo \'+b.ciclo+\')\':\'\')\n'
            '        +\' — fim \'+esc((b.fim||\'\').slice(11,19))+\'">\'+esc(b.etapa)+\'</span>\'}).join(\'\')\n'
            '    +r.marcas.map(m=>{const q=ts(m.quando);return q?\'<span class="marca" style="left:\'\n'
            '      +pct(q)+\'" title="\'+esc(m.tipo)+\' desde \'+esc(m.quando.slice(11,19))+\'"></span>\':\'\'}).join(\'\')\n'
            "    +'</div></div>').join('');\n"
            "  alvo.querySelectorAll('.bloco[data-l]').forEach(el=>el.onclick=async()=>{\n"
            "    let texto; try{ texto=await (await fetch('/log-da-etapa?trabalho='\n"
            "      +encodeURIComponent(el.dataset.t)+'&arquivo='+encodeURIComponent(el.dataset.l))).text() }\n"
            '    catch(e){ texto=String(e) }\n'
            "    $('tempo-log').hidden=false; $('tempo-log-texto').textContent=texto;\n"
            '  });\n'
            '}\n'
            '\n'
            '// O quadro das caixas: linhas com tipo/id/visto-em e a poda por linha.\n'
            '// Poda pede o motivo — sem registro do fechamento, o caixa.py recusa.\n'
            'async function pintaCaixas(){\n'
            "  const alvo=$('caixas-corpo');\n"
            "  let d; try{ d=await (await fetch('/caixas')).json() }\n"
            '  catch(e){ alvo.innerHTML=\'<p class="naomedido">não medido: \'+esc(e)+\'</p>\'; return }\n'
            '  const blocos=(d.caixas||[]).map(c=>\n'
            '    \'<div class="maq"><b>#\'+c.numero+\' \'+esc(c.titulo)+\'</b>\'\n'
            '    +(c.linhas.length?c.linhas.map(l=>\n'
            '      \'<div class="linha-i"><span class="selo-s">\'+esc(l.tipo)+\'</span>\'\n'
            '      +\'<span class="num">\'+esc(l.id)+\'</span>\'\n'
            '      +\'<span class="tit" title="\'+esc(l.texto)+\'">\'+esc(l.texto)+\'</span>\'\n'
            '      +(l.visto?\'<span class="selo-s">visto \'+esc(l.visto)+\'</span>\':\'\')\n'
            '      +\'<button class="podar-linha miudo" data-id="\'+esc(l.id)+\'">podar</button>\'\n'
            "      +'</div>').join('')\n"
            '      :\'<p class="nota">quadro vazio.</p>\')\n'
            "    +'</div>').join('');\n"
            '  alvo.innerHTML=(d.recado?\'<p class="nota">\'+esc(d.recado)+\'</p>\':\'\')\n'
            "    +(blocos||'');\n"
            "  alvo.querySelectorAll('.podar-linha').forEach(b=>b.onclick=async()=>{\n"
            "    const motivo=prompt('o motivo do fechamento — o commit, a medição ou a issue que a fechou:');\n"
            '    if(!motivo)return;\n'
            "    b.disabled=true; b.textContent='podando…';\n"
            "    let r; try{ r=await (await fetch('/podar',{method:'POST',\n"
            "      headers:{'Content-Type':'application/json'},\n"
            '      body:JSON.stringify({id:b.dataset.id,motivo})})).json() }\n'
            '    catch(e){ r={erro:String(e)} }\n'
            "    alert(r.erro||r.saida||'sem saída');\n"
            '    pintaCaixas();\n'
            '  });\n'
            '}\n'
            '\n'
            'async function maquina(reler){\n'
            '  pintaCaixas();\n'
            "  const onde={'instrumentos-corpo':pintaInstrumentos,'prompts-corpo':pintaPromptsESkills,\n"
            "    'nucleo-corpo':d=>pintaConfiguracao(d.configuracao)};\n"
            '  for(const id in onde)\n'
            '    $(id).innerHTML=\'<p class="nota">lendo — o estado dos servidores custa rede.</p>\';\n'
            '  try{\n'
            "    const d=await (await fetch('/maquina'+(reler?'?reler=1':''))).json();\n"
            '    for(const id in onde)$(id).innerHTML=onde[id](d);\n'
            '    maquinaLida=true;\n'
            '  }catch(e){\n'
            '    for(const id in onde)\n'
            '      $(id).innerHTML=\'<div class="maq"><p class="naomedido">não medido: \'+esc(e)+\'</p></div>\';\n'
            '  }\n'
            '}\n'
            '\n'
            "$('b').onclick=executar;\n"
            '// O pânico em dois passos: o primeiro clique arma, o segundo dispara.\n'
            '// Seis segundos sem o segundo clique desarmam sozinhos.\n'
            'let panicoArmado=null;\n'
            "$('panico').onclick=async()=>{\n"
            "  const p=$('panico');\n"
            '  if(!panicoArmado){\n'
            "    p.textContent='confirmar a parada?'; p.classList.add('armado');\n"
            "    panicoArmado=setTimeout(()=>{p.textContent='parada de emergência';\n"
            "      p.classList.remove('armado');panicoArmado=null},6000);\n"
            '    return;\n'
            '  }\n'
            '  clearTimeout(panicoArmado); panicoArmado=null;\n'
            "  p.textContent='parando…'; p.disabled=true;\n"
            "  let r; try{ r=await (await fetch('/panico',{method:'POST'})).json() }\n"
            '  catch(e){ r={erro:String(e)} }\n'
            "  p.textContent='parada de emergência'; p.classList.remove('armado');\n"
            '  p.disabled=false;\n'
            '  const linhas=(r.parados||[]).map(x=>\'<div class="linha-i"><span class="num">\'\n'
            '    +esc(x.trabalho)+\'</span><span class="tit">parada \'+esc(x.parada)\n'
            '    +\'</span><button class="retomar-panico" data-t="\'+esc(x.trabalho)\n'
            '    +\'">retomar</button></div>\').join(\'\');\n'
            '  $(\'saida\').innerHTML=\'<div class="recado"><b>relatório da parada de emergência</b>\'\n'
            "    +(r.erro?'<p>'+esc(r.erro)+'</p>':(linhas||'<p>nenhuma execução viva para parar.</p>'))\n"
            "    +'</div>';\n"
            "  irPara('mesa');\n"
            "  document.querySelectorAll('.retomar-panico').forEach(b=>b.onclick=()=>{\n"
            "    atual=b.dataset.t;irPara('execucoes');ciclo()});\n"
            '};\n'
            "$('desligar').onclick=async()=>{\n"
            "  if(!confirm('desligar a mesa? execução viva sobrevive.'))return;\n"
            "  try{await fetch('/desligar',{method:'POST'})}catch(e){}\n"
            '  document.body.innerHTML=\'<p style="padding:24px">mesa desligada — a execução viva, se havia, segue no processo dela.</p>\';\n'
            '};\n'
            "$('historico').onchange=()=>{assinatura='';ciclo()};\n"
            "$('modo').onchange=ajusta;\n"
            "for(const a of ABAS)$('aba-'+a).onclick=()=>irPara(a);\n"
            "window.addEventListener('hashchange',()=>irPara(location.hash.slice(1)));\n"
            "document.querySelectorAll('.maquina-reler').forEach(b=>b.onclick=()=>maquina(true));\n"
            'irPara(location.hash.slice(1));\n'
