            'SEPARADOR_DA_VOZ = "-"\n'
            '\n'
            'PACOTE_DO_MOTOR = "edge-tts"\n'
            'EXECUTAVEL_DO_MOTOR = "edge-tts"\n'
            'EXECUTAVEL_DO_PIP = "pip"\n'
            'PREFIXO_DO_AUDIO = "falar-"\n'
            'SUFIXO_DO_AUDIO = ".mp3"\n'
            'TETO_DO_ERRO = 400\n'
            '\n'
            'SISTEMA_WINDOWS = "Windows"\n'
            'SISTEMA_LINUX = "Linux"\n'
            'SISTEMA_MAC = "Darwin"\n'
            '\n'
            'PASTA_DOS_BINARIOS = {SISTEMA_WINDOWS: "Scripts"}\n'
